-- Schema for Domain: gridops | Business: Power and Utilities | Version: v1_ecm
-- Generated on: 2026-05-05 03:11:17

-- ========= DATABASE =========
CREATE DATABASE IF NOT EXISTS `power_and_utilities_v2`.`gridops` COMMENT 'Owns real-time and near-real-time grid operational data including SCADA monitoring, EMS dispatch, load forecasting, demand response (DR) dispatch, frequency regulation, voltage control, and outage management coordination. Manages balancing area control, switching orders, and reliability event logging. Integrates with OMS, DMS, PI Historian, and DERMS for operational intelligence.';

-- ========= TABLES =========
CREATE OR REPLACE TABLE `power_and_utilities_v2`.`gridops`.`balancing_area` (
    `balancing_area_id` BIGINT COMMENT 'Unique surrogate identifier for the balancing authority area (BAA) record in the lakehouse silver layer. Primary key for this master resource entity.',
    `abbreviation` STRING COMMENT 'Short-form abbreviation or acronym for the balancing authority area used in SCADA displays, EMS dispatch screens, and operational communications (e.g., MISO, PJM, SPP).. Valid values are `^[A-Z0-9]{2,8}$`',
    `agc_enabled` BOOLEAN COMMENT 'Indicates whether Automatic Generation Control (AGC) is active for this balancing area. AGC continuously adjusts generator output to maintain ACE within NERC BAL-001 limits. Critical flag for EMS dispatch configuration.',
    `area_sq_miles` DECIMAL(18,2) COMMENT 'Total geographic area of the balancing authority service territory in square miles. Used in infrastructure density analysis, storm response planning, and regulatory filings with state PUCs.',
    `area_type` STRING COMMENT 'Classification of the operational jurisdiction type. Distinguishes between a full NERC-registered balancing authority, a sub-control area operating under a parent BA, or a reserve sharing group. Drives dispatch logic and reliability obligation scope in the EMS.. Valid values are `balancing_authority|control_area|sub_control_area|reserve_sharing_group`',
    `balancing_area_name` STRING COMMENT 'Full legal or operational name of the balancing authority area as registered with NERC and recognized by FERC. Used in regulatory filings, RTO/ISO coordination, and operational reporting.',
    `cip_classification` STRING COMMENT 'NERC Critical Infrastructure Protection (CIP) impact classification for this balancing area as a bulk electric system (BES) cyber system. Drives cybersecurity control requirements under NERC CIP-002 through CIP-014 standards.. Valid values are `high|medium|low|not_applicable`',
    `control_area_ace_limit_mw` DECIMAL(18,2) COMMENT 'The maximum allowable Area Control Error (ACE) in megawatts for this balancing area, as defined in the NERC BAL-001 standard. ACE is the real-time difference between actual and scheduled interchange plus frequency bias. This limit drives EMS automatic generation control (AGC) setpoints.',
    `country_code` STRING COMMENT 'ISO 3166-1 alpha-3 country code for the primary country in which this balancing area operates (e.g., USA, CAN, MEX). Relevant for cross-border balancing areas and NERC international coordination.. Valid values are `^[A-Z]{3}$`',
    `created_timestamp` TIMESTAMP COMMENT 'The timestamp when this balancing area master record was first created in the system, in ISO 8601 format (yyyy-MM-ddTHH:mm:ss.SSSXXX). Supports data lineage, audit trail, and regulatory record retention requirements.',
    `demand_response_capacity_mw` DECIMAL(18,2) COMMENT 'Total enrolled demand response (DR) capacity in megawatts (MW) available within this balancing area for dispatch during peak demand or grid emergency events. Includes both direct load control and interruptible load programs.',
    `der_capacity_mw` DECIMAL(18,2) COMMENT 'Total nameplate capacity of distributed energy resources (DER) — including rooftop solar, battery storage, and small-scale generation — interconnected within this balancing area. Used in DERMS integration and load forecasting.',
    `effective_date` DATE COMMENT 'The date on which this balancing area record became operationally effective, including any boundary changes, restructuring events, or RTO/ISO membership transitions. Supports temporal analysis of balancing area configuration history.',
    `eia_ba_code` STRING COMMENT 'The EIA-assigned balancing authority code used in mandatory EIA Form 930 (Hourly Electric Grid Monitor) and EIA Form 411 submissions. Enables linkage between operational data and public EIA reporting.. Valid values are `^[A-Z0-9]{2,10}$`',
    `ems_system_code` STRING COMMENT 'The native identifier for this balancing area as configured in the GE PowerOn Advanced Energy Management System (EMS). Used for cross-referencing real-time operational data from the EMS with the lakehouse silver layer record.',
    `expiration_date` DATE COMMENT 'The date on which this balancing area record ceases to be effective, typically due to decommissioning, merger with another balancing authority, or transfer of operational control. Null for currently active areas.',
    `frequency_bias_mw_per_hz` DECIMAL(18,2) COMMENT 'The frequency bias setting for this balancing area expressed in megawatts per hertz (MW/Hz). This value is used in the ACE calculation formula and must be reported to NERC annually under BAL-003. Configured in the EMS AGC module.',
    `geographic_region` STRING COMMENT 'Descriptive geographic region or service territory description for the balancing area (e.g., Midwest, Pacific Northwest, Southeast). Used for operational reporting, regulatory filings, and GIS-based analysis in Esri ArcGIS.',
    `installed_capacity_mw` DECIMAL(18,2) COMMENT 'Total nameplate installed generation capacity in megawatts (MW) within the balancing area boundary. Represents the principal quantitative measure of the resource and is used in IRP filings, NERC reliability assessments, and reserve margin calculations.',
    `interchange_scheduling_method` STRING COMMENT 'The method used to schedule energy interchange transactions across the balancing area boundary. E-Tag indicates use of the NERC e-Tag system for electronic tagging of interchange. RTO-managed indicates the RTO/ISO controls interchange scheduling.. Valid values are `e-tag|manual|rto_managed|bilateral`',
    `interconnection` STRING COMMENT 'The North American AC synchronous interconnection to which this balancing area belongs. Determines frequency regulation obligations, emergency assistance protocols, and NERC reliability standards applicability.. Valid values are `eastern|western|ercot|alaska|hawaii`',
    `last_updated_timestamp` TIMESTAMP COMMENT 'The timestamp of the most recent modification to this balancing area master record, in ISO 8601 format (yyyy-MM-ddTHH:mm:ss.SSSXXX). Used for change tracking, data quality monitoring, and incremental lakehouse processing.',
    `latitude_centroid` DECIMAL(18,2) COMMENT 'Decimal latitude of the geographic centroid of the balancing area boundary polygon, in WGS84 coordinate reference system. Used for GIS visualization in Esri ArcGIS and spatial analytics.',
    `lmp_pricing_node_code` STRING COMMENT 'The RTO/ISO-assigned pricing node code for the primary Locational Marginal Price (LMP) settlement point associated with this balancing area. Used in Allegro ETRM for energy trading settlement and DAM/RTM position management.',
    `load_serving_entity_count` STRING COMMENT 'Number of load serving entities (LSEs) operating within this balancing area. Used in resource adequacy planning, reserve sharing agreements, and NERC reliability assessments.',
    `longitude_centroid` DECIMAL(18,2) COMMENT 'Decimal longitude of the geographic centroid of the balancing area boundary polygon, in WGS84 coordinate reference system. Used for GIS visualization in Esri ArcGIS and spatial analytics.',
    `market_participation` BOOLEAN COMMENT 'Indicates whether this balancing area participates in a wholesale energy market (Day-Ahead Market or Real-Time Market) operated by an RTO/ISO. True for market-participating areas; False for vertically integrated utilities operating outside organized markets.',
    `nerc_baa_code` STRING COMMENT 'The official NERC-assigned alphanumeric code uniquely identifying this balancing authority area within the North American bulk electric system. Used in NERC compliance filings, EIA-411 submissions, and interchange scheduling.. Valid values are `^[A-Z0-9]{2,10}$`',
    `nerc_registration_date` DATE COMMENT 'The date on which this balancing authority area was formally registered with NERC as a functional entity. Establishes the start of NERC reliability standard compliance obligations.',
    `nominal_frequency_hz` DECIMAL(18,2) COMMENT 'The nominal AC system frequency in hertz (Hz) for this balancing area (typically 60.000 Hz for North American interconnections). Used as the reference frequency for ACE calculations and frequency regulation compliance.',
    `operating_reserve_requirement_mw` DECIMAL(18,2) COMMENT 'The minimum operating reserve requirement in megawatts (MW) that must be maintained within this balancing area at all times, per NERC BAL-002 and applicable RTO/ISO tariff requirements. Includes both spinning and non-spinning reserves.',
    `operational_status` STRING COMMENT 'Current lifecycle state of the balancing area. Active indicates the area is fully operational and participating in real-time dispatch and frequency regulation. Transitioning indicates a merger, transfer, or restructuring is in progress.. Valid values are `active|inactive|suspended|transitioning|decommissioned`',
    `peak_load_mw` DECIMAL(18,2) COMMENT 'Historical or projected annual peak demand in megawatts (MW) for the balancing area. Used in reserve margin calculations, IRP planning, and NERC reliability assessments submitted to FERC and state PUCs.',
    `primary_frequency_regulation_mhz` DECIMAL(18,2) COMMENT 'The primary frequency response obligation assigned to this balancing area, expressed in megahertz (MHz) of frequency deviation response capability. Used in NERC BAL-003 compliance tracking and EMS frequency regulation dispatch.',
    `renewable_capacity_mw` DECIMAL(18,2) COMMENT 'Total nameplate capacity of renewable energy sources (wind, solar, hydro, geothermal) in megawatts (MW) within the balancing area. Used in REC tracking, IRP filings, and state renewable portfolio standard (RPS) compliance reporting.',
    `reserve_margin_pct` DECIMAL(18,2) COMMENT 'The required or actual planning reserve margin expressed as a percentage of peak load. Represents the buffer of generation capacity above peak demand required to maintain reliability. Reported in IRP filings and NERC assessments.',
    `rto_iso_membership` STRING COMMENT 'Name of the RTO or ISO within which this balancing area operates or is a member (e.g., PJM Interconnection, MISO, SPP, CAISO, ERCOT, NYISO, ISO-NE). Null if the utility operates as an independent balancing authority outside an RTO/ISO.',
    `saidi_target_minutes` DECIMAL(18,2) COMMENT 'The annual SAIDI performance target in minutes for this balancing area, representing the average total duration of interruptions per customer. Reported to state PUCs and used in reliability benchmarking.',
    `saifi_target` DECIMAL(18,2) COMMENT 'The annual SAIFI performance target for this balancing area, representing the average number of interruptions per customer per year. Reported to state PUCs and used in reliability benchmarking alongside SAIDI.',
    `scada_area_code` STRING COMMENT 'The SCADA system area code assigned to this balancing area in the operational technology environment. Used to correlate real-time telemetry from OSIsoft PI Historian with the balancing area master record for operational intelligence.. Valid values are `^[A-Z0-9_]{2,20}$`',
    `spinning_reserve_requirement_mw` DECIMAL(18,2) COMMENT 'The minimum spinning (synchronized) reserve requirement in megawatts (MW) for this balancing area. Spinning reserves must be online and capable of responding within 10 minutes per NERC BAL-002 standards.',
    `state_codes` STRING COMMENT 'Comma-separated list of two-letter US state abbreviations (e.g., OH,IN,MI) representing the states within or overlapping the balancing area boundary. Determines which state PUC jurisdictions apply for rate case filings and regulatory compliance.',
    `tie_line_count` STRING COMMENT 'Number of high-voltage transmission tie lines connecting this balancing area to adjacent balancing areas. Used in interchange scheduling, contingency analysis, and NERC CIP-014 physical security assessments.',
    `time_zone` STRING COMMENT 'The IANA time zone identifier for the primary operating time zone of this balancing area (e.g., America/Chicago, America/New_York). Used for scheduling, dispatch, and market settlement time alignment.',
    `transmission_operator_code` STRING COMMENT 'The NERC-assigned identifier of the Transmission Operator (TOP) responsible for operating the transmission facilities within this balancing area. May differ from the balancing authority in restructured markets.. Valid values are `^[A-Z0-9]{2,10}$`',
    `transmission_voltage_kv` DECIMAL(18,2) COMMENT 'The primary bulk electric system transmission voltage level in kilovolts (kV) for this balancing area (e.g., 345 kV, 500 kV, 765 kV). Defines the BES threshold and NERC CIP applicability scope.',
    CONSTRAINT pk_balancing_area PRIMARY KEY(`balancing_area_id`)
) COMMENT 'Master record for each balancing authority area (BAA) or control area managed by the utility, defining geographic and electrical boundaries, interchange schedules, and reliability obligations under NERC standards. Serves as the top-level operational jurisdiction for EMS dispatch and frequency regulation activities.';

CREATE OR REPLACE TABLE `power_and_utilities_v2`.`gridops`.`control_zone` (
    `control_zone_id` BIGINT COMMENT 'Unique surrogate identifier for the electrical control zone record within the balancing area. Primary key for this entity.',
    `balancing_area_id` BIGINT COMMENT 'Foreign key linking to gridops.balancing_area. Business justification: Control zones belong to a balancing area; adding balancing_area_id creates proper hierarchy and removes redundant code column.',
    `cip_standard_id` BIGINT COMMENT 'Foreign key linking to regulatory.cip_standard. Business justification: Each control zone is subject to a specific CIP standard; the FK supports compliance tracking and audit readiness.',
    `control_center_id` BIGINT COMMENT 'Foreign key linking to gridops.control_center. Business justification: A control center oversees multiple control zones; adding control_zone.control_center_id creates the necessary parent relationship and eliminates the silo for control_center.',
    `scada_system_id` BIGINT COMMENT 'Zone identifier as registered in the SCADA system (OSIsoft PI Historian / GE PowerOn). Used to correlate real-time telemetry data streams, alarm points, and control actions to this logical control zone.',
    `ami_meter_count` STRING COMMENT 'Number of Advanced Metering Infrastructure (AMI) smart meters deployed within this control zone. Used for demand response targeting, load disaggregation, and meter data management (MDM) reporting.',
    `area_control_error_threshold_mw` DECIMAL(18,2) COMMENT 'Maximum allowable Area Control Error (ACE) in Megawatts (MW) for this control zone before corrective dispatch action is triggered. Defined per NERC BAL-001 compliance requirements for balancing authority performance.',
    `bus_count` STRING COMMENT 'Number of electrical buses (nodes) within this control zone as modeled in the EMS network topology. Used for state estimation, power flow analysis, and contingency analysis.',
    `created_timestamp` TIMESTAMP COMMENT 'Timestamp when this control zone record was first created in the data lakehouse Silver layer. Supports data lineage, audit trail, and regulatory record retention requirements.',
    `critical_infrastructure_flag` BOOLEAN COMMENT 'Indicates whether this control zone contains or serves Critical Infrastructure Protection (CIP) assets as defined by NERC CIP standards. Zones flagged true require enhanced cybersecurity controls and physical security measures.',
    `customer_count` STRING COMMENT 'Total number of end-use customers (residential and commercial) served within this control zone. Used for SAIDI/SAIFI/CAIDI reliability index calculations and outage impact assessments.',
    `der_integration_enabled` BOOLEAN COMMENT 'Indicates whether Distributed Energy Resources (DER) — including rooftop solar, battery storage, and small-scale generation — are actively managed within this control zone via the DERMS platform.',
    `dispatch_priority` STRING COMMENT 'Numeric priority rank assigned to this control zone for load dispatch and restoration sequencing. Lower values indicate higher priority. Used by EMS/DMS operators during contingency events and load shedding scenarios.',
    `dms_zone_code` STRING COMMENT 'Zone identifier as configured in the Distribution Management System (DMS) for feeder switching, fault isolation, and service restoration coordination. Distinct from the EMS zone ID as DMS operates at distribution voltage levels.',
    `dr_program_eligible` BOOLEAN COMMENT 'Indicates whether this control zone participates in Demand Response (DR) dispatch programs. Zones flagged true are included in DR event targeting, load curtailment calculations, and DERMS coordination.',
    `effective_date` DATE COMMENT 'Date on which this control zone became operationally active and was formally recognized in the EMS/DMS configuration. Used for regulatory reporting, rate case filings, and historical grid topology analysis.',
    `ems_zone_code` STRING COMMENT 'Zone identifier as configured in the Energy Management System (EMS) for state estimation, optimal power flow, and automatic generation control (AGC) dispatch. Enables cross-system traceability between the EMS and the data lakehouse.',
    `feeder_count` STRING COMMENT 'Number of distribution feeders managed within this control zone. Supports feeder load balancing, switching order management, and outage restoration planning in the DMS.',
    `frequency_regulation_eligible` BOOLEAN COMMENT 'Indicates whether this control zone is eligible to provide frequency regulation ancillary services to the balancing authority or RTO/ISO market. True if the zone has resources capable of automatic generation control (AGC) response.',
    `geographic_region` STRING COMMENT 'Name or code of the geographic service territory region in which this control zone is located. Used for regional load forecasting, regulatory reporting to state PUCs, and operational area assignment.',
    `gis_zone_code` STRING COMMENT 'Zone identifier in the Esri ArcGIS geospatial system. Links the logical control zone to its physical geographic boundary polygon for spatial analysis, outage impact mapping, and infrastructure planning.',
    `installed_capacity_mw` DECIMAL(18,2) COMMENT 'Total installed generation capacity in Megawatts (MW) within or directly serving this control zone. Supports resource adequacy assessments and capacity reserve margin calculations.',
    `interconnection_type` STRING COMMENT 'North American electrical interconnection to which this control zone belongs: Eastern Interconnection, Western Interconnection, ERCOT (Texas), Alaska, or Hawaii. Determines synchronous grid boundaries and applicable NERC reliability standards.. Valid values are `eastern|western|ercot|alaska|hawaii`',
    `last_configuration_review_date` DATE COMMENT 'Date of the most recent formal review of this control zones EMS/DMS configuration parameters, including voltage setpoints, protection relay settings, and dispatch parameters. Supports NERC FAC-002 compliance documentation.',
    `load_forecast_model` STRING COMMENT 'Type of load forecasting methodology applied to this control zone within the Energy Management System (EMS). Determines how short-term and long-term load forecasts are generated for dispatch coordination and resource planning.. Valid values are `statistical|machine_learning|hybrid|persistence|expert_system`',
    `load_shedding_eligible` BOOLEAN COMMENT 'Indicates whether this control zone is eligible for controlled load shedding during grid emergency conditions. Zones containing critical infrastructure (hospitals, emergency services) are typically excluded.',
    `nerc_cip_classification` STRING COMMENT 'NERC CIP impact classification level for Bulk Electric System (BES) assets within this control zone. High and Medium classifications require mandatory cybersecurity and physical security controls per NERC CIP-002 through CIP-014.. Valid values are `high|medium|low|not_applicable`',
    `net_energy_metering_eligible` BOOLEAN COMMENT 'Indicates whether customers within this control zone are eligible for Net Energy Metering (NEM) programs, allowing bi-directional energy flow credit for distributed generation (e.g., rooftop solar). Affects load forecasting and grid hosting capacity analysis.',
    `oms_zone_code` STRING COMMENT 'Zone identifier as registered in the Outage Management System (OMS). Used to correlate outage events, crew dispatch, and restoration activities to this control zone for SAIDI/SAIFI/CAIDI reporting.',
    `peak_load_mw` DECIMAL(18,2) COMMENT 'Maximum recorded or rated peak electrical load in Megawatts (MW) for this control zone. Used as the principal capacity measure for load forecasting, resource adequacy planning, and Integrated Resource Plan (IRP) filings.',
    `reserve_margin_pct` DECIMAL(18,2) COMMENT 'Minimum required planning reserve margin percentage for this control zone as mandated by the applicable RTO/ISO or state Public Utility Commission (PUC). Expressed as a percentage of peak load.',
    `retirement_date` DATE COMMENT 'Date on which this control zone was retired or decommissioned from active grid operations. Null for currently active zones. Used for historical topology reconstruction and regulatory asset base (RAB) tracking.',
    `rto_iso_code` STRING COMMENT 'Code identifying the Regional Transmission Organization (RTO) or Independent System Operator (ISO) market in which this control zone participates for energy dispatch, ancillary services, and Locational Marginal Price (LMP) settlement.',
    `saidi_target_minutes` DECIMAL(18,2) COMMENT 'Target System Average Interruption Duration Index (SAIDI) in minutes for this control zone as established in the utilitys reliability performance plan or state PUC reliability standards. Benchmarks operational reliability performance.',
    `saifi_target` DECIMAL(18,2) COMMENT 'Target System Average Interruption Frequency Index (SAIFI) — average number of interruptions per customer per year — for this control zone as defined in the utilitys reliability plan or state PUC requirements.',
    `state_code` STRING COMMENT 'Two-letter US state code for the primary jurisdiction in which this control zone operates. Determines applicable state Public Utility Commission (PUC) regulations, rate cases, and reliability standards.. Valid values are `^[A-Z]{2}$`',
    `substation_count` STRING COMMENT 'Number of substations included within this control zone. Used for operational complexity assessment, maintenance planning, and regulatory asset base (RAB) reporting.',
    `tie_line_capacity_mw` DECIMAL(18,2) COMMENT 'Total rated transfer capacity in Megawatts (MW) of all tie lines connecting this control zone to adjacent zones or balancing areas. Used for interchange scheduling and Available Transfer Capability (ATC) calculations.',
    `tou_pricing_applicable` BOOLEAN COMMENT 'Indicates whether Time-of-Use (TOU) pricing rates are applicable to customers within this control zone. Drives load shape modeling and demand response program design for the zone.',
    `updated_timestamp` TIMESTAMP COMMENT 'Timestamp of the most recent update to this control zone record in the data lakehouse. Used for change data capture (CDC), incremental processing, and audit trail maintenance.',
    `voltage_control_mode` STRING COMMENT 'Operational mode for voltage control within this zone as configured in the DMS/EMS. Automatic mode enables closed-loop voltage regulation; supervisory mode allows operator-directed control; manual mode requires direct field action.. Valid values are `automatic|manual|supervisory|off`',
    `voltage_level_kv` DECIMAL(18,2) COMMENT 'Nominal operating voltage level of the control zone in kilovolts (kV). Defines the voltage class for equipment ratings, protection coordination, and voltage control strategy within the zone.',
    `weather_zone_code` STRING COMMENT 'Code identifying the weather forecast zone associated with this control zone. Weather zone data drives temperature-sensitive load forecasting models and storm preparedness planning within the EMS.',
    `zone_code` STRING COMMENT 'Externally-known alphanumeric code uniquely identifying the control zone within the Energy Management System (EMS) and Distribution Management System (DMS). Used in SCADA displays, switching orders, and operational reports.. Valid values are `^[A-Z0-9_]{2,20}$`',
    `zone_description` STRING COMMENT 'Free-text operational description of the control zone including its geographic boundaries, key assets, operational characteristics, and any special operating conditions or constraints relevant to dispatch and reliability management.',
    `zone_name` STRING COMMENT 'Human-readable name of the control zone used in operational dashboards, load forecasting reports, and dispatch coordination communications.',
    `zone_status` STRING COMMENT 'Current lifecycle status of the control zone within the EMS/DMS. Active zones participate in real-time dispatch and load forecasting. Commissioning zones are being brought into service. Decommissioned zones are retired from grid operations.. Valid values are `active|inactive|suspended|commissioning|decommissioned`',
    `zone_type` STRING COMMENT 'Operational classification of the control zone indicating its primary grid function: load (demand-side), generation (supply-side), transmission (bulk power), distribution (end-delivery), balancing (area control), or interchange (tie-point between areas).. Valid values are `load|generation|transmission|distribution|balancing|interchange`',
    CONSTRAINT pk_control_zone PRIMARY KEY(`control_zone_id`)
) COMMENT 'Defines electrical control zones within the balancing area, representing logical subdivisions of the grid used for load forecasting, voltage control, and dispatch coordination. Each zone maps to a set of buses, substations, and feeders managed under a unified operational strategy within the EMS/DMS.';

CREATE OR REPLACE TABLE `power_and_utilities_v2`.`gridops`.`scada_point` (
    `scada_point_id` BIGINT COMMENT 'Unique surrogate identifier for each SCADA telemetry point in the master catalog. Serves as the primary key for the scada_point product in the Databricks Silver Layer. Entity role: MASTER_RESOURCE — represents a configured telemetry measurement point owned and managed by the utility.',
    `registry_id` BIGINT COMMENT 'Reference to the grid asset (substation, transformer, generator, transmission line, distribution feeder, capacitor bank, etc.) that this SCADA point monitors or controls. Links the telemetry point to the physical asset in the asset management system (Maximo EAM or Esri ArcGIS). Used for asset health analytics and outage correlation.',
    `associated_asset_registry_id` BIGINT COMMENT 'Reference to the grid asset (substation, transformer, generator, transmission line, distribution feeder, capacitor bank, etc.) that this SCADA point monitors or controls. Links the telemetry point to the physical asset in the asset management system (Maximo EAM or Esri ArcGIS). Used for asset health analytics and outage correlation.',
    `balancing_area_id` BIGINT COMMENT 'Foreign key linking to gridops.balancing_area. Business justification: SCADA points are located within a balancing area; linking provides spatial context and removes string field.',
    `it_asset_id` BIGINT COMMENT 'Foreign key linking to technology.it_asset. Business justification: Each SCADA point corresponds to a physical IT asset (sensor/device); linking supports maintenance schedules and regulatory asset tracking.',
    `network_device_id` BIGINT COMMENT 'Foreign key linking to technology.network_device. Business justification: SCADA points are collected via network devices; linking enables IT asset management and cybersecurity compliance for each point.',
    `resource_id` BIGINT COMMENT 'Foreign key linking to der.der_resource. Business justification: SCADA points monitor DER inverter output for real‑time operations; utility operators need this link for dispatch and compliance.',
    `transmission_substation_id` BIGINT COMMENT 'Reference to the substation or switching station where the field device associated with this SCADA point is physically located. Used for geographic grouping, outage management correlation, and NERC reliability reporting. Links to the substation master record in GIS and EMS network model.',
    `alarm_high_high_limit` DECIMAL(18,2) COMMENT 'The critical upper threshold (High-High) above which an emergency or critical alarm is triggered, indicating a severe operational condition requiring immediate operator action. Expressed in engineering units. Used in EMS/DMS for two-tier alarm escalation (High vs. High-High). Supports NERC reliability event classification.',
    `alarm_high_limit` DECIMAL(18,2) COMMENT 'The upper operational threshold above which an alarm condition is triggered in the EMS/DMS/SCADA system. When the measured value exceeds this limit, an alarm notification is generated for grid operators. Expressed in engineering units. Configured in GE PowerOn EMS/DMS alarm management module.',
    `alarm_low_limit` DECIMAL(18,2) COMMENT 'The lower operational threshold below which an alarm condition is triggered in the EMS/DMS/SCADA system. When the measured value falls below this limit, an alarm notification is generated for grid operators. Expressed in engineering units. Configured in GE PowerOn EMS/DMS alarm management module.',
    `alarm_low_low_limit` DECIMAL(18,2) COMMENT 'The critical lower threshold (Low-Low) below which an emergency or critical alarm is triggered, indicating a severe operational condition requiring immediate operator action. Expressed in engineering units. Used in EMS/DMS for two-tier alarm escalation (Low vs. Low-Low). Supports NERC reliability event classification.',
    `asset_class` STRING COMMENT 'The operational asset class of the grid infrastructure element monitored by this SCADA point. Used for domain routing, regulatory reporting boundary classification, and T&D cost allocation. [ENUM-REF-CANDIDATE: generation|transmission|distribution|substation|gas_pipeline|gas_distribution|metering|protection — promote to reference product]',
    `commissioned_date` DATE COMMENT 'The date on which this SCADA point was formally commissioned and activated in the operational SCADA/EMS/DMS system. Marks the start of the points active lifecycle. Used for asset age analysis, warranty tracking, and NERC CIP change management audit trails.',
    `communication_protocol` STRING COMMENT 'The communication protocol used to transmit telemetry data from the field device (RTU/IED) to the SCADA master station for this point. Common utility protocols include DNP3, IEC 60870-5-101/104, IEC 61850, Modbus, and ICCP for inter-control-center communications. Used for cybersecurity classification and NERC CIP asset categorization. [ENUM-REF-CANDIDATE: DNP3|IEC60870-5-101|IEC60870-5-104|Modbus|IEC61850|ICCP|OPC-DA|OPC-UA — promote to reference product]',
    `compression_enabled` BOOLEAN COMMENT 'Indicates whether OSIsoft PI Historian data compression (exception and compression deviation) is enabled for this point. When True, PI Historian applies the deadband_value and compression deviation to reduce storage while preserving data fidelity. When False, all scanned values are archived (raw storage mode). Impacts PI Historian storage sizing and data retrieval performance.',
    `created_timestamp` TIMESTAMP COMMENT 'The timestamp when this SCADA point record was first created in the master catalog (Silver Layer). Represents the audit creation time in the Databricks Lakehouse. Formatted as yyyy-MM-ddTHH:mm:ss.SSSXXX per enterprise timestamp convention.',
    `data_quality_code` STRING COMMENT 'The current or last-known data quality status of this SCADA point as reported by OSIsoft PI Historian or GE PowerOn EMS/DMS. good = valid telemetry; bad = communication failure or device fault; uncertain = questionable signal; substituted = manually overridden value; manual_entry = operator-entered value; out_of_range = value outside raw limits. Used for data quality filtering in analytics.. Valid values are `good|bad|uncertain|substituted|manual_entry|out_of_range`',
    `deadband_value` DECIMAL(18,2) COMMENT 'The minimum change in the measured value required to trigger a new data archive event in OSIsoft PI Historian (exception deviation). Expressed in the same engineering units as the point. Prevents excessive data storage for slowly-changing signals while ensuring meaningful changes are captured. Configured per point in PI Historian compression settings.',
    `decommissioned_date` DATE COMMENT 'The date on which this SCADA point was decommissioned and removed from active scanning in the SCADA/EMS/DMS system. Null if the point is still active. Used for lifecycle management, historical data archival decisions, and NERC CIP asset retirement documentation.',
    `ems_point_address` STRING COMMENT 'The point address or database key used to reference this telemetry point within the GE PowerOn EMS/DMS real-time database. Typically a hierarchical address string (e.g., AREA.SUBSTATION.DEVICE.MEASUREMENT). Used for EMS state estimation, contingency analysis, and real-time display binding.',
    `energy_type` STRING COMMENT 'Identifies whether this SCADA point monitors an electric grid asset or a natural gas infrastructure asset. electric = electric T&D or generation; gas = natural gas pipeline, compressor, or distribution; both = dual-fuel or combined measurement point. Supports domain partitioning for electric vs. gas operations analytics.. Valid values are `electric|gas|both`',
    `engineering_unit` STRING COMMENT 'The physical unit of measurement associated with the SCADA point value (e.g., kV, MW, MVAr, A, Hz, degF, PSI, MCF/hr, kWh). Sourced from OSIsoft PI Historian engineering unit configuration. Critical for correct interpretation of telemetry values in EMS, DMS, and analytics applications. Aligns with IEC 61970 CIM unit symbols.',
    `functional_location` STRING COMMENT 'The SAP PM (Plant Maintenance) functional location code identifying the hierarchical physical location of the asset associated with this SCADA point (e.g., TX-SUBST-A-XFMR-01). Links SCADA telemetry to the SAP ERP asset hierarchy for O&M cost allocation, work order management, and CAPEX/OPEX tracking.',
    `gis_feature_reference` STRING COMMENT 'The unique feature identifier from Esri ArcGIS for the network element (substation, line segment, transformer, etc.) associated with this SCADA point. Enables spatial analysis, outage mapping, and geographic visualization of real-time telemetry in the GIS platform. Links SCADA data to the geospatial network model.',
    `is_alarmed` BOOLEAN COMMENT 'Indicates whether alarm processing is enabled for this SCADA point in the EMS/DMS alarm management system. True = alarm limits are active and will generate operator notifications; False = alarm processing suppressed (e.g., during maintenance or commissioning). Drives alarm display filtering in GE PowerOn EMS/DMS.',
    `is_bes_applicable` BOOLEAN COMMENT 'Indicates whether this SCADA point is associated with a Bulk Electric System (BES) element as defined by NERC. BES-applicable points are subject to NERC CIP cybersecurity standards and NERC reliability standards reporting requirements. True = BES applicable; False = non-BES (distribution or sub-transmission).',
    `is_cip_applicable` BOOLEAN COMMENT 'Indicates whether this SCADA point is subject to NERC Critical Infrastructure Protection (CIP) cybersecurity standards. CIP-applicable points require access control, monitoring, and change management per NERC CIP-007-6. True = CIP applicable; False = not subject to CIP requirements.',
    `is_controllable` BOOLEAN COMMENT 'Indicates whether this SCADA point supports remote control operations (e.g., breaker open/close, tap changer raise/lower, setpoint adjustment) from the EMS/DMS/SCADA master station. True = remote control enabled; False = read-only telemetry. Critical for access control and NERC CIP classification of control points.',
    `last_calibration_date` DATE COMMENT 'The date of the most recent calibration or verification of the field instrument (transducer, CT, PT, transmitter) associated with this SCADA point. Used for instrument maintenance scheduling, data quality assurance, and OSHA/PHMSA compliance for gas measurement instruments.',
    `last_modified_timestamp` TIMESTAMP COMMENT 'The timestamp when this SCADA point record was most recently updated in the master catalog. Tracks configuration changes to point attributes (alarm limits, scan rate, deadband, etc.). Critical for NERC CIP-010-3 configuration change management audit trail and Silver Layer incremental load processing.',
    `measurement_category` STRING COMMENT 'The physical or electrical quantity being measured by this SCADA point. Categorizes the telemetry by measurement domain for analytics, display grouping, and regulatory reporting. Examples: voltage (kV), power_mw (real power), power_mvar (reactive power), frequency (Hz), flow_mcf (gas flow), pressure (PSI). [ENUM-REF-CANDIDATE: voltage|current|power_mw|power_mvar|frequency|energy_mwh|flow_mcf|pressure|temperature|status_indication|position — promote to reference product]',
    `next_calibration_date` DATE COMMENT 'The scheduled date for the next calibration or verification of the field instrument associated with this SCADA point. Drives preventive maintenance work order generation in Maximo EAM. Ensures compliance with PHMSA gas measurement calibration intervals and OSHA instrument maintenance requirements.',
    `nominal_value` DECIMAL(18,2) COMMENT 'The expected or design nominal operating value for this SCADA point under normal grid conditions (e.g., nominal voltage = 138.0 kV, nominal frequency = 60.0 Hz). Used as a reference baseline for deviation analysis, alarm limit setting, and grid state estimation in EMS. Expressed in engineering units.',
    `offset_value` DECIMAL(18,2) COMMENT 'Additive offset applied after scale factor conversion to produce the final engineering unit value from the raw telemetry input. Used to correct for zero-point calibration errors or instrument biases. Configured in OSIsoft PI Historian or GE PowerOn EMS/DMS as part of the points conversion formula.',
    `pi_point_code` STRING COMMENT 'The native point identifier (PI Point ID or PI Tag Name) assigned by OSIsoft PI Historian for this SCADA telemetry point. Used for direct API queries to PI Historian via PI Web API or PI OLEDB. Enables traceability from the Silver Layer back to the source historian record.',
    `point_class` STRING COMMENT 'Functional classification of the SCADA point indicating its operational role. measurement = real-time telemetry value; status = equipment state indication; control = remotely operable control point; setpoint = configurable operating parameter; alarm = alarm/event indicator. Used for access control, display filtering, and NERC CIP classification.. Valid values are `measurement|status|control|setpoint|alarm`',
    `point_description` STRING COMMENT 'Free-text description of the SCADA telemetry point providing additional context about what is being measured, the associated equipment, and its operational significance. Sourced from OSIsoft PI Historian point descriptor field. Used in operator displays, engineering documentation, and data catalog search.',
    `point_name` STRING COMMENT 'Human-readable name of the SCADA telemetry point as configured in OSIsoft PI Historian or GE PowerOn EMS/DMS. Serves as the primary identity label for the point (e.g., SUBST_A_BUS1_VOLT, GEN_UNIT3_MW_OUTPUT). Used by grid operators and engineers to identify the measurement in real-time displays and historian queries.',
    `point_status` STRING COMMENT 'Current lifecycle status of the SCADA point in the master catalog. active = currently scanning and reporting; inactive = configured but not scanning; commissioned = newly added and validated; decommissioned = retired from service; suspended = temporarily halted due to maintenance or fault. Drives data quality filtering in PI Historian and Silver Layer ingestion.. Valid values are `active|inactive|commissioned|decommissioned|suspended`',
    `point_type` STRING COMMENT 'Classification of the SCADA telemetry point by signal type. analog = continuous measurement (e.g., voltage, MW flow); digital = discrete state (e.g., breaker open/closed); accumulator = pulse-count integration (e.g., energy meter pulse); string = text-based status; calculated = derived value computed within the historian or EMS.. Valid values are `analog|digital|accumulator|string|calculated`',
    `raw_high_limit` DECIMAL(18,2) COMMENT 'The maximum raw input value (in engineering units) that the SCADA point can physically receive from the field device before being flagged as out-of-range. Values above this threshold are treated as bad quality data. Configured in OSIsoft PI Historian and GE PowerOn EMS/DMS for data validation.',
    `raw_low_limit` DECIMAL(18,2) COMMENT 'The minimum raw input value (in engineering units) that the SCADA point can physically receive from the field device before being flagged as out-of-range. Values below this threshold are treated as bad quality data. Configured in OSIsoft PI Historian and GE PowerOn EMS/DMS for data validation.',
    `rtu_address` STRING COMMENT 'The communication address of the Remote Terminal Unit (RTU) or Intelligent Electronic Device (IED) from which this SCADA point is polled. Includes protocol-specific addressing (e.g., DNP3 address, Modbus register, IEC 60870-5-101/104 information object address). Used for field device troubleshooting and communication diagnostics.',
    `scale_factor` DECIMAL(18,2) COMMENT 'Multiplier applied to the raw telemetry input value to convert it to engineering units. For example, a current transformer (CT) ratio or potential transformer (PT) ratio applied to raw analog counts. Configured in OSIsoft PI Historian or GE PowerOn EMS/DMS as part of the points conversion formula.',
    `scan_rate_seconds` STRING COMMENT 'The frequency in seconds at which the SCADA system polls or samples this telemetry point from the field device (RTU, IED, or PLC). Common values: 2 (high-frequency protection), 4 (standard SCADA), 30 (slow telemetry), 60 (non-critical). Determines data density in PI Historian and impacts AMI/SCADA bandwidth planning.',
    `source_system` STRING COMMENT 'The operational system of record from which this SCADA point configuration originates. Identifies whether the point is mastered in OSIsoft PI Historian, GE PowerOn EMS, GE PowerOn DMS, a field RTU/IED, DERMS, or OMS. Critical for data lineage, integration mapping, and Silver Layer ingestion pipeline routing.. Valid values are `PI_HISTORIAN|GE_POWERON_EMS|GE_POWERON_DMS|SCADA_RTU|DERMS|OMS`',
    `tag_code` STRING COMMENT 'Externally-known unique tag identifier assigned to the SCADA point in the source operational system (OSIsoft PI Historian tag name or GE PowerOn point address). This is the business identifier used across OMS, DMS, EMS, and PI Historian integrations to reference the telemetry point. Equivalent to the PI tag name in OSIsoft PI.',
    `voltage_level_kv` DECIMAL(18,2) COMMENT 'The nominal voltage level in kilovolts (kV) of the electrical bus, equipment, or circuit that this SCADA point is associated with (e.g., 500 kV, 230 kV, 138 kV, 69 kV, 12.47 kV, 0.48 kV). Used for voltage class filtering, T&D boundary classification, and NERC BES (Bulk Electric System) applicability determination.',
    CONSTRAINT pk_scada_point PRIMARY KEY(`scada_point_id`)
) COMMENT 'Master catalog of all SCADA telemetry points (analog and digital) monitored via OSIsoft PI Historian and GE PowerOn EMS/DMS. Each record defines a measurement point including point name, tag ID, associated asset, engineering units, scan rate, deadband, and alarm thresholds. Serves as the SSOT for real-time grid telemetry configuration.';

CREATE OR REPLACE TABLE `power_and_utilities_v2`.`gridops`.`scada_reading` (
    `scada_reading_id` BIGINT COMMENT 'Unique surrogate identifier for each SCADA telemetry reading or alarm event record in the Silver layer. Entity role: EVENT_LOG — this is an append-only stream of immutable timestamped observations and alarm events captured from SCADA points via OSIsoft PI Historian.',
    `asset_registry_id` BIGINT COMMENT 'Reference to the physical grid asset (transformer, breaker, generator, transmission line, etc.) associated with this SCADA point reading. Enables correlation of telemetry to the asset registry in Maximo EAM.',
    `crew_member_id` BIGINT COMMENT 'Reference to the grid operator who acknowledged the alarm. Supports operator performance review, shift accountability, and NERC CIP-007 access logging. Null for non-alarm readings or unacknowledged alarms.',
    `distribution_switching_order_id` BIGINT COMMENT 'Reference to the switching order or clearance order in the DMS that initiated or is associated with a digital state change captured in this SCADA reading (e.g., breaker open/close operation). Links telemetry evidence to planned switching operations for post-switching verification.',
    `dr_dispatch_dr_dispatch_event_id` BIGINT COMMENT 'Reference to the Demand Response (DR) dispatch event that this SCADA reading is associated with, when the reading reflects load reduction or DR program response. Enables measurement and verification (M&V) of DR performance against dispatch instructions.',
    `dr_dispatch_event_id` BIGINT COMMENT 'Reference to the Demand Response (DR) dispatch event that this SCADA reading is associated with, when the reading reflects load reduction or DR program response. Enables measurement and verification (M&V) of DR performance against dispatch instructions.',
    `employee_id` BIGINT COMMENT 'Reference to the grid operator who acknowledged the alarm. Supports operator performance review, shift accountability, and NERC CIP-007 access logging. Null for non-alarm readings or unacknowledged alarms.',
    `gridops_outage_event_id` BIGINT COMMENT 'Reference to the outage or reliability event record in the OMS (Outage Management System) that this SCADA reading is associated with. Links telemetry evidence to outage events for SAIDI/SAIFI/CAIDI calculation, post-event analysis, and NERC reliability reporting.',
    `lmp_price_id` BIGINT COMMENT 'Reference to the RTO/ISO pricing node (LMP node) associated with this SCADA measurement point. Enables correlation of real-time telemetry with Day-Ahead Market (DAM) and Real-Time Market (RTM) LMP prices for congestion analysis and energy trading settlement.',
    `ot_asset_id` BIGINT COMMENT 'The identifier of the Remote Terminal Unit (RTU) or Intelligent Electronic Device (IED) that collected and transmitted this SCADA reading to the EMS/DMS. Supports communication path diagnostics, RTU performance monitoring, and NERC CIP-007 device inventory tracking.',
    `registry_id` BIGINT COMMENT 'Reference to the physical grid asset (transformer, breaker, generator, transmission line, etc.) associated with this SCADA point reading. Enables correlation of telemetry to the asset registry in Maximo EAM.',
    `resource_id` BIGINT COMMENT 'Foreign key linking to der.der_resource. Business justification: SCADA readings capture DER telemetry; required for performance reporting and regulatory compliance of distributed resources.',
    `scada_point_id` BIGINT COMMENT 'Foreign key linking to gridops.scada_point. Business justification: Readings are generated by a specific SCADA point; FK enables direct join and eliminates need for point_name lookup.',
    `transmission_substation_id` BIGINT COMMENT 'Reference to the substation or grid node where the SCADA point is physically located. Supports geographic and topological analysis of grid conditions.',
    `acknowledged_timestamp` TIMESTAMP COMMENT 'The UTC timestamp at which the alarm was acknowledged by a grid operator. Used to calculate time-to-acknowledge (TTA) for operator performance review and ISA-18.2 alarm response time KPI measurement. Null if not yet acknowledged or not an alarm.',
    `alarm_duration_seconds` STRING COMMENT 'The elapsed time in seconds between alarm trigger (reading_timestamp) and alarm cleared (cleared_timestamp). Used for ISA-18.2 alarm flood analysis, chattering alarm detection (alarms clearing and re-triggering rapidly), and post-event reliability analysis. Null if alarm is still active or not an alarm record.',
    `alarm_point_ref` STRING COMMENT 'The unique identifier or tag reference of the SCADA alarm point as configured in the DMS/EMS alarm management system (e.g., ALM_SUB_NORTH_BKR101_THERMAL). Used to cross-reference alarm events back to the alarm rationalization register and ISA-18.2 master alarm database.',
    `alarm_priority` STRING COMMENT 'The ISA-18.2 priority level assigned to the alarm (critical, high, medium, low, advisory). Drives operator response urgency, alarm flood analysis, and alarm rationalization reviews. Null for non-alarm readings.. Valid values are `critical|high|medium|low|advisory`',
    `alarm_state` STRING COMMENT 'Current lifecycle state of the alarm per ISA-18.2 alarm management workflow (active = unacknowledged and in alarm, acknowledged = operator has acknowledged, cleared = condition returned to normal, shelved = temporarily removed from annunciation, suppressed = disabled by design). Null for non-alarm readings.. Valid values are `active|acknowledged|cleared|shelved|suppressed`',
    `alarm_threshold` DOUBLE COMMENT 'The configured setpoint or limit value that, when crossed by the measured value, triggers the alarm (e.g., 110 MW thermal limit, 0.95 pu voltage low limit, 59.95 Hz under-frequency threshold). Supports alarm rationalization and threshold optimization analysis.',
    `alarm_type` STRING COMMENT 'Classifies the category of alarm event when is_alarm is True (e.g., thermal_overload, voltage_violation, equipment_failure, comm_loss, protection_operation, frequency_deviation). Null for non-alarm telemetry readings. Drives alarm rationalization and root-cause categorization. [ENUM-REF-CANDIDATE: thermal_overload|voltage_violation|equipment_failure|comm_loss|protection_operation|frequency_deviation|overcurrent|earth_fault — promote to reference product]',
    `analog_value` DOUBLE COMMENT 'The numeric measured value for analog SCADA points (e.g., 345.7 kV, 150.3 MW, 60.02 Hz, 1250 amps). This is the principal EVENT_PAYLOAD_OR_VALUE for analog readings. Null for digital state points. Stored in the engineering unit defined by engineering_unit.',
    `balancing_area_code` STRING COMMENT 'The NERC-registered Balancing Authority Area code within which this SCADA point operates (e.g., the utilitys registered BA identifier with NERC/FERC). Required for NERC reliability compliance reporting, RTO/ISO market settlement, and balancing area control performance (CPS1/CPS2) analysis.',
    `cleared_timestamp` TIMESTAMP COMMENT 'The UTC timestamp at which the alarm condition returned to normal and the alarm was cleared. Used to calculate alarm duration and time-to-clear (TTC) for post-event analysis and alarm flood studies. Null if alarm is still active or not an alarm record.',
    `communication_protocol` STRING COMMENT 'The SCADA communication protocol used to transmit this reading from the field device to the EMS/DMS (e.g., DNP3, IEC 61850, IEC 60870-5-104, Modbus, ICCP for inter-control-center). Supports protocol-level diagnostics and NERC CIP-007 communication security assessments.. Valid values are `DNP3|IEC_61850|IEC_60870|Modbus|ICCP|proprietary`',
    `compression_deviation` DOUBLE COMMENT 'The PI Historian compression deviation (swinging door algorithm tolerance) applied to this tag. Determines how aggressively PI compresses the time-series data. Understanding compression settings is essential for accurate signal reconstruction in load forecasting and post-event analysis.',
    `digital_state` STRING COMMENT 'The discrete state value for digital SCADA points representing equipment status (e.g., breaker open/closed, switch status, protection relay trip/normal, recloser enabled/disabled). Null for analog measurement points. [ENUM-REF-CANDIDATE: open|closed|trip|lockout|normal|abnormal|on|off|enabled|disabled — promote to reference product]',
    `engineering_unit` STRING COMMENT 'The unit of measure for the analog_value (e.g., MW, MVAR, kV, Hz, A for amps, °C, psi, MCF). Ensures correct interpretation of numeric readings across different measurement types and supports dimensional analysis in grid operations. [ENUM-REF-CANDIDATE: MW|MVAR|MVA|kV|Hz|A|°C|°F|psi|MCF|therm|%|pu|tap — 14 candidates stripped; promote to reference product]',
    `exception_deviation` DOUBLE COMMENT 'The configured exception deviation (deadband) value for this PI tag — the minimum change in analog value required to trigger a new archive event in PI Historian. A reading is stored only when the value changes by more than this amount. Used to understand data compression behavior and reconstruct continuous signal profiles.',
    `ferc_jurisdiction` STRING COMMENT 'Indicates whether the asset associated with this SCADA point falls under FERC jurisdictional transmission (interstate), state PUC jurisdictional distribution, or is exempt. Determines applicable regulatory reporting requirements for FERC Form 1, NERC reliability standards, and rate case filings.. Valid values are `FERC_jurisdictional|state_jurisdictional|exempt`',
    `ingested_timestamp` TIMESTAMP COMMENT 'The UTC timestamp at which this record was written into the Silver layer lakehouse table. Used to measure data latency, detect backfill scenarios, and support audit trails. Distinct from reading_timestamp which reflects the real-world event time.',
    `is_alarm` BOOLEAN COMMENT 'Indicates whether this record represents an alarm event (True) or a routine telemetry reading (False). Partitions the dataset for alarm management workflows, ISA-18.2 alarm rationalization analysis, and operator performance review.',
    `is_shelved` BOOLEAN COMMENT 'Indicates whether the alarm has been temporarily shelved (removed from active annunciation for a defined period) per ISA-18.2 shelving practice. Shelved alarms are excluded from alarm flood counts but must be tracked for rationalization audits.',
    `is_suppressed` BOOLEAN COMMENT 'Indicates whether the alarm is in a suppressed (by-design disabled) state, such as during planned maintenance or equipment outage. Suppressed alarms must be documented and reviewed per ISA-18.2 alarm rationalization requirements.',
    `measurement_type` STRING COMMENT 'The engineering quantity being measured by this SCADA point (e.g., MW for real power, MVAR for reactive power, kV for voltage, Hz for frequency, amps for current, temperature_c for equipment temperature, flow_mcf for gas flow). Drives unit-of-measure validation and alarm threshold interpretation. [ENUM-REF-CANDIDATE: MW|MVAR|kV|Hz|amps|temperature_c|MVA|power_factor|tap_position|flow_mcf|pressure_psi|status — promote to reference product]',
    `nerc_cip_asset_class` STRING COMMENT 'The NERC CIP Bulk Electric System (BES) asset classification for the asset associated with this SCADA point (BES_high, BES_medium, BES_low, non_BES). Determines applicable NERC CIP cybersecurity standards (CIP-002 through CIP-014) and access control requirements for this telemetry data.. Valid values are `BES_high|BES_medium|BES_low|non_BES`',
    `pi_archive_name` STRING COMMENT 'The name of the OSIsoft PI Historian archive file or data archive from which this reading was extracted (e.g., PI_ARCHIVE_2024_Q1). Supports data lineage, archive retrieval for post-event analysis, and Silver layer backfill reconciliation.',
    `pi_tag_code` BIGINT COMMENT 'Reference to the PI Historian tag (SCADA point) that emitted this reading. Serves as the EVENT_SOURCE_REFERENCE linking the observation back to the originating sensor or control point definition.',
    `point_name` STRING COMMENT 'The human-readable PI tag name or SCADA point descriptor as configured in OSIsoft PI Historian (e.g., SUB_NORTH_BKR_101_STATUS, GEN_UNIT3_MW_OUTPUT). Serves as the primary EVENT_TYPE_OR_CHANNEL discriminator and the operational label used by grid operators.',
    `point_type` STRING COMMENT 'Classifies the SCADA point as analog (continuous measurement), digital (discrete state), accumulator (pulse count/energy total), string (text state), or calculated (derived value). Determines how the reading_value and digital_state fields are interpreted.. Valid values are `analog|digital|accumulator|string|calculated`',
    `quality_code` STRING COMMENT 'OSIsoft PI Historian quality descriptor indicating the reliability of the reading (e.g., good = valid telemetry, bad = hardware/comm failure, uncertain = questionable signal, substituted = manually entered replacement, stale = no update within scan cycle). Critical for filtering unreliable data in operational analytics and NERC compliance evidence. [ENUM-REF-CANDIDATE: good|bad|uncertain|substituted|manual|stale|comm_fail|out_of_scan — 8 candidates stripped; promote to reference product]',
    `raw_value_string` STRING COMMENT 'The original unparsed string representation of the SCADA point value as received from the RTU/IED before type conversion and engineering unit scaling. Preserved for data quality investigation, protocol debugging, and Silver layer reconciliation against the Bronze raw landing zone.',
    `reading_timestamp` TIMESTAMP COMMENT 'The precise UTC timestamp at which the SCADA point value was sampled or the alarm event was triggered, as recorded by OSIsoft PI Historian. This is the principal EVENT_TIMESTAMP and the primary time axis for all operational analysis, post-event review, and NERC compliance evidence.',
    `rtu_code` STRING COMMENT 'The identifier of the Remote Terminal Unit (RTU) or Intelligent Electronic Device (IED) that collected and transmitted this SCADA reading to the EMS/DMS. Supports communication path diagnostics, RTU performance monitoring, and NERC CIP-007 device inventory tracking.',
    `scan_rate_seconds` STRING COMMENT 'The configured polling interval in seconds at which this SCADA point is scanned by the RTU/IED and reported to PI Historian (e.g., 2 seconds for critical protection points, 30 seconds for non-critical analog measurements). Used to detect stale data and validate scan cycle compliance.',
    `shelve_expiry_timestamp` TIMESTAMP COMMENT 'The UTC timestamp at which a shelved alarm is scheduled to automatically return to active annunciation. Supports ISA-18.2 shelving time-limit enforcement and alarm rationalization audit trails. Null if alarm is not shelved.',
    `source_system` STRING COMMENT 'The operational system of record that originated or forwarded this reading to the Silver layer (e.g., PI_Historian for OSIsoft PI, EMS for Energy Management System, DMS for GE PowerOn Distribution Management System, OMS for Outage Management System, DERMS for Distributed Energy Resource Management). Supports data lineage and cross-system reconciliation.. Valid values are `PI_Historian|EMS|DMS|OMS|DERMS|SCADA_RTU`',
    `substitution_reason` STRING COMMENT 'When quality_code is substituted, this field records the reason the original telemetry value was replaced (e.g., manual_entry by operator, estimated from adjacent readings, comm_failure_fill during communication outage, maintenance_hold during planned work). Required for NERC compliance evidence and data quality audit trails.. Valid values are `manual_entry|estimated|comm_failure_fill|maintenance_hold|default_value`',
    `time_to_acknowledge_seconds` STRING COMMENT 'The elapsed time in seconds between the alarm trigger (reading_timestamp) and operator acknowledgment (acknowledged_timestamp). Pre-computed at ingestion time for ISA-18.2 alarm response time KPI reporting and operator performance review. Null for non-alarm records or unacknowledged alarms.',
    `trigger_value` DOUBLE COMMENT 'The actual measured value at the moment the alarm condition was triggered (e.g., 112.5 MW when a 110 MW thermal limit was exceeded). Enables post-event analysis of how far the measured value deviated from the threshold. Null for non-alarm readings.',
    `voltage_level_kv` DECIMAL(18,2) COMMENT 'The nominal voltage level in kilovolts (kV) of the bus, line, or equipment associated with this SCADA point (e.g., 345 kV transmission, 138 kV sub-transmission, 12.47 kV distribution). Used to classify readings by voltage tier for T&D performance analysis and NERC FAC compliance.',
    CONSTRAINT pk_scada_reading PRIMARY KEY(`scada_reading_id`)
) COMMENT 'Near-real-time and historical telemetry readings and alarm events captured from SCADA points via OSIsoft PI Historian. Stores timestamped analog values (MW, MVAR, kV, Hz, amps, temperature), digital state changes (breaker open/close, switch status, protection relay operations), and alarm records. Alarm data includes alarm point reference, alarm type (thermal overload, voltage violation, equipment failure, communication loss, protection operation), priority level per ISA-18.2 alarm management standard, trigger value, threshold, acknowledgment status, acknowledging operator, shelving status, suppression state, and time to acknowledge/clear. This is the highest-volume product in the domain and the foundation for all real-time operational decisions, alarm management and rationalization, operator performance review, post-event analysis, NERC CIP-007 compliance, and NERC compliance evidence.';

CREATE OR REPLACE TABLE `power_and_utilities_v2`.`gridops`.`ems_dispatch_instruction` (
    `ems_dispatch_instruction_id` BIGINT COMMENT 'Unique surrogate identifier for each EMS dispatch instruction record in the balancing area. Primary key for this entity.',
    `balancing_area_id` BIGINT COMMENT 'Reference to the balancing authority area within which this dispatch instruction is issued. Aligns with NERC balancing area definitions.',
    `bus_id` BIGINT COMMENT 'Reference to the pricing node at which the Locational Marginal Price (LMP) applies for this dispatch instruction. Used for economic dispatch optimization and settlement calculations.',
    `der_program_id` BIGINT COMMENT 'Foreign key linking to der.program. Business justification: EMS dispatch may include specific DER program instructions for ancillary services; operators need the program reference.',
    `distribution_switching_order_id` BIGINT COMMENT 'Reference to a switching order in the DMS (Distribution Management System) or EMS that is coordinated with this dispatch instruction. Used when dispatch is part of a planned switching sequence.',
    `employee_id` BIGINT COMMENT 'Reference to the EMS operator or system entity (AGC) that issued this dispatch instruction. Used for accountability and audit trail per NERC CIP and reliability standards.',
    `generating_unit_id` BIGINT COMMENT 'Reference to the generating unit or controllable resource to which this dispatch instruction is directed. Links to the asset registry in Maximo or GIS.',
    `gridops_outage_event_id` BIGINT COMMENT 'Reference to an associated outage or reliability event in the OMS (Outage Management System) that triggered or is related to this dispatch instruction. Populated for reliability-driven dispatches.',
    `operator_employee_id` BIGINT COMMENT 'Reference to the EMS operator or system entity (AGC) that issued this dispatch instruction. Used for accountability and audit trail per NERC CIP and reliability standards.',
    `scada_point_id` BIGINT COMMENT 'The SCADA (Supervisory Control and Data Acquisition) telemetry point identifier associated with the generating units MW output measurement in OSIsoft PI Historian. Used to correlate dispatch instructions with real-time telemetry data.',
    `acknowledgment_status` STRING COMMENT 'Status of the generating unit or resource operators acknowledgment of this dispatch instruction. Pending indicates awaiting response; acknowledged confirms receipt; not_acknowledged indicates no response within the required window; rejected indicates the resource declined the instruction.. Valid values are `pending|acknowledged|not_acknowledged|rejected`',
    `acknowledgment_timestamp` TIMESTAMP COMMENT 'The date and time at which the generating unit operator or automated system acknowledged receipt of this dispatch instruction.',
    `agc_sequence_number` STRING COMMENT 'Sequential number assigned by the Automatic Generation Control (AGC) system for this dispatch instruction within a given AGC scan cycle. Used to correlate instructions to AGC telemetry cycles in OSIsoft PI Historian.',
    `co2_emission_rate_lb_per_mwh` DECIMAL(18,2) COMMENT 'The estimated CO2 emission rate for the dispatched generating unit at the instructed MW setpoint, expressed in pounds per MWh. Used for environmental compliance reporting to EPA and state regulators.',
    `compliance_flag` BOOLEAN COMMENT 'Indicates whether the generating unit complied with this dispatch instruction within the required response time and MW tolerance. True if compliant; False if non-compliant. Used for NERC BAL reliability reporting.',
    `contingency_name` STRING COMMENT 'The name or identifier of the N-1 or N-2 contingency scenario that triggered this dispatch instruction, if applicable. Used for post-contingency analysis and NERC reliability event reporting.',
    `created_timestamp` TIMESTAMP COMMENT 'The date and time at which this dispatch instruction record was first captured in the Silver Layer data product. Audit trail field for data lineage and regulatory compliance.',
    `demand_response_flag` BOOLEAN COMMENT 'Indicates whether this dispatch instruction targets a Demand Response (DR) resource rather than a traditional generating unit. True when the controllable resource is a DR program participant.',
    `der_flag` BOOLEAN COMMENT 'Indicates whether this dispatch instruction targets a Distributed Energy Resource (DER) such as rooftop solar, battery storage, or small-scale generation managed via DERMS.',
    `dispatch_reason` STRING COMMENT 'The primary reason for issuing this dispatch instruction. Economic dispatch optimizes cost; reliability dispatch addresses grid stability; regulation dispatch supports frequency control; emergency dispatch responds to contingency events; voltage_support addresses reactive power needs; reserve dispatch activates operating reserves. [ENUM-REF-CANDIDATE: economic|reliability|regulation|emergency|voltage_support|reserve — promote to reference product]. Valid values are `economic|reliability|regulation|emergency|voltage_support|reserve`',
    `dispatch_type` STRING COMMENT 'Indicates whether the dispatch instruction was generated automatically by the AGC system or issued manually by an EMS operator. Automatic instructions originate from AGC scan cycles; manual instructions are operator-initiated.. Valid values are `automatic|manual`',
    `effective_timestamp` TIMESTAMP COMMENT 'The date and time at which the dispatch instruction is expected to take effect at the generating unit. May differ from instruction_timestamp due to ramp lead time or scheduling offset.',
    `energy_source_type` STRING COMMENT 'The primary energy source type of the dispatched generating unit or resource. Used for generation mix reporting, renewable energy tracking, and REC (Renewable Energy Certificate) accounting. [ENUM-REF-CANDIDATE: fossil_fuel|nuclear|hydro|wind|solar|battery_storage|demand_response|other — promote to reference product]',
    `expiry_timestamp` TIMESTAMP COMMENT 'The date and time at which this dispatch instruction expires or is superseded if not acknowledged or executed. After this time, the instruction is considered void.',
    `frequency_regulation_flag` BOOLEAN COMMENT 'Indicates whether this dispatch instruction is associated with frequency regulation service (AGC regulation signal). True when the instruction is part of a regulation up/down signal from the balancing authority.',
    `fuel_type` STRING COMMENT 'The specific fuel type consumed by the dispatched generating unit. Used for fuel cost allocation, emissions reporting, and EPA compliance. none for non-fuel resources such as wind, solar, or demand response. [ENUM-REF-CANDIDATE: natural_gas|coal|oil|uranium|water|wind|solar|none — promote to reference product]',
    `heat_rate_btu_per_kwh` DECIMAL(18,2) COMMENT 'The heat rate of the generating unit at the dispatched MW setpoint, expressed in British Thermal Units per kilowatt-hour (BTU/kWh). Used for fuel consumption estimation, emissions calculations, and economic dispatch optimization.',
    `instruction_number` STRING COMMENT 'Externally-known, human-readable business identifier for the dispatch instruction, used in operator logs, audit trails, and regulatory filings. Format: EMS-DISP-YYYY-NNNNNN.. Valid values are `^EMS-DISP-[0-9]{4}-[0-9]{6}$`',
    `instruction_status` STRING COMMENT 'Current lifecycle status of the dispatch instruction. Tracks the workflow from issuance through acknowledgment, execution, and completion or cancellation. [ENUM-REF-CANDIDATE: issued|acknowledged|executing|completed|cancelled|rejected — promote to reference product if additional statuses are needed]. Valid values are `issued|acknowledged|executing|completed|cancelled|rejected`',
    `instruction_timestamp` TIMESTAMP COMMENT 'The precise date and time (with timezone offset) at which the EMS issued this dispatch instruction to the generating unit or controllable resource. This is the principal business event timestamp.',
    `lmp_at_dispatch` DECIMAL(18,2) COMMENT 'The Locational Marginal Price (LMP) in dollars per MWh at the dispatch node at the time this instruction was issued. Used for economic dispatch evaluation and post-dispatch settlement.',
    `lmp_node_code` BIGINT COMMENT 'Reference to the pricing node at which the Locational Marginal Price (LMP) applies for this dispatch instruction. Used for economic dispatch optimization and settlement calculations.',
    `market_interval_code` BIGINT COMMENT 'Reference to the energy market interval (Day-Ahead Market or Real-Time Market) associated with this dispatch instruction. Links to the market scheduling system or ETRM (Allegro) interval record.',
    `market_type` STRING COMMENT 'The energy market context under which this dispatch instruction is issued. DAM (Day-Ahead Market), RTM (Real-Time Market), bilateral contract, self-schedule, or none for purely reliability-driven dispatches.. Valid values are `DAM|RTM|bilateral|self_schedule|none`',
    `mvar_setpoint` DECIMAL(18,2) COMMENT 'The target reactive power output level in Megavars (MVAR) instructed for voltage support purposes. Applicable when dispatch_reason is voltage_support or when reactive dispatch is co-optimized.',
    `mw_actual_response` DECIMAL(18,2) COMMENT 'The actual MW output achieved by the generating unit in response to this dispatch instruction, as measured by SCADA telemetry from OSIsoft PI Historian. Used to assess dispatch compliance and unit performance.',
    `mw_compliance_deviation` DECIMAL(18,2) COMMENT 'The difference in MW between the instructed setpoint and the actual response (mw_actual_response minus mw_setpoint). Positive values indicate over-generation; negative values indicate under-generation. Used for NERC compliance analysis.',
    `mw_delta` DECIMAL(18,2) COMMENT 'The change in MW output instructed by this dispatch (mw_setpoint minus mw_setpoint_prior). Positive values indicate an increase in generation; negative values indicate a decrease. Used for ramp compliance analysis.',
    `mw_setpoint` DECIMAL(18,2) COMMENT 'The target real power output level in Megawatts (MW) that the generating unit or controllable resource is instructed to achieve. This is the principal quantitative dispatch directive.',
    `mw_setpoint_prior` DECIMAL(18,2) COMMENT 'The MW setpoint that was in effect immediately before this dispatch instruction was issued. Used to calculate the MW delta and assess ramp requirements.',
    `operator_notes` STRING COMMENT 'Free-text notes entered by the EMS operator at the time of dispatch. May include context for manual overrides, reliability concerns, or coordination with other control areas.',
    `pi_tag_name` STRING COMMENT 'The OSIsoft PI Historian tag name for the real-time MW output data stream of the dispatched generating unit. Enables direct linkage between dispatch instructions and PI Historian time-series data for operational analytics.',
    `ramp_rate_mw_per_min` DECIMAL(18,2) COMMENT 'The instructed rate of change in MW output, expressed in Megawatts per minute (MW/min), at which the generating unit should ramp to the new setpoint. Derived from unit capability and AGC parameters.',
    `regulation_direction` STRING COMMENT 'Direction of frequency regulation service associated with this dispatch instruction. up indicates regulation up (increase output); down indicates regulation down (decrease output); none for non-regulation dispatches.. Valid values are `up|down|none`',
    `rejection_reason` STRING COMMENT 'Free-text or coded reason provided by the resource operator when a dispatch instruction is rejected or not acknowledged. Used for reliability event analysis and operator performance review.',
    `reserve_type` STRING COMMENT 'Type of operating reserve being activated by this dispatch instruction, if applicable. Spinning reserves are online and synchronized; non-spinning reserves can be brought online within 10 minutes; supplemental reserves provide longer-term backup.. Valid values are `spinning|non_spinning|supplemental|none`',
    `response_timestamp` TIMESTAMP COMMENT 'The date and time at which the generating unit reached or was confirmed to be at the instructed MW setpoint, as recorded by SCADA telemetry.',
    `source_system` STRING COMMENT 'The originating operational system that generated this dispatch instruction. EMS for Energy Management System automated dispatch; AGC for Automatic Generation Control; DMS for Distribution Management System; OMS for Outage Management System; DERMS for Distributed Energy Resource Management System; manual for operator-entered instructions.. Valid values are `EMS|AGC|DMS|OMS|DERMS|manual`',
    `updated_timestamp` TIMESTAMP COMMENT 'The date and time at which this dispatch instruction record was last modified in the Silver Layer data product. Used for incremental data processing and audit trail.',
    CONSTRAINT pk_ems_dispatch_instruction PRIMARY KEY(`ems_dispatch_instruction_id`)
) COMMENT 'Records each generation dispatch instruction issued by the Energy Management System (EMS) to generating units or controllable resources within the balancing area. Captures MW setpoint, ramp rate, dispatch reason (economic, reliability, regulation), issuing operator, and acknowledgment status. Integrates with AGC (Automatic Generation Control) and manual operator actions.';

CREATE OR REPLACE TABLE `power_and_utilities_v2`.`gridops`.`load_forecast` (
    `load_forecast_id` BIGINT COMMENT 'Unique surrogate identifier for each load forecast record in the balancing area Energy Management System (EMS) forecasting engine. Primary key for the load_forecast data product.',
    `balancing_area_id` BIGINT COMMENT 'Reference to the NERC-defined Balancing Authority Area (BAA) for which this load forecast was produced. The balancing area is the fundamental geographic and operational unit for which the EMS maintains load-generation balance. Links to the balancing area master reference product.',
    `control_zone_id` BIGINT COMMENT 'Reference to the specific control zone or load zone within the balancing area for which this forecast applies. Control zones represent sub-areas of the transmission system with distinct load characteristics, used for Locational Marginal Price (LMP) and zonal load forecasting.',
    `weather_forecast_id` BIGINT COMMENT 'Foreign key linking to gridops.weather_forecast. Business justification: Load forecasts are derived from a specific weather forecast; FK links forecast source.',
    `actual_demand_mw` DECIMAL(18,2) COMMENT 'The observed actual electrical load demand in Megawatts (MW) for the forecast interval, populated post-interval from SCADA telemetry or OSIsoft PI Historian. Null until the interval has elapsed and actuals are available. Used for forecast accuracy tracking and model performance evaluation.',
    `confidence_interval_lower_mw` DECIMAL(18,2) COMMENT 'The lower bound of the statistical confidence interval for the forecasted demand in Megawatts (MW). Represents the minimum plausible demand at the specified confidence level. Used for probabilistic unit commitment and reserve margin planning.',
    `confidence_interval_upper_mw` DECIMAL(18,2) COMMENT 'The upper bound of the statistical confidence interval for the forecasted demand in Megawatts (MW). Represents the maximum plausible demand at the specified confidence level. Used for contingency planning and operating reserve determination.',
    `confidence_level_pct` DECIMAL(18,2) COMMENT 'The statistical confidence level expressed as a percentage (e.g., 90.00, 95.00) associated with the confidence interval bounds. Indicates the probability that actual demand will fall within the stated confidence interval bounds.',
    `cooling_degree_days` DECIMAL(18,2) COMMENT 'The number of Cooling Degree Days (CDD) for the forecast date, calculated as the number of degrees the mean daily temperature exceeds 65°F. A standard weather normalization metric used in load forecasting models to quantify cooling-driven electrical demand.',
    `created_timestamp` TIMESTAMP COMMENT 'Audit timestamp recording when this load forecast record was first persisted into the Silver Layer lakehouse. Used for data lineage, audit trail, and SLA compliance tracking. Stored in ISO 8601 format (yyyy-MM-ddTHH:mm:ss.SSSXXX).',
    `day_type` STRING COMMENT 'Classification of the forecast day by its load profile category. Weekday, weekend, and holiday designations drive distinct load shape patterns in the EMS forecasting model. Peak day and off-peak day classifications support Time-of-Use (TOU) and Critical Peak Pricing (CPP) rate analysis.. Valid values are `weekday|weekend|holiday|peak_day|off_peak_day`',
    `der_generation_forecast_mw` DECIMAL(18,2) COMMENT 'The forecasted generation output in Megawatts (MW) from Distributed Energy Resources (DER) including rooftop solar, behind-the-meter storage, and small-scale generation within the distribution system. Subtracted from gross load to derive net load. Sourced from DERMS forecasting.',
    `dr_dispatched_mw` DECIMAL(18,2) COMMENT 'The amount of Demand Response (DR) capacity in Megawatts (MW) that has been dispatched or is planned to be dispatched during this forecast interval. Represents load reduction committed through DR programs, reducing the net load the grid must serve. Used for DR dispatch planning and DERMS coordination.',
    `forecast_date` DATE COMMENT 'The calendar date for which the load forecast applies. For day-ahead forecasts this is the operating day being forecasted. Used for daily operations planning, Day-Ahead Market (DAM) scheduling, and next-day unit commitment.',
    `forecast_error_mw` DECIMAL(18,2) COMMENT 'The absolute difference between forecasted demand and actual demand in Megawatts (MW), calculated as actual_demand_mw minus forecasted_demand_mw. Positive values indicate under-forecasting; negative values indicate over-forecasting. Populated post-interval for accuracy tracking.',
    `forecast_error_pct` DECIMAL(18,2) COMMENT 'The forecast error expressed as a percentage of actual demand, calculated as (actual_demand_mw - forecasted_demand_mw) / actual_demand_mw * 100. Used as the primary KPI for EMS forecasting model accuracy assessment and NERC compliance reporting.',
    `forecast_horizon_type` STRING COMMENT 'Classification of the forecast by its planning horizon. Short-term covers hourly/daily intervals; medium-term covers weekly/monthly; persistence uses the last observed value as the forecast; day-ahead supports Day-Ahead Market (DAM) scheduling; real-time supports Real-Time Market (RTM) dispatch. [ENUM-REF-CANDIDATE: short_term|medium_term|long_term|persistence|day_ahead|real_time — promote to reference product]. Valid values are `short_term|medium_term|long_term|persistence|day_ahead|real_time`',
    `forecast_humidity_pct` DECIMAL(18,2) COMMENT 'The forecasted relative humidity percentage used as a secondary weather input to the load forecasting model. Humidity affects the heat index and cooling load, particularly for residential and commercial air conditioning demand.',
    `forecast_interval_end` TIMESTAMP COMMENT 'The ending date and time of the interval for which the load demand is being forecasted. Together with forecast_interval_start, defines the precise time window of the forecast. Stored in ISO 8601 format (yyyy-MM-ddTHH:mm:ss.SSSXXX).',
    `forecast_interval_start` TIMESTAMP COMMENT 'The beginning date and time of the interval for which the load demand is being forecasted. For hourly forecasts this marks the top of the hour; for daily forecasts this marks midnight. Used for unit commitment scheduling, interchange scheduling, and DR dispatch planning. Stored in ISO 8601 format (yyyy-MM-ddTHH:mm:ss.SSSXXX).',
    `forecast_model_name` STRING COMMENT 'The name or identifier of the load forecasting algorithm or model used to produce this forecast (e.g., regression-based, neural network, ensemble). Supports model governance, audit trail, and comparison of forecast accuracy across different modeling approaches in the EMS.',
    `forecast_model_version` STRING COMMENT 'The version string of the EMS load forecasting model used to produce this forecast (e.g., 3.2.1). Enables traceability of forecast outputs to specific model releases, supporting model validation, regulatory audit, and accuracy benchmarking.',
    `forecast_model_version_code` BIGINT COMMENT 'Reference to the specific version of the EMS load forecasting model used to produce this forecast. Enables accuracy tracking across model versions, supports model governance, and facilitates comparison of forecast performance between model iterations.',
    `forecast_notes` STRING COMMENT 'Free-text field for operational notes, qualitative adjustments, or override justifications applied to this forecast record by EMS operators. Captures manual interventions, special event adjustments (e.g., major sporting events, industrial shutdowns), or model override rationale for audit and review purposes.',
    `forecast_run_number` STRING COMMENT 'Externally-known business identifier assigned by the EMS forecasting engine to uniquely identify a specific forecast run or batch. Used to group all interval records produced in a single forecast execution cycle. Aligns with OSIsoft PI Historian and GE PowerOn EMS run identifiers.',
    `forecast_run_timestamp` TIMESTAMP COMMENT 'The date and time at which the EMS forecasting engine initiated and completed the forecast run that produced this record. This is the principal business event timestamp representing when the forecast was generated, distinct from the interval being forecasted. Stored in ISO 8601 format (yyyy-MM-ddTHH:mm:ss.SSSXXX).',
    `forecast_status` STRING COMMENT 'Current lifecycle state of the forecast record. Draft indicates the forecast is being generated; published indicates it has been released for operational use; superseded indicates a newer forecast run has replaced it; archived indicates it has been retained for historical accuracy tracking; cancelled indicates the run was aborted.. Valid values are `draft|published|superseded|archived|cancelled`',
    `forecast_temperature_f` DECIMAL(18,2) COMMENT 'The forecasted ambient temperature in degrees Fahrenheit used as the primary weather input to the load forecasting model for this interval. Temperature is the dominant weather driver of electrical load in most utility service territories.',
    `forecasted_demand_mw` DECIMAL(18,2) COMMENT 'The primary forecasted electrical load demand in Megawatts (MW) for the specified interval. This is the principal quantitative output of the EMS forecasting engine, used for unit commitment, interchange scheduling, and next-day operations planning.',
    `heating_degree_days` DECIMAL(18,2) COMMENT 'The number of Heating Degree Days (HDD) for the forecast date, calculated as the number of degrees the mean daily temperature falls below 65°F. A standard weather normalization metric used in load forecasting models to quantify heating-driven electrical and gas demand.',
    `interchange_schedule_mw` DECIMAL(18,2) COMMENT 'The scheduled net interchange in Megawatts (MW) with neighboring balancing areas or the Regional Transmission Organization (RTO)/Independent System Operator (ISO) for this forecast interval. Positive values indicate net imports; negative values indicate net exports. Used in balancing area control and unit commitment.',
    `interval_duration_minutes` STRING COMMENT 'The length of the forecast interval in minutes (e.g., 15, 30, 60, 1440 for daily). Determines the granularity of the forecast and aligns with Advanced Metering Infrastructure (AMI) interval data and SCADA telemetry resolution.',
    `is_peak_period` BOOLEAN COMMENT 'Boolean flag indicating whether this forecast interval falls within a designated peak demand period as defined by the utilitys tariff or operational planning criteria. Used to identify intervals requiring heightened operational attention, DR dispatch readiness, and capacity reserve verification.',
    `is_reliability_event` BOOLEAN COMMENT 'Boolean flag indicating whether this forecast interval is associated with a declared reliability event (e.g., emergency operating condition, NERC alert, extreme weather advisory). When true, the forecast may have been produced under emergency protocols with modified model parameters.',
    `manual_override_flag` BOOLEAN COMMENT 'Boolean flag indicating whether an EMS operator manually overrode the model-generated forecast value for this interval. When true, the forecasted_demand_mw reflects an operator-adjusted value rather than the raw model output. Supports audit trail and model accuracy analysis.',
    `net_load_forecast_mw` DECIMAL(18,2) COMMENT 'The forecasted net load in Megawatts (MW) after subtracting Distributed Energy Resources (DER) generation (e.g., rooftop solar, behind-the-meter storage) from gross forecasted demand. Net load is the actual generation requirement that dispatchable resources must meet. Critical for unit commitment and interchange scheduling.',
    `operating_day` DATE COMMENT 'The NERC-defined operating day (midnight to midnight local time) to which this forecast record belongs. Distinct from forecast_date in that it represents the grid operations scheduling day used by the Regional Transmission Organization (RTO) or Independent System Operator (ISO) for market and reliability purposes.',
    `operating_reserve_requirement_mw` DECIMAL(18,2) COMMENT 'The minimum operating reserve requirement in Megawatts (MW) for this forecast interval, derived from the forecasted load and NERC reliability standards. Includes spinning and non-spinning reserves required to maintain grid reliability. Used for unit commitment and capacity planning.',
    `peak_demand_estimate_mw` DECIMAL(18,2) COMMENT 'The estimated peak electrical demand in Megawatts (MW) expected within the forecast period. Critical for capacity planning, reserve margin calculations, and Demand Response (DR) dispatch planning. Used in General Rate Case (GRC) filings and Integrated Resource Plan (IRP) submissions.',
    `regulatory_reporting_flag` BOOLEAN COMMENT 'Boolean flag indicating whether this forecast record is designated for inclusion in regulatory reporting submissions (e.g., EIA Form 930, FERC filings, NERC reliability assessments, PUC rate case filings). Supports automated extraction of reportable forecast data for compliance workflows.',
    `rto_iso_code` STRING COMMENT 'The code identifying the Regional Transmission Organization (RTO) or Independent System Operator (ISO) market in which this balancing area participates (e.g., PJM, MISO, CAISO, ERCOT, SPP). Determines the market rules, scheduling protocols, and reporting requirements applicable to this forecast.',
    `season` STRING COMMENT 'The utility-defined operating season for the forecast interval. Seasonal classification drives load shape selection in the EMS forecasting model and aligns with seasonal rate structures, capacity planning periods, and NERC reliability assessments.. Valid values are `summer|winter|spring|fall`',
    `source_system_code` STRING COMMENT 'Code identifying the operational system of record that produced or supplied this load forecast record. Supports data lineage and provenance tracking in the Silver Layer lakehouse. Values correspond to the utilitys operational systems including the Energy Management System (EMS), SCADA, OSIsoft PI Historian, Distribution Management System (DMS), Outage Management System (OMS), and DERMS. [ENUM-REF-CANDIDATE: EMS|SCADA|PI_HISTORIAN|DMS|OMS|DERMS|MANUAL — 7 candidates stripped; promote to reference product]',
    `updated_timestamp` TIMESTAMP COMMENT 'Audit timestamp recording the most recent modification to this load forecast record, such as when actual demand values were populated post-interval or when the forecast status was updated. Stored in ISO 8601 format (yyyy-MM-ddTHH:mm:ss.SSSXXX).',
    `weather_adjusted_baseline_mw` DECIMAL(18,2) COMMENT 'The weather-normalized baseline load demand in Megawatts (MW), representing what demand would be under normal or reference weather conditions. Used to isolate weather-driven load variability from underlying demand trends for regulatory reporting and Integrated Resource Plan (IRP) analysis.',
    `weather_station_code` BIGINT COMMENT 'Reference to the primary weather station or weather data source used to supply temperature, humidity, and other meteorological inputs to the load forecasting model for this forecast interval. Weather normalization is a core component of EMS load forecasting.',
    CONSTRAINT pk_load_forecast PRIMARY KEY(`load_forecast_id`)
) COMMENT 'Stores short-term (hourly/daily), medium-term (weekly/monthly), and persistence forecasts produced by the EMS forecasting engine for the balancing area and control zones. Includes forecasted MW demand by interval, weather-adjusted baseline, peak demand estimate, confidence interval, forecast model version, and actual vs. forecast variance for accuracy tracking. Used for unit commitment, interchange scheduling, DR dispatch planning, and next-day operations planning.';

CREATE OR REPLACE TABLE `power_and_utilities_v2`.`gridops`.`frequency_regulation_event` (
    `frequency_regulation_event_id` BIGINT COMMENT 'Unique surrogate identifier for each frequency regulation event record in the balancing area. Primary key for this data product.',
    `balancing_area_id` BIGINT COMMENT 'Reference to the NERC-registered Balancing Authority Area (BAA) in which this frequency regulation event occurred. Links to the balancing area master record for geographic and operational context.',
    `crew_member_id` BIGINT COMMENT 'Reference to the grid operations control room operator who acknowledged, responded to, or closed this frequency regulation event. Provides accountability traceability for manual operator interventions and NERC compliance documentation.',
    `employee_id` BIGINT COMMENT 'Reference to the grid operations control room operator who acknowledged, responded to, or closed this frequency regulation event. Provides accountability traceability for manual operator interventions and NERC compliance documentation.',
    `rate_case_id` BIGINT COMMENT 'Foreign key linking to regulatory.rate_case. Business justification: Frequency regulation performance is reported in rate‑case filings; linking each event to the rate case enables required reporting.',
    `ace_threshold_mw` DECIMAL(18,2) COMMENT 'The ACE threshold in Megawatts (MW) that, when exceeded, triggers a compliance event or corrective action. Derived from the Balancing Authoritys frequency bias setting and NERC BAL-001 control performance standards.',
    `ace_value_mw` DECIMAL(18,2) COMMENT 'Instantaneous Area Control Error (ACE) value in Megawatts (MW) at the time of the event. ACE represents the difference between actual and scheduled net interchange, adjusted for frequency bias. This is the authoritative ACE measurement for NERC BAL-001 real power balancing compliance.',
    `actual_interchange_mw` DECIMAL(18,2) COMMENT 'The actual measured net interchange in Megawatts (MW) with neighboring balancing areas at the time of the event, as recorded by SCADA/EMS metering. The difference between actual and scheduled interchange is a primary component of the ACE calculation.',
    `agc_response_mw` DECIMAL(18,2) COMMENT 'Total Megawatts (MW) of generation adjustment dispatched by the Automatic Generation Control (AGC) system in response to this frequency regulation event. Represents the corrective generation signal sent to participating generating units.',
    `baal_exceedance_flag` BOOLEAN COMMENT 'Indicates whether the Balancing Authority ACE Limit (BAAL) was exceeded during this event. True if ACE exceeded the BAAL threshold as defined in NERC BAL-001-2, triggering mandatory corrective action and potential compliance reporting.',
    `baal_high_mw` DECIMAL(18,2) COMMENT 'The upper Balancing Authority ACE Limit (BAAL) threshold in Megawatts (MW) applicable during this event interval. Defined per NERC BAL-001-2 and used to assess whether the balancing authority exceeded its allowable ACE boundary.',
    `baal_low_mw` DECIMAL(18,2) COMMENT 'The lower Balancing Authority ACE Limit (BAAL) threshold in Megawatts (MW) applicable during this event interval. Defined per NERC BAL-001-2 and used to assess whether the balancing authority exceeded its allowable ACE boundary on the under-generation side.',
    `control_area_code` STRING COMMENT 'NERC-assigned alphanumeric code identifying the Balancing Authority control area where the event occurred. Used in NERC compliance filings, RTO/ISO interchange scheduling, and energy balance reporting.. Valid values are `^[A-Z0-9]{2,10}$`',
    `corrective_action_taken` STRING COMMENT 'Narrative description of the corrective actions taken by the EMS/AGC system or grid operators to restore frequency and ACE to within compliance limits. Includes AGC dispatch instructions, manual operator interventions, and emergency procedures. Required for NERC BAL-002 disturbance control documentation.',
    `cps1_score` DECIMAL(18,2) COMMENT 'NERC Control Performance Standard 1 (CPS1) compliance score as a percentage for the reporting interval. CPS1 measures the one-minute average ACE divided by the frequency error, with a minimum compliance threshold of 100%. Values below 100% indicate non-compliance with NERC BAL-001.',
    `cps2_score` DECIMAL(18,2) COMMENT 'NERC Control Performance Standard 2 (CPS2) compliance score as a percentage for the reporting interval. CPS2 measures the 10-minute average ACE against the L10 limit, with a minimum compliance threshold of 90%. Values below 90% indicate non-compliance with NERC BAL-001.',
    `created_timestamp` TIMESTAMP COMMENT 'The date and time (UTC) when this frequency regulation event record was first created in the data lakehouse Silver layer. Used for data lineage, audit trail, and ETL reconciliation.',
    `disturbance_cause` STRING COMMENT 'Root cause classification of the frequency regulation event or disturbance. Used for post-event analysis, NERC BAL-002 disturbance control standard reporting, and operational reliability improvement. [ENUM-REF-CANDIDATE: generation_trip|load_loss|transmission_fault|interchange_error|equipment_failure|weather_event|unknown — promote to reference product]',
    `duration_seconds` STRING COMMENT 'Total elapsed duration of the frequency regulation event in seconds, calculated from event_start_timestamp to event_end_timestamp. Used for NERC BAL-002 disturbance control standard compliance assessment and operational performance reporting.',
    `ems_event_code` STRING COMMENT 'The native event identifier assigned by the Energy Management System (EMS) — specifically GE PowerOn — for this frequency regulation event. Used for cross-referencing between the lakehouse Silver layer and the operational EMS source system for audit and reconciliation purposes.',
    `event_code` STRING COMMENT 'Externally-known alphanumeric identifier assigned to this frequency regulation event, used in NERC compliance filings, RTO/ISO settlement reports, and operational logs. Format: FRE-{YYYY}-{NNNNNN}.. Valid values are `^FRE-[0-9]{4}-[0-9]{6}$`',
    `event_end_timestamp` TIMESTAMP COMMENT 'The precise date and time (UTC) when the frequency regulation event concluded and normal operating conditions were restored. Null if the event is still active. Used to compute event duration for NERC BAL-002 disturbance control standard compliance.',
    `event_severity` STRING COMMENT 'Operational severity classification of the frequency regulation event based on the magnitude of frequency deviation, ACE exceedance, and system impact. Used for prioritizing operator response, escalation workflows, and post-event reliability analysis.. Valid values are `informational|minor|moderate|major|critical`',
    `event_start_timestamp` TIMESTAMP COMMENT 'The precise date and time (UTC) when the frequency regulation event began, as recorded by the Energy Management System (EMS) or SCADA historian. This is the principal real-world event time used for NERC compliance interval calculations and RTO/ISO settlement.',
    `event_status` STRING COMMENT 'Current lifecycle state of the frequency regulation event record. active indicates the event is ongoing; resolved indicates corrective action has restored normal frequency; under_review indicates post-event analysis is in progress; reported indicates the event has been submitted to NERC/RTO; closed indicates all follow-up actions are complete.. Valid values are `active|resolved|under_review|reported|closed`',
    `event_type` STRING COMMENT 'Classification of the frequency regulation event. Distinguishes between frequency deviations from 60 Hz, Area Control Error (ACE) exceedances, Automatic Generation Control (AGC) response actions, disturbance control events, regulation reserve deployments, and Balancing Authority ACE Limit (BAAL) exceedances. [ENUM-REF-CANDIDATE: frequency_deviation|ace_exceedance|agc_response|disturbance_control|regulation_reserve_deployment|baal_exceedance — promote to reference product]. Valid values are `frequency_deviation|ace_exceedance|agc_response|disturbance_control|regulation_reserve_deployment|baal_exceedance`',
    `frequency_bias_setting_mw_per_hz` DECIMAL(18,2) COMMENT 'The balancing authoritys frequency bias setting in Megawatts per Hertz (MW/Hz) in effect during this event. Used in the ACE calculation formula: ACE = (NIA - NIS) - 10B(FA - FS). Must be reported to NERC and the RTO/ISO per BAL-001 and BAL-005 requirements.',
    `frequency_deviation_hz` DECIMAL(18,2) COMMENT 'Magnitude of frequency deviation from the 60 Hz nominal in Hertz (Hz). Positive values indicate over-frequency; negative values indicate under-frequency. Key metric for NERC BAL-003 frequency response obligation compliance and disturbance analysis.',
    `frequency_nadir_hz` DECIMAL(18,2) COMMENT 'The lowest instantaneous system frequency in Hertz (Hz) recorded during this event, representing the frequency nadir following a generation loss or load increase disturbance. Critical metric for NERC BAL-003 frequency response adequacy assessment.',
    `frequency_response_mw_per_hz` DECIMAL(18,2) COMMENT 'The balancing authoritys measured frequency response in Megawatts per Hertz (MW/Hz) during this event. Compared against the NERC-assigned Frequency Response Obligation (FRO) to assess BAL-003 compliance. A more negative value indicates stronger frequency response.',
    `interconnection_name` STRING COMMENT 'Name of the North American electrical interconnection (synchronous grid) within which this frequency regulation event occurred. Determines the nominal frequency standard (60 Hz) and the pool of balancing authorities sharing frequency response obligations.. Valid values are `Eastern|Western|ERCOT|Quebec|Alaska`',
    `interval_end_timestamp` TIMESTAMP COMMENT 'End timestamp (UTC) of the energy accounting interval associated with this record. Paired with interval_start_timestamp to define the precise measurement window for energy balance and ACE compliance calculations.',
    `interval_start_timestamp` TIMESTAMP COMMENT 'Start timestamp (UTC) of the energy accounting interval associated with this record. Used to align hourly and sub-hourly energy balance data (generation, load, interchange, losses) with RTO/ISO settlement periods and NERC BAL-001 compliance measurement windows.',
    `nerc_reportable_flag` BOOLEAN COMMENT 'Indicates whether this frequency regulation event meets the threshold for mandatory reporting to NERC under applicable reliability standards (BAL-001, BAL-002, BAL-003). True if the event must be included in NERC compliance filings or event analysis submissions.',
    `nerc_violation_flag` BOOLEAN COMMENT 'Indicates whether this event resulted in a confirmed violation of a NERC reliability standard (e.g., BAL-001 CPS1/CPS2 non-compliance, BAL-002 disturbance control failure, BAL-003 frequency response obligation shortfall). True triggers mandatory NERC self-report or enforcement action.',
    `net_interchange_mwh` DECIMAL(18,2) COMMENT 'Net energy interchange with neighboring balancing areas during the event interval, expressed in Megawatt-Hours (MWh). Positive values indicate net export; negative values indicate net import. Core component of the ACE calculation and energy balance accounting per NERC BAL-001.',
    `pi_tag_reference` STRING COMMENT 'The OSIsoft PI Historian tag name or tag path associated with the primary frequency or ACE measurement for this event. Enables direct traceability from the Silver layer record back to the real-time operational data stream in the PI Historian for validation and reprocessing.',
    `regulation_down_mw` DECIMAL(18,2) COMMENT 'Megawatts (MW) of regulation-down reserve deployed during this event to decrease generation output and correct an over-frequency or positive ACE condition. Reported separately for RTO/ISO market settlement and NERC BAL-002 compliance.',
    `regulation_reserve_deployed_mw` DECIMAL(18,2) COMMENT 'Total regulation reserve capacity deployed in Megawatts (MW) during this event. Includes both regulation-up and regulation-down resources activated to restore ACE to within compliance limits. Used for RTO/ISO settlement and reserve adequacy reporting.',
    `regulation_up_mw` DECIMAL(18,2) COMMENT 'Megawatts (MW) of regulation-up reserve deployed during this event to increase generation output and correct an under-frequency or negative ACE condition. Reported separately for RTO/ISO market settlement and NERC BAL-002 compliance.',
    `reporting_interval_type` STRING COMMENT 'The sub-hourly or hourly interval granularity for energy accounting data associated with this event record. Determines the resolution of generation, load, interchange, and ACE values stored. Aligns with RTO/ISO settlement interval requirements and NERC BAL-001 compliance measurement periods.. Valid values are `one_minute|five_minute|ten_minute|fifteen_minute|thirty_minute|hourly`',
    `rto_iso_code` BIGINT COMMENT 'Reference to the Regional Transmission Organization (RTO) or Independent System Operator (ISO) under whose market rules and settlement protocols this frequency regulation event is reported. Links to the RTO/ISO master record for market context.',
    `scheduled_interchange_mw` DECIMAL(18,2) COMMENT 'The net scheduled interchange in Megawatts (MW) with neighboring balancing areas at the time of the event, as agreed through the interchange scheduling process. Used in the ACE calculation and compared against actual interchange to determine the interchange component of ACE.',
    `settlement_interval_code` BIGINT COMMENT 'Reference to the RTO/ISO market settlement interval record associated with this energy balance event. Links frequency regulation and energy accounting data to the corresponding Day-Ahead Market (DAM) or Real-Time Market (RTM) settlement period.',
    `system_frequency_hz` DECIMAL(18,2) COMMENT 'Measured system frequency in Hertz (Hz) at the time of the event trigger. Nominal value is 60.000 Hz for North American interconnections. Deviations from 60 Hz trigger frequency regulation responses per NERC BAL-003 frequency response obligations.',
    `system_losses_mwh` DECIMAL(18,2) COMMENT 'Estimated transmission and distribution system losses in Megawatt-Hours (MWh) during the event interval. Used in energy balance reconciliation: Generation = Load + Net Interchange + Losses. Supports NERC BAL-001 energy accounting and EIA reporting.',
    `total_generation_mwh` DECIMAL(18,2) COMMENT 'Total electrical energy generated within the balancing area during the event interval, expressed in Megawatt-Hours (MWh). Authoritative value for energy balance accounting, RTO/ISO settlement, and NERC BAL-001 real power balancing compliance.',
    `total_load_mwh` DECIMAL(18,2) COMMENT 'Total electrical energy consumed by load within the balancing area during the event interval, expressed in Megawatt-Hours (MWh). Used for energy balance verification, RTO/ISO settlement, and NERC BAL-001 compliance reporting.',
    `updated_timestamp` TIMESTAMP COMMENT 'The date and time (UTC) when this frequency regulation event record was most recently modified in the data lakehouse Silver layer. Tracks post-event corrections, operator annotations, and compliance status updates.',
    CONSTRAINT pk_frequency_regulation_event PRIMARY KEY(`frequency_regulation_event_id`)
) COMMENT 'Captures frequency regulation events, ACE (Area Control Error) exceedances, AGC response actions, and serves as the single source of truth for all energy balance and frequency compliance data for the balancing area. Records include: frequency deviations from 60 Hz, CPS1/CPS2/BAAL compliance metrics, regulation reserve deployment, and corrective actions taken. Also stores hourly and sub-hourly energy accounting: total generation (MWh), total load (MWh), net interchange (MWh), system losses, and ACE values by interval. Supports NERC BAL-001 (real power balancing), BAL-002 (disturbance control), BAL-003 (frequency response), energy balance reporting for RTO/ISO settlement, and operational energy accounting. This is the authoritative product for all ACE-related data, frequency compliance, and energy balance records.';

CREATE OR REPLACE TABLE `power_and_utilities_v2`.`gridops`.`voltage_control_action` (
    `voltage_control_action_id` BIGINT COMMENT 'Unique identifier for the voltage control action record.',
    `approver_employee_id` BIGINT COMMENT 'Reference to the supervisor or reliability coordinator who approved the voltage control action. Null if no approval was required.',
    `approver_id` BIGINT COMMENT 'Reference to the supervisor or reliability coordinator who approved the voltage control action. Null if no approval was required.',
    `balancing_area_id` BIGINT COMMENT 'Foreign key linking to gridops.balancing_area. Business justification: Voltage control actions occur within a balancing area; FK replaces textual code.',
    `bus_id` BIGINT COMMENT 'Reference to the electrical bus that was the target of the voltage control action.',
    `employee_id` BIGINT COMMENT 'Reference to the grid operator who initiated the manual voltage control action. Null if action was automated.',
    `ems_dispatch_ems_dispatch_instruction_id` BIGINT COMMENT 'The dispatch instruction identifier from the Energy Management System that authorized or triggered this voltage control action.',
    `ems_dispatch_instruction_id` BIGINT COMMENT 'The dispatch instruction identifier from the Energy Management System that authorized or triggered this voltage control action.',
    `gridops_outage_event_id` BIGINT COMMENT 'Reference to an outage record if this voltage control action was related to outage management or restoration activities.',
    `outage_gridops_outage_event_id` BIGINT COMMENT 'Reference to an outage record if this voltage control action was related to outage management or restoration activities.',
    `primary_voltage_employee_id` BIGINT COMMENT 'Reference to the grid operator who initiated the manual voltage control action. Null if action was automated.',
    `registry_id` BIGINT COMMENT 'Reference to the specific control device (capacitor bank, reactor, tap changer, or reactive power source) that was operated.',
    `reliability_event_id` BIGINT COMMENT 'Reference to a reliability event record if this voltage control action was taken in response to a grid reliability event or contingency.',
    `scada_point_id` BIGINT COMMENT 'Reference to the SCADA monitoring point where the voltage control action was executed.',
    `transmission_substation_id` BIGINT COMMENT 'Reference to the substation where the voltage control action occurred.',
    `verified_by_operator_employee_id` BIGINT COMMENT 'Reference to the operator who verified the successful completion and effectiveness of the voltage control action.',
    `action_duration_seconds` STRING COMMENT 'The time in seconds from action initiation to completion or failure.',
    `action_mode` STRING COMMENT 'Indicates whether the voltage control action was initiated manually by an operator, automatically by control system, scheduled as part of planned operations, or triggered by emergency conditions.. Valid values are `manual|automatic|scheduled|emergency`',
    `action_notes` STRING COMMENT 'Free-text notes or comments entered by the operator or system regarding the voltage control action, including justification, observations, or special circumstances.',
    `action_priority` STRING COMMENT 'The operational priority level assigned to the voltage control action based on the severity of the voltage deviation and potential impact on grid reliability.. Valid values are `routine|elevated|high|critical|emergency`',
    `action_status` STRING COMMENT 'The execution status of the voltage control action indicating whether it completed successfully, failed, partially completed, was aborted, or is pending verification.. Valid values are `successful|failed|partial|aborted|pending_verification`',
    `action_timestamp` TIMESTAMP COMMENT 'The precise date and time when the voltage control action was executed in the grid.',
    `action_type` STRING COMMENT 'The type of voltage control action performed. [ENUM-REF-CANDIDATE: capacitor_bank_switch_on|capacitor_bank_switch_off|reactor_switch_on|reactor_switch_off|tap_changer_raise|tap_changer_lower|reactive_power_increase|reactive_power_decrease|voltage_regulator_adjust — promote to reference product]. Valid values are `capacitor_bank_switch_on|capacitor_bank_switch_off|reactor_switch_on|reactor_switch_off|tap_changer_raise|tap_changer_lower`',
    `ambient_temperature_c` DECIMAL(18,2) COMMENT 'The ambient temperature in degrees Celsius at the substation location at the time of the voltage control action.',
    `approval_required_flag` BOOLEAN COMMENT 'Boolean indicator of whether the voltage control action required supervisory or reliability coordinator approval before execution.',
    `approval_timestamp` TIMESTAMP COMMENT 'The date and time when supervisory approval was granted for the voltage control action. Null if no approval was required.',
    `automation_system_source` STRING COMMENT 'The name or identifier of the automated control system that initiated the voltage control action (e.g., DMS, DERMS, voltage regulator controller). Null if action was manual.',
    `capacitor_bank_mvar` DECIMAL(18,2) COMMENT 'The reactive power rating in megavolt-amperes reactive of the capacitor bank that was switched. Null if action did not involve a capacitor bank.',
    `control_algorithm` STRING COMMENT 'The name or identifier of the control algorithm or logic used to determine the voltage control action (e.g., volt-var optimization, conservation voltage reduction, local voltage control). Null if action was manual.',
    `created_timestamp` TIMESTAMP COMMENT 'The date and time when this voltage control action record was first created in the system.',
    `generation_at_action_mw` DECIMAL(18,2) COMMENT 'The total real power generation in megawatts at the target bus or substation at the time the voltage control action was executed.',
    `initiating_condition` STRING COMMENT 'The operational condition or event that triggered the need for voltage control action.. Valid values are `voltage_deviation|load_increase|load_decrease|generation_change|contingency_event|scheduled_maintenance`',
    `last_modified_timestamp` TIMESTAMP COMMENT 'The date and time when this voltage control action record was last updated in the system.',
    `load_at_action_mw` DECIMAL(18,2) COMMENT 'The total real power load in megawatts at the target bus or substation at the time the voltage control action was executed.',
    `post_action_voltage_kv` DECIMAL(18,2) COMMENT 'The voltage level in kilovolts measured at the target bus immediately after the control action was executed.',
    `power_factor_post_action` DECIMAL(18,2) COMMENT 'The power factor measured at the target bus immediately after the voltage control action was executed. Value ranges from -1.0 to 1.0.',
    `power_factor_pre_action` DECIMAL(18,2) COMMENT 'The power factor measured at the target bus immediately before the voltage control action was executed. Value ranges from -1.0 to 1.0.',
    `pre_action_voltage_kv` DECIMAL(18,2) COMMENT 'The voltage level in kilovolts measured at the target bus immediately before the control action was executed.',
    `reactive_power_change_mvar` DECIMAL(18,2) COMMENT 'The change in reactive power in megavolt-amperes reactive resulting from the voltage control action. Positive values indicate reactive power injection, negative values indicate absorption.',
    `reactor_mvar` DECIMAL(18,2) COMMENT 'The reactive power rating in megavolt-amperes reactive of the reactor that was switched. Null if action did not involve a reactor.',
    `switching_order_number` STRING COMMENT 'The formal switching order number associated with this voltage control action, if the action was part of a planned switching procedure.',
    `tap_position_change` STRING COMMENT 'The number of tap positions changed on a tap changer device. Positive values indicate raise operations, negative values indicate lower operations. Null if action did not involve a tap changer.',
    `target_voltage_kv` DECIMAL(18,2) COMMENT 'The desired voltage level in kilovolts that the control action was intended to achieve at the target bus.',
    `verification_timestamp` TIMESTAMP COMMENT 'The date and time when the effectiveness of the voltage control action was verified through post-action monitoring.',
    `voltage_deviation_percent` DECIMAL(18,2) COMMENT 'The percentage deviation of pre-action voltage from the nominal voltage level, calculated as ((pre_action_voltage - nominal_voltage) / nominal_voltage) * 100.',
    `voltage_profile_compliance_flag` BOOLEAN COMMENT 'Boolean indicator of whether the post-action voltage level is within the acceptable voltage profile limits defined by regulatory standards and operational procedures.',
    `weather_condition` STRING COMMENT 'The prevailing weather condition at the time of the voltage control action, which may influence load patterns and voltage stability. [ENUM-REF-CANDIDATE: clear|cloudy|rain|snow|storm|extreme_heat|extreme_cold|fog|wind — promote to reference product]',
    CONSTRAINT pk_voltage_control_action PRIMARY KEY(`voltage_control_action_id`)
) COMMENT 'Records operator and automated voltage control actions taken within the grid including capacitor bank switching, reactor switching, tap changer adjustments, and reactive power dispatch. Captures target bus, pre-action voltage (kV), post-action voltage (kV), action type, initiating condition, and operator or automation source. Supports voltage profile compliance and post-event review.';

CREATE OR REPLACE TABLE `power_and_utilities_v2`.`gridops`.`gridops_switching_order` (
    `gridops_switching_order_id` BIGINT COMMENT 'Unique identifier for the switching order record in the grid operations system.',
    `approving_supervisor_employee_id` BIGINT COMMENT 'Reference to the grid operations supervisor or reliability coordinator who reviewed and approved this switching order for execution.',
    `balancing_area_id` BIGINT COMMENT 'Foreign key linking to gridops.balancing_area. Business justification: GridOps switching orders are tied to a balancing area; FK replaces textual code.',
    `employee_id` BIGINT COMMENT 'Reference to the grid operations control center operator who created and issued this switching order.',
    `crew_id` BIGINT COMMENT 'Reference to the field crew or operations team assigned to physically execute the switching steps in this order.',
    `gridops_outage_event_id` BIGINT COMMENT 'Reference to the associated planned outage record in the Outage Management System (OMS) if this switching order is coordinated with customer outage notifications.',
    `oms_outage_gridops_outage_event_id` BIGINT COMMENT 'Reference to the associated planned outage record in the Outage Management System (OMS) if this switching order is coordinated with customer outage notifications.',
    `incident_id` BIGINT COMMENT 'Reference to the grid operations incident or reliability event that triggered this switching order, if applicable (e.g., fault, equipment failure, system disturbance).',
    `purchase_order_id` BIGINT COMMENT 'Foreign key linking to supply.purchase_order. Business justification: Regulatory cost allocation report requires linking each switching order to the purchase order that procured materials for the work.',
    `transmission_substation_id` BIGINT COMMENT 'Reference to the primary substation where the switching operations will be performed.',
    `warehouse_id` BIGINT COMMENT 'Foreign key linking to supply.warehouse. Business justification: Spare parts for switching orders are drawn from specific warehouses; linking enables inventory audit and cost tracking.',
    `work_order_id` BIGINT COMMENT 'Reference to the associated maintenance or construction work order that requires this switching order for equipment isolation or energization.',
    `actual_completion_timestamp` TIMESTAMP COMMENT 'The actual date and time when the final switching step in this order was completed and the order was closed.',
    `actual_start_timestamp` TIMESTAMP COMMENT 'The actual date and time when execution of the first switching step in this order was initiated by the field crew or control center operator.',
    `affected_circuit_count` STRING COMMENT 'The number of electrical circuits (feeders, transmission lines, or distribution circuits) that will be impacted by the execution of this switching order.',
    `approval_timestamp` TIMESTAMP COMMENT 'The date and time when the approving supervisor or reliability coordinator formally approved this switching order for execution.',
    `approving_supervisor_name` STRING COMMENT 'Full name of the operations supervisor or reliability coordinator who approved this switching order.',
    `cancellation_reason` STRING COMMENT 'Detailed explanation of why this switching order was cancelled, including operational conditions, safety concerns, or work scope changes that led to cancellation.',
    `cancellation_timestamp` TIMESTAMP COMMENT 'The date and time when this switching order was cancelled or voided, if applicable.',
    `created_timestamp` TIMESTAMP COMMENT 'The date and time when this switching order record was first created in the grid operations system.',
    `emergency_restoration_flag` BOOLEAN COMMENT 'Boolean indicator whether this switching order is part of an emergency restoration effort following an unplanned outage or system disturbance. True indicates emergency restoration.',
    `estimated_customer_impact_count` STRING COMMENT 'The estimated number of customer accounts that may experience service interruption or voltage fluctuation during the execution of this switching order.',
    `issuing_operator_name` STRING COMMENT 'Full name of the certified system operator who created and issued this switching order.',
    `last_modified_timestamp` TIMESTAMP COMMENT 'The date and time when this switching order record was most recently updated or modified.',
    `loto_tag_numbers` STRING COMMENT 'Comma-separated list of Lock Out Tag Out (LOTO) tag numbers applied to equipment as part of this switching order to ensure worker safety during de-energized work.',
    `network_segment` STRING COMMENT 'The segment of the electrical network where the switching order will be executed: transmission (high-voltage bulk power), distribution (medium/low-voltage customer delivery), substation (transformation and switching facilities), or generation (power plant interconnection).. Valid values are `transmission|distribution|substation|generation`',
    `notes` STRING COMMENT 'Free-form operational notes, special instructions, or additional context provided by the issuing operator or approving supervisor for this switching order.',
    `order_number` STRING COMMENT 'Externally-known unique switching order number assigned by the grid operations center for tracking and reference. Format: SO-YYYYMMDD-SITE.. Valid values are `^SO-[0-9]{8}-[A-Z]{2,4}$`',
    `order_purpose` STRING COMMENT 'Detailed business justification and operational purpose for issuing this switching order, including work scope, equipment involved, and expected outcomes.',
    `order_status` STRING COMMENT 'Current lifecycle status of the switching order: draft (being prepared), pending approval (awaiting supervisor review), approved (ready for execution), in progress (actively executing steps), completed (all steps executed), cancelled (order voided), or suspended (temporarily halted). [ENUM-REF-CANDIDATE: draft|pending_approval|approved|in_progress|completed|cancelled|suspended — 7 candidates stripped; promote to reference product]',
    `order_type` STRING COMMENT 'Classification of the switching order based on operational purpose: planned maintenance isolation, emergency fault restoration, fault isolation, load transfer, construction support, or equipment testing.. Valid values are `planned_maintenance|emergency_restoration|fault_isolation|load_transfer|construction_support|testing`',
    `outage_coordination_required_flag` BOOLEAN COMMENT 'Boolean indicator whether this switching order requires coordination with the Outage Management System (OMS) for planned customer outage notifications. True indicates OMS coordination is required.',
    `priority_level` STRING COMMENT 'Operational priority classification for the switching order: emergency (immediate safety or reliability threat), high (critical infrastructure), medium (scheduled maintenance), or low (routine work).. Valid values are `emergency|high|medium|low`',
    `reliability_impact_assessment` STRING COMMENT 'Documented assessment of the potential impact of this switching order on system reliability, including contingency analysis, N-1 criteria evaluation, and risk mitigation measures.',
    `safety_clearance_required_flag` BOOLEAN COMMENT 'Boolean indicator whether this switching order requires formal safety clearance and Lock Out Tag Out (LOTO) procedures before execution. True indicates safety clearance is mandatory.',
    `scada_monitoring_enabled_flag` BOOLEAN COMMENT 'Boolean indicator whether real-time SCADA monitoring and telemetry is enabled for the equipment and circuits affected by this switching order. True indicates SCADA monitoring is active.',
    `scheduled_completion_timestamp` TIMESTAMP COMMENT 'The planned date and time when execution of this switching order is expected to be completed, including all steps and restoration.',
    `scheduled_start_timestamp` TIMESTAMP COMMENT 'The planned date and time when execution of this switching order is scheduled to begin.',
    `sequence_validation_status` STRING COMMENT 'Status of automated or manual validation of the switching step sequence for electrical safety, operational feasibility, and compliance with switching procedures: not validated, validated (passed all checks), validation failed (errors detected), or override approved (validation bypassed by authority).. Valid values are `not_validated|validated|validation_failed|override_approved`',
    `source_system` STRING COMMENT 'The operational system of record that originated this switching order data (e.g., GE PowerOn DMS/OMS, SCADA EMS).',
    `switching_procedure_reference` STRING COMMENT 'Reference to the standard operating procedure (SOP) or switching instruction document that governs the execution of this switching order, including document number and version.',
    `switching_step_count` STRING COMMENT 'The total number of discrete switching steps (individual device operations) defined in this switching order sequence.',
    `voltage_class_kv` DECIMAL(18,2) COMMENT 'The nominal voltage class in kilovolts (kV) of the equipment and network segment affected by this switching order (e.g., 765, 500, 345, 230, 138, 69, 34.5, 13.8, 4.16 kV).',
    `weather_conditions` STRING COMMENT 'Documented weather conditions at the time of switching order execution, relevant for safety assessment and operational decision-making (e.g., clear, rain, snow, high wind, lightning).',
    CONSTRAINT pk_gridops_switching_order PRIMARY KEY(`gridops_switching_order_id`)
) COMMENT 'Manages switching orders issued by grid operations for planned and emergency switching sequences on the transmission and distribution network. Each order contains a header (order number, purpose, issuing operator, approving supervisor, execution status, safety clearances, LOTO tags) and an ordered sequence of switching steps (discrete actions on breakers, switches, and disconnects with per-step device identifier, action type, required safety tag, completion timestamp, executing operator, and sequence validation). Integrates with GE PowerOn DMS/OMS. Supports planned maintenance isolation, emergency fault restoration, and safety compliance tracking through granular step-level execution audit.';

CREATE OR REPLACE TABLE `power_and_utilities_v2`.`gridops`.`switching_step` (
    `switching_step_id` BIGINT COMMENT 'Unique system-generated identifier for each individual switching step record within the Databricks Silver Layer. Serves as the primary key for this entity.',
    `authorizing_operator_employee_id` BIGINT COMMENT 'Reference to the control room operator or supervisor who authorized execution of this switching step. Supports two-person integrity requirements and chain-of-command compliance for high-voltage switching operations.',
    `crew_id` BIGINT COMMENT 'Foreign key linking to workforce.crew. Business justification: Each switching step is executed by a crew; linking enables tracking crew performance and safety compliance.',
    `network_device_id` BIGINT COMMENT 'Reference to the specific grid device (breaker, switch, disconnect, recloser, sectionalizer) on which this switching action is to be performed. Links to the asset registry in the Distribution Management System (DMS) or GIS.',
    `distribution_substation_id` BIGINT COMMENT 'Reference to the substation or switching station where the target device is physically located. Used for geographic and operational context in outage management and grid operations.',
    `employee_id` BIGINT COMMENT 'Reference to the operator or field technician who physically executed or confirmed execution of this switching step. Provides accountability and traceability for safety compliance and post-event analysis.',
    `feeder_id` BIGINT COMMENT 'Reference to the distribution feeder circuit associated with the device being switched. Enables load flow analysis and outage impact assessment at the feeder level.',
    `gridops_outage_event_id` BIGINT COMMENT 'Reference to the associated outage event in the Outage Management System (OMS) that this switching step is part of restoring or isolating. Links switching activity to customer impact and SAIDI/SAIFI metrics.',
    `gridops_switching_order_id` BIGINT COMMENT 'Foreign key linking to gridops.gridops_switching_order. Business justification: Switching steps belong to an internal GridOps switching order; FK creates proper parent‑child link.',
    `person_id` BIGINT COMMENT 'Reference to the operator or field technician who physically executed or confirmed execution of this switching step. Provides accountability and traceability for safety compliance and post-event analysis.',
    `scada_point_id` BIGINT COMMENT 'The SCADA telemetry point identifier associated with the target device for this switching step. Used to retrieve real-time device status from the OSIsoft PI Historian or EMS/DMS SCADA system.',
    `work_order_id` BIGINT COMMENT 'Reference to the Maximo work order associated with the maintenance or construction activity that necessitated this switching step. Links switching operations to asset maintenance workflows.',
    `action_type` STRING COMMENT 'The discrete switching action to be performed in this step. Defines the specific operation on the identified device: open or close a breaker/switch, apply or remove a ground, or isolate/energize a section of the grid.. Valid values are `open|close|ground|de-ground|isolate|energize`',
    `actual_execution_timestamp` TIMESTAMP COMMENT 'The actual date and time at which this switching step was physically completed by the executing operator. Used for outage duration calculations, SAIDI/SAIFI reporting, and post-switching analysis.',
    `arc_flash_boundary_ft` DECIMAL(18,2) COMMENT 'The calculated arc flash protection boundary in feet for the device associated with this switching step, as determined by arc flash hazard analysis. Defines the minimum safe approach distance for personnel.',
    `communication_method` STRING COMMENT 'The method used to communicate the switching instruction between the control room operator and the field operator for this step. Documents the communication channel for audit trail and NERC compliance purposes.. Valid values are `radio|telephone|in_person|scada_remote|automated`',
    `confirmed_timestamp` TIMESTAMP COMMENT 'The date and time at which the control room operator confirmed receipt of the completed step notification from the field operator. Captures the two-way communication verification required for safe switching operations.',
    `created_timestamp` TIMESTAMP COMMENT 'The date and time at which this switching step record was first created in the system, typically when the switching order was drafted and steps were defined. Supports audit trail and data lineage requirements.',
    `critical_customer_impacted` BOOLEAN COMMENT 'Indicates whether this switching step affects one or more critical customers (hospitals, emergency services, water treatment facilities, or other life-safety accounts). Triggers priority restoration protocols and regulatory notification requirements.',
    `customers_affected_count` STRING COMMENT 'The number of customer service points that are de-energized or affected as a direct result of this switching step. Used for outage impact assessment, SAIDI/SAIFI calculations, and customer notification prioritization.',
    `deviation_reason` STRING COMMENT 'Explanation for any deviation from the planned switching step, such as a step being skipped, reordered, or modified during execution. Required for post-event review and regulatory compliance documentation.',
    `device_name` STRING COMMENT 'Human-readable name or label of the grid device targeted by this switching step, as maintained in the Distribution Management System (DMS) or GIS asset registry. Supports operator identification in the field.',
    `device_state_after` STRING COMMENT 'The verified state of the switching device immediately after this step was executed. Confirms the post-condition of the device and validates that the intended switching action was successfully completed.. Valid values are `open|closed|grounded|unknown`',
    `device_state_before` STRING COMMENT 'The verified state of the switching device immediately before this step was executed. Confirms the pre-condition of the device and supports post-event reconstruction of grid topology changes.. Valid values are `open|closed|grounded|unknown`',
    `device_type` STRING COMMENT 'Classification of the grid switching device targeted by this step. Indicates the physical type of apparatus to be operated, which determines the applicable operating procedure and safety requirements.. Valid values are `breaker|switch|recloser|sectionalizer|disconnect|fuse`',
    `executing_operator_name` STRING COMMENT 'Full name of the operator or field technician who executed this switching step. Captured at time of execution for audit trail and regulatory compliance purposes.',
    `gis_feature_reference` STRING COMMENT 'The unique feature identifier of the target device in the Esri ArcGIS geospatial asset management system. Enables spatial analysis, field crew navigation, and integration with the Distribution Management System (DMS) network model.',
    `last_updated_timestamp` TIMESTAMP COMMENT 'The date and time at which this switching step record was most recently modified, such as when step status was updated, notes were added, or execution was confirmed. Supports change tracking and audit compliance.',
    `load_current_amps` DECIMAL(18,2) COMMENT 'The measured or estimated load current in amperes flowing through the device at the time of the switching step. Used to assess whether the switching operation is within the devices rated interrupting capacity.',
    `network_model_node_code` STRING COMMENT 'The node identifier of the target device within the DMS/EMS network connectivity model. Used for power flow analysis, load flow calculations, and topology processing to validate switching step safety.',
    `ppe_required` STRING COMMENT 'Description of the minimum Personal Protective Equipment (PPE) required for safe execution of this switching step, such as arc flash suit rating, rubber gloves class, and face shield requirements per OSHA and NFPA 70E standards.',
    `protective_relay_coordination` BOOLEAN COMMENT 'Indicates whether protective relay coordination checks are required before executing this switching step. Ensures that relay settings and protection schemes remain valid after the switching operation to prevent cascading failures.',
    `remote_operation` BOOLEAN COMMENT 'Indicates whether this switching step was executed remotely from the control room via SCADA/DMS, as opposed to a manual field operation by a crew member. Distinguishes automated from manual switching for reliability analysis.',
    `repeat_back_verified` BOOLEAN COMMENT 'Indicates whether the field operator performed a verbal repeat-back of the switching instruction to the control room operator prior to execution, as required by NERC operating procedures for safe switching.',
    `safety_tag_number` STRING COMMENT 'The unique identifier of the safety tag (hold tag, caution tag, or danger tag) associated with this switching step. Required for lockout/tagout (LOTO) compliance tracking and personnel protection verification.',
    `safety_tag_required` BOOLEAN COMMENT 'Indicates whether a safety tag (hold tag, caution tag, or danger tag) must be applied or verified before this switching step can be executed. Critical for personnel safety and OSHA compliance.',
    `safety_tag_type` STRING COMMENT 'Classification of the safety tag associated with this switching step. Distinguishes between hold tags (prohibit operation), caution tags (warn of hazard), danger tags (imminent hazard), and clearance tags (work authorization).. Valid values are `hold|caution|danger|clearance|none`',
    `scada_verified` BOOLEAN COMMENT 'Indicates whether the device state change for this switching step was independently verified by the Supervisory Control and Data Acquisition (SCADA) system, providing automated confirmation beyond operator verbal report.',
    `scheduled_execution_timestamp` TIMESTAMP COMMENT 'The planned date and time at which this switching step is scheduled to be executed, as defined in the approved switching order. Used for outage coordination and crew scheduling.',
    `source_system_step_reference` STRING COMMENT 'The native identifier of this switching step record in the originating operational system (GE PowerOn DMS/OMS). Preserves the source system key for data lineage, reconciliation, and cross-system traceability in the Silver Layer.',
    `step_instruction` STRING COMMENT 'Detailed written instruction describing the exact action to be performed in this switching step, including device location, access method, and any special precautions. Provides the field operator with unambiguous direction.',
    `step_notes` STRING COMMENT 'Free-text field for operator notes, observations, or deviations recorded at the time of step execution. Captures field conditions, anomalies, or explanations for skipped or failed steps.',
    `step_number` STRING COMMENT 'Sequential position of this switching step within the parent switching order. Defines the mandatory execution order of discrete switching actions to ensure safe and correct grid reconfiguration.',
    `step_status` STRING COMMENT 'Current execution lifecycle state of this individual switching step. Tracks whether the step is awaiting execution, actively being performed, successfully completed, skipped per approved deviation, failed, or cancelled.. Valid values are `pending|in_progress|completed|skipped|failed|cancelled`',
    `step_type` STRING COMMENT 'Classifies the nature of this switching step within the overall switching plan. Primary steps are the core switching actions; contingency steps are alternatives; restoration steps return the grid to normal; verification steps confirm device state; notification steps record required communications.. Valid values are `primary|contingency|restoration|verification|notification`',
    `switching_purpose` STRING COMMENT 'The operational reason or purpose for which this switching step is being performed. Classifies the switching activity to support reliability reporting, outage analysis, and regulatory compliance categorization. [ENUM-REF-CANDIDATE: planned_maintenance|emergency_restoration|load_transfer|fault_isolation|construction|testing — promote to reference product if additional values are needed]. Valid values are `planned_maintenance|emergency_restoration|load_transfer|fault_isolation|construction|testing`',
    `voltage_level_kv` DECIMAL(18,2) COMMENT 'The nominal operating voltage level in kilovolts (kV) of the circuit or equipment associated with this switching step. Determines the applicable safety clearance distances, PPE requirements, and operating procedures.',
    CONSTRAINT pk_switching_step PRIMARY KEY(`switching_step_id`)
) COMMENT 'Individual step within a switching order defining a single discrete switching action (open/close breaker, isolate section, ground equipment). Captures step sequence number, device identifier, action type, required safety tag, completion timestamp, and executing operator. Enables granular tracking of switching sequence execution and safety compliance.';

CREATE OR REPLACE TABLE `power_and_utilities_v2`.`gridops`.`gridops_outage_event` (
    `gridops_outage_event_id` BIGINT COMMENT 'Unique identifier for the grid outage event record. Primary key for the outage event entity in the Outage Management System (OMS).',
    `asset_registry_id` BIGINT COMMENT 'Foreign key linking to asset.registry. Business justification: Required for Outage Management Report: each outage event must identify the primary asset that caused the failure for regulatory reporting and restoration planning.',
    `balancing_area_id` BIGINT COMMENT 'Foreign key linking to gridops.balancing_area. Business justification: Outage events are scoped to a balancing area; FK provides relational integrity.',
    `cost_center_id` BIGINT COMMENT 'Foreign key linking to finance.cost_center. Business justification: Supports Outage Cost Recovery and regulatory reporting by assigning outage events to a cost center.',
    `crew_id` BIGINT COMMENT 'Foreign key linking to workforce.crew. Business justification: Outage Management assigns a primary crew responsible for restoration; needed for outage restoration reporting.',
    `filing_id` BIGINT COMMENT 'Foreign key linking to regulatory.filing. Business justification: Regulatory outage reporting filing (e.g., FERC Form 1) requires linking each outage event to its filing for compliance.',
    `incident_id` BIGINT COMMENT 'Foreign key linking to safety.incident. Business justification: Regulatory outage report requires linking each outage event to a safety incident for compliance and root‑cause analysis.',
    `incident_ticket_id` BIGINT COMMENT 'Foreign key linking to technology.incident_ticket. Business justification: Outage events generate IT incident tickets for system issues; linking enables root‑cause tracking and IT service level compliance.',
    `purchase_order_id` BIGINT COMMENT 'Foreign key linking to supply.purchase_order. Business justification: Repair work after an outage is often funded by a purchase order; linking supports restoration cost reporting and budgeting.',
    `registry_id` BIGINT COMMENT 'Unique identifier of the specific equipment asset that failed. Links to Maximo EAM for asset history, maintenance records, and replacement tracking.',
    `resource_id` BIGINT COMMENT 'Foreign key linking to der.der_resource. Business justification: Outage management tracks which DER resources are impacted to coordinate restoration and reliability reporting.',
    `storm_event_id` BIGINT COMMENT 'Foreign key linking to workforce.storm_event. Business justification: Storm‑caused outages must be linked to the originating storm event for emergency response coordination and reporting.',
    `vendor_id` BIGINT COMMENT 'Foreign key linking to supply.vendor. Business justification: Outage restoration contracts external vendors; reporting (FERC/NERC) mandates identifying the vendor responsible for each outage event.',
    `affected_feeder_code` STRING COMMENT 'Code identifying the distribution feeder (primary circuit) affected by the outage. Critical for outage location, crew dispatch, and reliability metric calculation by feeder.',
    `affected_substation_code` STRING COMMENT 'Code identifying the substation serving the affected network segment. Used for outage aggregation, crew routing, and asset management coordination.',
    `alarm_event_id` STRING COMMENT 'Identifier of the SCADA alarm that triggered or correlated with this outage event. Links to PI Historian and EMS for real-time operational data and root cause analysis. Also known as SCADA alarm ID.',
    `confirmed_customers_affected` STRING COMMENT 'Final confirmed count of customer accounts that experienced a service interruption during this outage event. Used for official SAIDI, SAIFI, CAIDI, and MAIFI calculations and regulatory reporting.',
    `created_timestamp` TIMESTAMP COMMENT 'Date and time when this outage event record was first created in the data platform. Used for data lineage, audit trail, and change tracking.',
    `crew_arrival_timestamp` TIMESTAMP COMMENT 'Date and time when field crews arrived on-site at the outage location. Used to calculate travel time and time-to-repair metrics.',
    `crew_dispatch_timestamp` TIMESTAMP COMMENT 'Date and time when field crews were dispatched to investigate and restore the outage. Used to calculate response time metrics and crew utilization.',
    `critical_infrastructure_affected_flag` BOOLEAN COMMENT 'Boolean indicator whether the outage affected critical infrastructure customers (hospitals, emergency services, water treatment, communications). Triggers priority restoration and regulatory notification.',
    `customer_minutes_interrupted` BIGINT COMMENT 'Total customer-minutes of interruption, calculated as the sum of (customers affected × duration) for each restoration milestone. Primary input for SAIDI calculation. Also known as CMI.',
    `equipment_failed_type` STRING COMMENT 'Type of equipment that failed and caused the outage (e.g., transformer, recloser, fuse, conductor, insulator, switch). Links to asset management for failure analysis and replacement planning.',
    `estimated_customers_affected` STRING COMMENT 'Initial estimate of the number of customer accounts affected by the outage, typically calculated by the OMS based on network topology and meter connectivity. Updated as outage scope is refined.',
    `estimated_restoration_time` TIMESTAMP COMMENT 'The estimated date and time when service is expected to be fully restored. Communicated to customers and updated as restoration progresses. Also known as ETR.',
    `fault_isolation_timestamp` TIMESTAMP COMMENT 'Date and time when the fault was successfully isolated from the rest of the network through switching operations. Enables partial restoration to unaffected customers.',
    `first_restoration_timestamp` TIMESTAMP COMMENT 'Date and time when service was first restored to any subset of affected customers, typically through switching operations or temporary measures.',
    `major_event_day_flag` BOOLEAN COMMENT 'Boolean indicator whether this outage occurred during a Major Event Day as defined by IEEE 1366 2.5 beta method. MED outages are typically excluded from reliability metric calculations. Also known as MED flag.',
    `oms_external_reference` STRING COMMENT 'External identifier from the source OMS system (GE PowerOn). Used for cross-system reconciliation and data lineage tracking. Also known as OMS external ID.',
    `oms_source_system` STRING COMMENT 'Name of the source OMS system that created this outage record (e.g., GE PowerOn, Oracle OMS). Used for data lineage and multi-system integration scenarios. Also known as OMS source system.',
    `outage_cause_code` STRING COMMENT 'Standardized IEEE 1366 cause code identifying the root cause of the outage (e.g., equipment failure, tree contact, animal contact, weather, vehicle accident, planned maintenance).',
    `outage_cause_description` STRING COMMENT 'Detailed narrative description of the outage cause, including specific circumstances, equipment involved, and contributing factors. Captured by field crews during restoration.',
    `outage_duration_minutes` STRING COMMENT 'Total duration of the outage event in minutes, calculated as the difference between outage start and end timestamps. Used for SAIDI and CAIDI reliability metric calculations.',
    `outage_end_timestamp` TIMESTAMP COMMENT 'The date and time when service was fully restored to all affected customers. Used to calculate total outage duration for reliability metrics and regulatory reporting.',
    `outage_location_address` STRING COMMENT 'Street address or nearest intersection to the outage location. Used for crew dispatch, customer communication, and regulatory reporting. Organizational contact data classified as confidential.',
    `outage_location_latitude` DECIMAL(18,2) COMMENT 'Geographic latitude coordinate of the outage location in decimal degrees. Used for crew routing, GIS mapping, and spatial analysis of outage patterns.',
    `outage_location_longitude` DECIMAL(18,2) COMMENT 'Geographic longitude coordinate of the outage location in decimal degrees. Used for crew routing, GIS mapping, and spatial analysis of outage patterns.',
    `outage_number` STRING COMMENT 'Business identifier for the outage event, typically generated by the OMS (GE PowerOn). Used for external communication, crew dispatch, and regulatory reporting.',
    `outage_start_timestamp` TIMESTAMP COMMENT 'The date and time when the outage event was first detected or reported. This is the official start time used for SAIDI, SAIFI, CAIDI, and MAIFI reliability metric calculations.',
    `outage_status` STRING COMMENT 'Current lifecycle status of the outage event. Tracks progression from initial detection through crew dispatch, fault isolation, restoration activities, and final closure. [ENUM-REF-CANDIDATE: detected|confirmed|dispatched|isolated|restoring|restored|closed — 7 candidates stripped; promote to reference product]',
    `outage_type` STRING COMMENT 'Classification of the outage event. Planned outages are scheduled maintenance; unplanned are unexpected interruptions; momentary are brief interruptions typically under 5 minutes.. Valid values are `planned|unplanned|momentary`',
    `peak_customers_out` STRING COMMENT 'Maximum number of customers simultaneously without service at any point during the outage event. Used for storm impact assessment and resource planning.',
    `regulatory_notification_required_flag` BOOLEAN COMMENT 'Boolean indicator whether this outage event requires notification to regulatory authorities (state PUC, FERC, DOE) based on customer count, duration, or critical infrastructure impact thresholds.',
    `regulatory_notification_timestamp` TIMESTAMP COMMENT 'Date and time when regulatory notification was submitted to the appropriate authority (state PUC, FERC, DOE). Required for compliance audit trail.',
    `restoration_method` STRING COMMENT 'Primary method used to restore service (e.g., switching, repair, replacement, temporary bypass, mobile substation). Used for restoration strategy analysis and resource planning.',
    `storm_name` STRING COMMENT 'Name or identifier of the storm event if this outage was part of a named storm (e.g., Hurricane Ida, Winter Storm Uri). Used for storm impact analysis and FEMA reporting.',
    `updated_timestamp` TIMESTAMP COMMENT 'Date and time when this outage event record was last modified in the data platform. Used for data lineage, audit trail, and change tracking.',
    `weather_condition` STRING COMMENT 'Weather conditions at the time of the outage event (e.g., clear, rain, snow, ice, wind, lightning, hurricane, tornado). Used for cause analysis and major event day (MED) classification.',
    CONSTRAINT pk_gridops_outage_event PRIMARY KEY(`gridops_outage_event_id`)
) COMMENT 'Master record for each grid outage event managed through the OMS (GE PowerOn), encompassing the full outage lifecycle from detection through restoration. Header captures outage type (planned/unplanned/momentary), affected network segment, cause code (IEEE 1366), estimated and confirmed customers affected, start timestamp, ETR (estimated time of restoration), and regulatory notification status. Includes a chronological restoration log tracking each milestone (crew dispatch, fault isolation, switching action, partial restoration, full restoration) with timestamps, restored customer counts, restoration method, and responsible crew. Serves as the SSOT for outage lifecycle management, SAIDI/SAIFI/CAIDI/MAIFI calculation, regulatory reporting (state PUC, DOE OE-417), and post-storm analysis.';

CREATE OR REPLACE TABLE `power_and_utilities_v2`.`gridops`.`outage_restoration_log` (
    `outage_restoration_log_id` BIGINT COMMENT 'Unique identifier for each restoration activity log entry. Primary key for the outage restoration log.',
    `crew_id` BIGINT COMMENT 'Identifier of the field crew responsible for this restoration activity. Links to workforce management system for crew performance analysis.',
    `distribution_substation_id` BIGINT COMMENT 'Identifier of the substation associated with this restoration activity. Supports substation-level restoration performance analysis.',
    `feeder_id` BIGINT COMMENT 'Identifier of the distribution feeder affected by this restoration activity. Links to distribution network model for circuit-level analysis.',
    `gridops_outage_event_id` BIGINT COMMENT 'Reference to the parent outage event that this restoration activity belongs to. Links restoration activities to the originating outage.',
    `automated_restoration_flag` BOOLEAN COMMENT 'Indicates whether this restoration was performed automatically by distribution automation systems. True if automated, false if manual crew intervention was required.',
    `cause_code` STRING COMMENT 'Standardized code identifying the root cause of the outage being restored. Links to cause code reference table for regulatory reporting.',
    `crew_type` STRING COMMENT 'Classification of crew performing the restoration work. Distinguishes between internal utility crews, contractors, mutual aid crews, and emergency response teams.. Valid values are `internal|contractor|mutual_aid|emergency_response`',
    `customer_callback_required_flag` BOOLEAN COMMENT 'Indicates whether customer callbacks are required after this restoration milestone. True if customers need to be contacted to verify service restoration.',
    `customers_restored_count` STRING COMMENT 'Number of customers whose service was restored at this milestone. Used for calculating cumulative restoration progress and regulatory reporting.',
    `data_source_system` STRING COMMENT 'Name of the source system that provided this restoration log data (e.g., OMS, DMS, SCADA, field mobile application). Supports data lineage and integration troubleshooting.',
    `device_location` STRING COMMENT 'Physical location or address of the device operated during restoration. Enables geographic analysis of restoration activities.',
    `device_operated` STRING COMMENT 'Identifier or name of the electrical device operated during this restoration milestone (e.g., circuit breaker, recloser, switch). Supports asset performance analysis.',
    `dms_event_code` STRING COMMENT 'Reference identifier from the Distribution Management System for this restoration event. Links to DMS for advanced distribution automation analysis.',
    `equipment_failure_flag` BOOLEAN COMMENT 'Indicates whether equipment failure was identified during this restoration activity. True if equipment failure was discovered, false otherwise.',
    `estimated_restoration_time` TIMESTAMP COMMENT 'Estimated time when restoration was expected to be completed at the time this milestone was logged. Used for comparing actual vs. estimated restoration performance.',
    `load_restored_mw` DECIMAL(18,2) COMMENT 'Amount of electrical load in megawatts restored at this milestone. Supports grid operations analysis and capacity restoration tracking.',
    `mutual_aid_request_flag` BOOLEAN COMMENT 'Indicates whether mutual aid resources were requested or utilized for this restoration activity. True if mutual aid was involved, false otherwise.',
    `oms_ticket_number` STRING COMMENT 'Reference number of the OMS trouble ticket associated with this restoration activity. Links to outage management system for end-to-end outage tracking.',
    `priority_level` STRING COMMENT 'Priority classification assigned to this restoration activity. Critical facilities (hospitals, emergency services) receive higher priority.. Valid values are `critical|high|medium|low`',
    `record_created_timestamp` TIMESTAMP COMMENT 'Timestamp when this restoration log record was first created in the system. Supports data lineage and audit trail requirements.',
    `record_updated_timestamp` TIMESTAMP COMMENT 'Timestamp when this restoration log record was last modified. Tracks data currency and supports audit trail requirements.',
    `restoration_cost_estimate` DECIMAL(18,2) COMMENT 'Estimated cost in USD associated with this restoration activity. Includes labor, materials, and equipment costs for financial tracking and storm cost analysis.',
    `restoration_duration_minutes` STRING COMMENT 'Duration in minutes from outage start to this restoration milestone. Used for calculating CAIDI (Customer Average Interruption Duration Index) and other reliability metrics.',
    `restoration_method` STRING COMMENT 'Method used to restore service at this milestone. Indicates whether restoration was via primary feed, alternate feed, temporary generation, or switching operations.. Valid values are `primary_feed|alternate_feed|temporary_generation|manual_switching|automated_switching|sectionalizing`',
    `restoration_milestone_type` STRING COMMENT 'Classification of the restoration activity milestone. Defines the type of restoration event being logged (crew dispatch, fault isolation, switching, partial or full restoration).. Valid values are `crew_dispatched|crew_arrived|fault_isolated|switching_action|partial_restoration|full_restoration`',
    `restoration_notes` STRING COMMENT 'Free-text notes and observations recorded by field crews during restoration activity. Captures operational details, challenges encountered, and lessons learned.',
    `restoration_sequence_number` STRING COMMENT 'Sequential ordering of restoration activities within a single outage event. Enables chronological reconstruction of restoration workflow.',
    `restoration_status` STRING COMMENT 'Current status of this restoration activity. Tracks whether the restoration milestone is in progress, completed, failed, or pending verification.. Valid values are `in_progress|completed|failed|pending_verification`',
    `restoration_timestamp` TIMESTAMP COMMENT 'Date and time when this specific restoration milestone occurred. Critical for calculating restoration duration metrics and CAIDI (Customer Average Interruption Duration Index).',
    `safety_incident_flag` BOOLEAN COMMENT 'Indicates whether a safety incident occurred during this restoration activity. True if any safety event was reported, false otherwise.',
    `scada_confirmation_flag` BOOLEAN COMMENT 'Indicates whether the restoration activity was confirmed via SCADA system. True if SCADA telemetry verified the restoration, false if manual confirmation only.',
    `switching_order_number` STRING COMMENT 'Reference number of the switching order executed during this restoration activity. Links to switching order management system for operational traceability.',
    `vegetation_related_flag` BOOLEAN COMMENT 'Indicates whether vegetation contact or interference was involved in the outage being restored. True if vegetation-related, false otherwise.',
    `weather_condition` STRING COMMENT 'Weather conditions present during this restoration activity. Supports correlation analysis between weather and restoration performance.',
    CONSTRAINT pk_outage_restoration_log PRIMARY KEY(`outage_restoration_log_id`)
) COMMENT 'Detailed chronological log of restoration activities for each outage event, capturing each restoration milestone (crew dispatch, fault isolation, switching action, partial restoration, full restoration). Records timestamp, restored customer count, restoration method, and responsible crew. Supports CAIDI calculation, regulatory reporting, and post-storm analysis.';

CREATE OR REPLACE TABLE `power_and_utilities_v2`.`gridops`.`reliability_event` (
    `reliability_event_id` BIGINT COMMENT 'Unique identifier for the reliability event record. Primary key for the reliability event entity.',
    `balancing_area_id` BIGINT COMMENT 'Foreign key linking to gridops.balancing_area. Business justification: Reliability events are associated with a balancing area; FK replaces free‑text field.',
    `gridops_outage_event_id` BIGINT COMMENT 'Identifier linking this reliability event to associated customer outage records in the Outage Management System. Used for cross-system correlation and customer impact analysis.',
    `incident_id` BIGINT COMMENT 'Foreign key linking to safety.incident. Business justification: Major reliability events trigger safety incident investigations for regulatory reporting and corrective action.',
    `oms_outage_gridops_outage_event_id` BIGINT COMMENT 'Identifier linking this reliability event to associated customer outage records in the Outage Management System. Used for cross-system correlation and customer impact analysis.',
    `affected_facilities` STRING COMMENT 'List or description of transmission lines, substations, generation units, or other Bulk Electric System (BES) facilities impacted by the reliability event. Includes facility identifiers and equipment names.',
    `analysis_completion_date` DATE COMMENT 'Date when the post-event analysis or root cause investigation was completed. Null if analysis is not yet complete or not required.',
    `caidi_impact_minutes` DECIMAL(18,2) COMMENT 'Contribution of this reliability event to the utilitys CAIDI metric, measured in average minutes per customer interruption. Used for reliability performance tracking and regulatory reporting.',
    `cip_incident_flag` BOOLEAN COMMENT 'Indicates whether this reliability event is also classified as a NERC CIP cyber security or physical security incident requiring separate CIP incident reporting. True if CIP incident reporting is required.',
    `contributing_factors` STRING COMMENT 'Additional factors that contributed to the severity or propagation of the reliability event. May include cascading failures, inadequate operating reserves, communication failures, or procedural gaps.',
    `control_room_location` STRING COMMENT 'Physical location or identifier of the control room where the reliability event was managed. Used for tracking operational responsibility and shift coordination.',
    `corrective_actions_taken` STRING COMMENT 'Description of immediate corrective actions taken by operators to mitigate or resolve the reliability event. Includes switching operations, load shedding, generation dispatch adjustments, and emergency procedures executed.',
    `customers_affected` STRING COMMENT 'Total number of customer accounts that experienced service interruption as a result of the reliability event. Used for outage impact assessment and regulatory reporting.',
    `detection_timestamp` TIMESTAMP COMMENT 'Date and time when the reliability event was first detected by control room operators, SCADA alarms, or automated monitoring systems. May differ from event start if detection was delayed.',
    `ems_case_code` STRING COMMENT 'Identifier for the EMS state estimator case or snapshot associated with the reliability event. Links to power flow analysis and system state data at the time of the event.',
    `estimated_restoration_timestamp` TIMESTAMP COMMENT 'Estimated date and time when full service restoration is expected to be completed. Updated as restoration work progresses. Null if event is already resolved.',
    `event_classification` STRING COMMENT 'Primary classification of the reliability event per NERC EOP/TOP standards and internal utility categorization. Determines regulatory reporting obligations and escalation procedures.. Valid values are `nerc_reportable|state_reportable|internal_disturbance|contingency|n_minus_1_violation|bes_incident`',
    `event_end_timestamp` TIMESTAMP COMMENT 'Precise date and time when the reliability event was fully resolved and normal operations restored. Null if event is still ongoing. Used to calculate event duration.',
    `event_number` STRING COMMENT 'Externally-known unique identifier for the reliability event, used in regulatory reporting and inter-utility communications. Typically follows utility-specific or NERC-prescribed numbering conventions.. Valid values are `^[A-Z0-9]{8,20}$`',
    `event_start_timestamp` TIMESTAMP COMMENT 'Precise date and time when the reliability event was first detected or initiated. Represents the beginning of the disturbance or incident. Critical for NERC timeline reporting.',
    `event_status` STRING COMMENT 'Current lifecycle status of the reliability event. Tracks progression from initial detection through investigation, containment, resolution, and final closure.. Valid values are `open|investigating|contained|resolved|closed|archived`',
    `event_type` STRING COMMENT 'Detailed type of reliability event such as transmission outage, generation loss, voltage deviation, frequency excursion, load shed, protective relay operation, or equipment failure. Provides granular categorization beyond classification.',
    `frequency_deviation_hz` DECIMAL(18,2) COMMENT 'Maximum frequency deviation from nominal 60 Hz (or 50 Hz) observed during the reliability event. Measured in Hertz. Critical for assessing system stability and NERC BAL standard compliance.',
    `initiating_cause` STRING COMMENT 'Root cause or triggering event that initiated the reliability event. Examples include equipment failure, weather event, human error, cyber incident, protective relay misoperation, or external disturbance.',
    `lessons_learned` STRING COMMENT 'Summary of key lessons learned from the reliability event. Includes insights on operational procedures, equipment performance, communication effectiveness, and recommendations for improvement.',
    `mw_generation_lost` DECIMAL(18,2) COMMENT 'Total amount of generation capacity lost during the reliability event, measured in megawatts. Includes forced outages and emergency shutdowns of generation units.',
    `mw_load_lost` DECIMAL(18,2) COMMENT 'Total amount of customer load lost during the reliability event, measured in megawatts. Key metric for assessing event severity and NERC reporting thresholds.',
    `nerc_oe417_report_number` STRING COMMENT 'Unique identifier for the NERC OE-417 Electric Emergency Incident and Disturbance Report filed for this reliability event. Links to official regulatory submission.',
    `nerc_reportable_flag` BOOLEAN COMMENT 'Indicates whether this event meets NERC criteria for mandatory reporting under EOP-004 or other NERC standards. True if event must be reported to NERC.',
    `notification_timestamp` TIMESTAMP COMMENT 'Date and time when the reliability event was formally notified to NERC, RTO/ISO, state PUC, or other regulatory authorities. Critical for compliance with reporting deadlines.',
    `operator_entry_type` STRING COMMENT 'Classification of the operator log entry by type. Distinguishes between event-related actions, routine observations, shift logs, standing orders, and equipment status notes. [ENUM-REF-CANDIDATE: event_action|observation|communication|shift_handoff|alarm_ack|switching_order|standing_order|equipment_status — 8 candidates stripped; promote to reference product]',
    `operator_log_entry` STRING COMMENT 'Chronological free-text narrative of operator actions, observations, and communications during the reliability event. Includes shift handoff notes, alarm acknowledgments, switching orders executed, and inter-utility communications. Forms the official auditable operational record.',
    `operator_name` STRING COMMENT 'Name of the control room operator who logged the entry or took action during the reliability event. Used for operational accountability and training purposes.',
    `post_event_analysis_required_flag` BOOLEAN COMMENT 'Indicates whether a formal post-event analysis or root cause investigation is required for this reliability event. True for significant events requiring detailed technical review.',
    `preventive_actions_recommended` STRING COMMENT 'Recommended preventive actions to avoid recurrence of similar reliability events. May include equipment upgrades, procedure changes, training enhancements, or system reinforcements.',
    `record_created_timestamp` TIMESTAMP COMMENT 'Date and time when this reliability event record was first created in the system. Used for audit trail and data lineage tracking.',
    `record_updated_timestamp` TIMESTAMP COMMENT 'Date and time when this reliability event record was last modified. Updated whenever any field in the record changes. Used for audit trail and change tracking.',
    `restoration_priority` STRING COMMENT 'Priority level assigned for service restoration efforts. Critical priority for hospitals, emergency services, and critical infrastructure; high for large customer groups; medium and low for routine restoration.. Valid values are `critical|high|medium|low`',
    `rto_iso_region` STRING COMMENT 'RTO or ISO region where the reliability event occurred. Examples include PJM, MISO, CAISO, ERCOT, SPP, NYISO, ISO-NE. Used for regional coordination and reporting.',
    `saidi_impact_minutes` DECIMAL(18,2) COMMENT 'Contribution of this reliability event to the utilitys SAIDI metric, measured in customer-minutes of interruption. Used for reliability performance tracking and regulatory reporting.',
    `saifi_impact_count` DECIMAL(18,2) COMMENT 'Contribution of this reliability event to the utilitys SAIFI metric, measured as interruption frequency per customer. Used for reliability performance tracking and regulatory reporting.',
    `scada_alarm_count` STRING COMMENT 'Total number of SCADA alarms triggered during the reliability event. Used to assess event complexity and operator workload during the incident.',
    `shift_supervisor_name` STRING COMMENT 'Name of the shift supervisor on duty during the reliability event. Used for operational accountability and post-event review coordination.',
    `state_reportable_flag` BOOLEAN COMMENT 'Indicates whether this event must be reported to state Public Utility Commission per state-specific disturbance reporting requirements. True if state reporting is required.',
    `voltage_deviation_kv` DECIMAL(18,2) COMMENT 'Maximum voltage deviation from normal operating range observed during the reliability event. Measured in kilovolts. Used to assess voltage stability and equipment stress.',
    `weather_conditions` STRING COMMENT 'Description of weather conditions at the time of the reliability event. Includes temperature, wind speed, precipitation, lightning activity, and other relevant meteorological data.',
    `weather_related_flag` BOOLEAN COMMENT 'Indicates whether the reliability event was caused or significantly influenced by weather conditions such as storms, lightning, ice, wind, or extreme temperatures. True if weather was a factor.',
    CONSTRAINT pk_reliability_event PRIMARY KEY(`reliability_event_id`)
) COMMENT 'Records NERC-reportable and internally tracked reliability events including disturbances, contingencies, N-1 violations, BES incidents, and all associated operator log entries and control room communications. Each event captures classification per NERC EOP/TOP standards, affected facilities, initiating cause, system impact (MW lost, customers affected), regulatory reporting obligation, and timeline. Includes chronological operator actions, observations, shift handoff notes, alarm acknowledgments, inter-utility communications, and free-text narratives forming the complete operational record. Also serves as the repository for routine operator log entries (shift logs, standing orders, equipment status notes) classified by entry type. Feeds NERC OE-417, state PUC disturbance reporting, NERC CIP compliance evidence, and serves as the official auditable operational record for all control room activities.';

CREATE OR REPLACE TABLE `power_and_utilities_v2`.`gridops`.`dr_dispatch_event` (
    `dr_dispatch_event_id` BIGINT COMMENT 'Unique identifier for the demand response dispatch event. Primary key.',
    `balancing_area_id` BIGINT COMMENT 'Foreign key linking to gridops.balancing_area. Business justification: DR dispatch events are executed within a balancing area; FK adds referential integrity.',
    `compliance_obligation_id` BIGINT COMMENT 'Foreign key linking to regulatory.compliance_obligation. Business justification: Demand‑Response dispatches must satisfy a documented compliance obligation; the FK ties each dispatch to its obligation record.',
    `customer_account_id` BIGINT COMMENT 'Foreign key linking to customer.customer_account. Business justification: DR Dispatch Report requires linking each dispatch to the customer account enrolled in the program for settlement and regulatory compliance.',
    `der_program_id` BIGINT COMMENT 'Reference to the DR program under which this dispatch event was issued.',
    `dr_enrollment_id` BIGINT COMMENT 'Foreign key linking to customer.dr_enrollment. Business justification: Compliance audit tracks which specific DR enrollment was dispatched; the DR dispatch event must reference the enrollment record.',
    `employee_id` BIGINT COMMENT 'The identifier of the grid operations control room operator who issued the DR dispatch event.. Valid values are `^OP[0-9]{6}$`',
    `gridops_outage_event_id` BIGINT COMMENT 'Reference to the outage management system (OMS) event that triggered this DR dispatch, if the dispatch was issued in response to a grid outage or contingency.',
    `person_id` BIGINT COMMENT 'The identifier of the grid operations control room operator who issued the DR dispatch event.',
    `product_program_id` BIGINT COMMENT 'Foreign key linking to product.product_program. Business justification: DR dispatch events are executed under a specific demand‑response program defined in product_program; required for program performance tracking.',
    `wbs_element_id` BIGINT COMMENT 'Foreign key linking to finance.wbs_element. Business justification: Demand‑Response dispatches are tracked as projects; linking to WBS enables budgeting and cost tracking.',
    `actual_mw_reduction` DECIMAL(18,2) COMMENT 'The actual measured load reduction in megawatts (MW) achieved across all participating resources, aggregated from interval meter data.',
    `ambient_temperature_f` DECIMAL(18,2) COMMENT 'The ambient outdoor temperature in degrees Fahrenheit at the time of dispatch, used for weather normalization and performance analysis.',
    `baseline_methodology` STRING COMMENT 'The baseline calculation methodology used to determine pre-event load and measure actual reduction: high 10 of 10 (highest 10 of last 10 similar days), mid 8 of 10, high 5 of 10, customer baseline (negotiated), or meter before/after (direct measurement).. Valid values are `high_10_of_10|mid_8_of_10|high_5_of_10|customer_baseline|meter_before_after`',
    `compliance_status` STRING COMMENT 'Overall program compliance status for this dispatch event: compliant (met all requirements), non-compliant (failed to meet targets), partial (some resources complied), under review (pending settlement), exempt (test or waived event).. Valid values are `compliant|non_compliant|partial|under_review|exempt`',
    `created_timestamp` TIMESTAMP COMMENT 'The timestamp when this DR dispatch event record was first created in the system.',
    `derms_integration_flag` BOOLEAN COMMENT 'Boolean flag indicating whether this dispatch event was coordinated through the DERMS platform for DER-based DR resources.',
    `dispatch_authorization_code` STRING COMMENT 'The authorization code or approval reference for the dispatch event, required for emergency and economic dispatches per operating procedures.. Valid values are `^AUTH-[A-Z0-9]{8}$`',
    `dispatch_duration_minutes` STRING COMMENT 'The total duration of the DR dispatch event in minutes, calculated from start to end timestamp.',
    `dispatch_end_timestamp` TIMESTAMP COMMENT 'The scheduled end date and time for the DR curtailment event.',
    `dispatch_issued_timestamp` TIMESTAMP COMMENT 'The date and time when the DR dispatch event was issued by grid operations to participating resources.',
    `dispatch_notes` STRING COMMENT 'Free-text operational notes and comments recorded by the dispatch operator regarding event circumstances, special conditions, or post-event observations.',
    `dispatch_number` STRING COMMENT 'Business identifier for the DR dispatch event, formatted as DR-YYYYMMDD-NNNN for external reference and operational tracking.. Valid values are `^DR-[0-9]{8}-[0-9]{4}$`',
    `dispatch_start_timestamp` TIMESTAMP COMMENT 'The scheduled start date and time for the DR curtailment event.',
    `dispatch_status` STRING COMMENT 'Current lifecycle status of the DR dispatch event: pending (notification sent, not yet active), active (curtailment in progress), completed (event concluded), cancelled (event aborted), failed (dispatch unsuccessful).. Valid values are `pending|active|completed|cancelled|failed`',
    `dispatch_trigger_type` STRING COMMENT 'The operational reason for issuing the DR dispatch: emergency (grid emergency), economic (price-driven), capacity (resource adequacy), test (program validation), scheduled (planned event), or reliability (NERC compliance).. Valid values are `emergency|economic|capacity|test|scheduled|reliability`',
    `ferc_2222_reportable_flag` BOOLEAN COMMENT 'Boolean flag indicating whether this dispatch event involves aggregated DER participation and is reportable under FERC Order 2222 requirements.',
    `frequency_deviation_hz` DECIMAL(18,2) COMMENT 'The grid frequency deviation in hertz (Hz) from nominal 60 Hz at the time of dispatch, if the dispatch was triggered by frequency regulation needs.',
    `grid_emergency_level` STRING COMMENT 'The grid emergency alert level at the time of dispatch issuance, ranging from normal to emergency levels 1-3 per NERC EEA protocols.. Valid values are `normal|advisory|warning|emergency_1|emergency_2|emergency_3`',
    `iso_rto_market` STRING COMMENT 'The ISO or RTO market jurisdiction under which this DR dispatch was executed. [ENUM-REF-CANDIDATE: PJM|CAISO|ERCOT|MISO|NYISO|ISO-NE|SPP|non-ISO — 8 candidates stripped; promote to reference product]',
    `last_modified_timestamp` TIMESTAMP COMMENT 'The timestamp when this DR dispatch event record was last updated, reflecting status changes, performance data updates, or settlement finalization.',
    `lmp_trigger_price` DECIMAL(18,2) COMMENT 'The locational marginal price (LMP) in dollars per MWh that triggered an economic DR dispatch, if applicable.',
    `notification_lead_time_minutes` STRING COMMENT 'The advance notice time in minutes between dispatch issuance and dispatch start, as required by program rules.',
    `notification_method` STRING COMMENT 'The primary method used to notify DR participants of the dispatch event: automated signal (OpenADR, API), phone, email, SMS, web portal, or SCADA command.. Valid values are `automated_signal|phone|email|sms|web_portal|scada`',
    `performance_percentage` DECIMAL(18,2) COMMENT 'The overall performance of the dispatch event expressed as a percentage of actual MW reduction divided by target MW reduction.',
    `scada_snapshot_timestamp` TIMESTAMP COMMENT 'The timestamp of the SCADA system snapshot captured at dispatch issuance, used for grid state verification and post-event analysis.',
    `settlement_amount` DECIMAL(18,2) COMMENT 'The total financial settlement amount in USD to be paid to all participating DR resources for this dispatch event, based on performance and program rates.',
    `settlement_ready_flag` BOOLEAN COMMENT 'Boolean flag indicating whether all performance data has been validated and the event is ready for financial settlement and capacity payment processing.',
    `target_mw_reduction` DECIMAL(18,2) COMMENT 'The total target load reduction in megawatts (MW) requested from all participating DR resources for this dispatch event.',
    `total_resources_dispatched` STRING COMMENT 'The total count of individual DR resources (customers, aggregators, DERs) that were dispatched as part of this event.',
    `total_resources_responded` STRING COMMENT 'The count of dispatched resources that successfully responded and achieved measurable load reduction during the event.',
    `voltage_deviation_kv` DECIMAL(18,2) COMMENT 'The voltage deviation in kilovolts (kV) from nominal levels at critical substations, if the dispatch was triggered by voltage control needs.',
    `weather_adjusted_flag` BOOLEAN COMMENT 'Boolean flag indicating whether the baseline and performance calculations were adjusted for weather conditions (temperature, humidity) per program rules.',
    CONSTRAINT pk_dr_dispatch_event PRIMARY KEY(`dr_dispatch_event_id`)
) COMMENT 'Records each demand response (DR) dispatch event issued by grid operations to enrolled DR resources and aggregators, with full per-resource performance tracking. Header captures dispatch trigger (emergency, economic, capacity, test), target MW reduction, dispatch window, notification method, and overall program compliance status. Detail records capture each participating resources identifier, resource type, nominated MW reduction, actual metered MW reduction (from interval meter data), response time, ramp compliance, performance score, and settlement-ready compliance flag. Integrates with DERMS for DER-based DR and with the product domain for DR program definitions. Supports DR capacity payment settlement, program compliance verification, FERC Order 2222 reporting, and resource performance trending.';

CREATE OR REPLACE TABLE `power_and_utilities_v2`.`gridops`.`dr_resource_response` (
    `dr_resource_response_id` BIGINT COMMENT 'Unique identifier for the demand response resource response record. Primary key.',
    `aggregator_id` BIGINT COMMENT 'Reference to the aggregator entity if this resource is part of an aggregated DR portfolio.',
    `dr_dispatch_event_id` BIGINT COMMENT 'Reference to the parent DR dispatch event that triggered this resource response.',
    `resource_id` BIGINT COMMENT 'Reference to the specific DR resource or aggregator that responded to the dispatch event.',
    `product_program_id` BIGINT COMMENT 'Reference to the specific DR program under which this response was dispatched.',
    `actual_duration_minutes` STRING COMMENT 'The actual duration in minutes that the resource sustained the load reduction.',
    `actual_load_mw` DECIMAL(18,2) COMMENT 'The actual metered load in megawatts during the DR event period, measured from AMI or SCADA systems.',
    `actual_reduction_mw` DECIMAL(18,2) COMMENT 'The actual measured load reduction in megawatts achieved by the resource, calculated as baseline minus actual load.',
    `balancing_authority_area` STRING COMMENT 'The balancing authority area code where this DR resource is located and responded.',
    `baseline_calculation_method` STRING COMMENT 'The methodology used to calculate the baseline load for this resource (e.g., 10-of-10, 5-of-10, regression-based).',
    `baseline_load_mw` DECIMAL(18,2) COMMENT 'The calculated baseline load in megawatts representing what the resource would have consumed without the DR event, used for settlement calculations.',
    `compliance_flag` BOOLEAN COMMENT 'Boolean indicator of whether the resource met the minimum performance requirements for the DR event (True = compliant, False = non-compliant).',
    `compliance_percentage` DECIMAL(18,2) COMMENT 'The percentage of nominated reduction actually delivered, calculated as (actual reduction / nominated reduction) * 100.',
    `created_timestamp` TIMESTAMP COMMENT 'The date and time when this resource response record was first created in the system.',
    `dispatch_instruction_type` STRING COMMENT 'Classification of the dispatch instruction that triggered this response.. Valid values are `manual|automatic|test|emergency`',
    `dispatch_timestamp` TIMESTAMP COMMENT 'The date and time when the DR dispatch signal was issued to the resource.',
    `event_duration_minutes` STRING COMMENT 'The total duration in minutes that the resource was expected to maintain the load reduction.',
    `meter_data_source` STRING COMMENT 'The source system or method used to capture the actual load measurements for this response.. Valid values are `ami|scada|manual|estimated|aggregated`',
    `nominated_reduction_mw` DECIMAL(18,2) COMMENT 'The committed or nominated load reduction in megawatts that the resource agreed to provide for this dispatch event.',
    `non_compliance_reason` STRING COMMENT 'Explanation or code indicating why the resource failed to meet compliance requirements, if applicable.',
    `notes` STRING COMMENT 'Free-text field for operational notes, exceptions, or additional context regarding this resource response.',
    `penalty_amount_usd` DECIMAL(18,2) COMMENT 'Financial penalty assessed against the resource for non-compliance or under-performance, if applicable.',
    `performance_score` DECIMAL(18,2) COMMENT 'Calculated performance score for the resource response, incorporating reduction accuracy, response time, and sustained performance. Used for resource ranking and future dispatch prioritization.',
    `rebound_effect_mw` DECIMAL(18,2) COMMENT 'The measured load increase in megawatts immediately following the DR event, representing the rebound or snapback effect.',
    `reduction_variance_mw` DECIMAL(18,2) COMMENT 'The difference between nominated and actual reduction in megawatts, used for compliance and performance assessment.',
    `resource_name` STRING COMMENT 'Human-readable name or identifier of the DR resource or aggregator for operational reference.',
    `resource_type` STRING COMMENT 'Classification of the DR resource type participating in the event.. Valid values are `aggregator|direct_load|behind_the_meter_generation|battery_storage|controllable_load|interruptible_load`',
    `response_end_timestamp` TIMESTAMP COMMENT 'The actual date and time when the resource completed its response to the dispatch event.',
    `response_start_timestamp` TIMESTAMP COMMENT 'The actual date and time when the resource began responding to the dispatch signal.',
    `response_time_minutes` DECIMAL(18,2) COMMENT 'The elapsed time in minutes from dispatch signal to the start of measurable load reduction, indicating resource responsiveness.',
    `settlement_amount_usd` DECIMAL(18,2) COMMENT 'The calculated payment amount in US dollars owed to the resource for its DR performance in this event, based on contracted rates and actual reduction.',
    `settlement_status` STRING COMMENT 'Current status of the financial settlement process for this resource response.. Valid values are `pending|calculated|approved|paid|disputed|adjusted`',
    `telemetry_quality_flag` STRING COMMENT 'Data quality indicator for the metered telemetry used in this response measurement.. Valid values are `good|suspect|estimated|missing`',
    `updated_timestamp` TIMESTAMP COMMENT 'The date and time when this resource response record was last modified.',
    `verification_method` STRING COMMENT 'The method used to verify and validate the resource response performance.. Valid values are `meter_based|telemetry|manual_inspection|third_party`',
    `weather_adjustment_applied` BOOLEAN COMMENT 'Indicates whether a weather-based adjustment was applied to the baseline calculation to account for temperature or other weather impacts.',
    CONSTRAINT pk_dr_resource_response PRIMARY KEY(`dr_resource_response_id`)
) COMMENT 'Captures the measured performance response of each individual DR resource or aggregator to a specific DR dispatch event. Records resource identifier, nominated MW reduction, actual metered MW reduction, response time, compliance flag, and performance score. Used for DR settlement, program compliance verification, and resource performance tracking.';

CREATE OR REPLACE TABLE `power_and_utilities_v2`.`gridops`.`grid_contingency` (
    `grid_contingency_id` BIGINT COMMENT 'Unique identifier for the grid contingency scenario record. Primary key for the grid contingency data product.',
    `scada_system_id` BIGINT COMMENT 'Identifier of the SCADA system that provides real-time telemetry data for the elements involved in this contingency scenario.',
    `balancing_area_code` STRING COMMENT 'Code identifying the balancing area or balancing authority area where this contingency is defined and monitored, used for jurisdictional and operational coordination.',
    `cascading_outage_risk` STRING COMMENT 'Assessment of the risk that this contingency could trigger cascading outages affecting a wider area of the Bulk Electric System (BES), based on system topology, protection schemes, and historical events.. Valid values are `high|medium|low|none`',
    `contingency_category` STRING COMMENT 'NERC TPL planning category classification: P0 (no contingency/base case), P1 (single element), P2 (single element with stuck breaker), P3 (loss of generator), P4 (multiple elements), P5 (delayed fault clearing), P6 (system instability), P7 (common structure). [ENUM-REF-CANDIDATE: P0|P1|P2|P3|P4|P5|P6|P7 — 8 candidates stripped; promote to reference product]',
    `contingency_code` STRING COMMENT 'Unique business identifier or code used to reference this contingency in operational systems, study reports, and inter-system communication.',
    `contingency_name` STRING COMMENT 'Human-readable name or label assigned to this contingency scenario for operator identification and reference in Energy Management System (EMS) displays and reports.',
    `contingency_type` STRING COMMENT 'Classification of the contingency scenario based on the number and type of elements removed. N-1 represents single element outage, N-2 represents simultaneous loss of two elements, N-1-1 represents sequential loss of two elements. [ENUM-REF-CANDIDATE: N-1|N-2|N-1-1|generator_trip|line_trip|transformer_trip|bus_fault|multiple_element — 8 candidates stripped; promote to reference product]',
    `corrective_action_required` BOOLEAN COMMENT 'Boolean flag indicating whether corrective actions (generation redispatch, transmission switching, load shedding) are required to maintain system reliability if this contingency occurs.',
    `corrective_action_time_minutes` STRING COMMENT 'Maximum time in minutes allowed to implement corrective actions after this contingency occurs, based on thermal time constants, voltage decay rates, and operational procedures.',
    `corrective_action_type` STRING COMMENT 'Type of corrective action recommended or required to mitigate violations resulting from this contingency. May include multiple actions separated by semicolons (e.g., generation redispatch; transmission switching).',
    `created_timestamp` TIMESTAMP COMMENT 'Timestamp when this contingency record was first created in the system, supporting audit trail and data lineage requirements.',
    `dms_zone_code` STRING COMMENT 'Identifier linking this contingency to the DMS zone for transmission-distribution coordination and voltage control at the interface.',
    `effective_date` DATE COMMENT 'Date when this contingency definition became active and was included in security assessment processes.',
    `elements_removed_count` STRING COMMENT 'Count of transmission or generation elements (lines, transformers, generators, buses) that are removed or tripped in this contingency scenario definition.',
    `ems_system_code` STRING COMMENT 'Identifier of the EMS system instance where this contingency definition is maintained and where real-time security assessments are executed.',
    `expiration_date` DATE COMMENT 'Date when this contingency definition expires or is scheduled to be removed from active security assessment, typically due to system topology changes or element retirement. Null for indefinite contingencies.',
    `geographic_region` STRING COMMENT 'Geographic region or sub-region identifier for this contingency, used for regional reliability coordination and reporting.',
    `grid_contingency_status` STRING COMMENT 'Current lifecycle status of the contingency scenario in the real-time security assessment engine. Active contingencies are monitored continuously; inactive contingencies are excluded from real-time analysis.. Valid values are `active|inactive|suspended|archived|under_review`',
    `interconnection_type` STRING COMMENT 'North American power grid interconnection where this contingency is located: Eastern Interconnection, Western Interconnection, Texas Interconnection (ERCOT), or Quebec Interconnection.. Valid values are `eastern|western|texas|quebec`',
    `last_assessment_timestamp` TIMESTAMP COMMENT 'Timestamp of the most recent real-time or study-mode security assessment execution that evaluated this contingency scenario.',
    `last_violation_timestamp` TIMESTAMP COMMENT 'Timestamp when this contingency most recently resulted in a thermal, voltage, or stability violation during security assessment. Null if no violations have been detected.',
    `load_at_risk_mw` DECIMAL(18,2) COMMENT 'Total customer load in megawatts that could be interrupted or at risk of interruption if this contingency occurs and results in cascading outages or system instability.',
    `modified_timestamp` TIMESTAMP COMMENT 'Timestamp when this contingency record was most recently modified, supporting change tracking and audit requirements.',
    `monitoring_elements_count` STRING COMMENT 'Count of transmission elements (lines, transformers, interfaces) that are monitored for thermal overload, voltage violation, or stability issues when this contingency is applied in security assessment.',
    `nerc_cip_classification` STRING COMMENT 'NERC CIP impact rating classification for the elements involved in this contingency, indicating the cyber security and physical security requirements applicable to these assets.. Valid values are `high|medium|low|not_applicable`',
    `nerc_region` STRING COMMENT 'NERC regional entity with reliability oversight for this contingency scenario (e.g., WECC, MRO, NPCC, RF, SERC, Texas RE).',
    `oms_zone_code` STRING COMMENT 'Identifier linking this contingency to the OMS zone for coordination of planned and unplanned outage management and customer impact assessment.',
    `primary_element_name` STRING COMMENT 'Name or identifier of the primary transmission or generation element that is removed in this contingency scenario, as defined in the EMS network model.',
    `primary_element_type` STRING COMMENT 'Type classification of the primary element that is removed or fails in this contingency scenario.. Valid values are `transmission_line|transformer|generator|bus|shunt_device|hvdc_link`',
    `primary_element_voltage_kv` DECIMAL(18,2) COMMENT 'Nominal voltage level in kilovolts of the primary element involved in the contingency scenario.',
    `probability_class` STRING COMMENT 'Qualitative assessment of the likelihood of this contingency occurring based on historical outage data, equipment reliability, and operational experience.. Valid values are `high|medium|low|rare|extreme`',
    `probability_value` DECIMAL(18,2) COMMENT 'Quantitative probability estimate (0.0 to 1.0) representing the annual likelihood of this contingency scenario occurring, derived from historical reliability data and risk assessment models.',
    `real_time_assessment_enabled` BOOLEAN COMMENT 'Boolean flag indicating whether this contingency is included in the real-time security assessment (RTSA) engine that runs continuously in the EMS to monitor system security.',
    `rto_iso_code` STRING COMMENT 'Code identifying the RTO or ISO that has operational or planning jurisdiction over this contingency scenario (e.g., PJM, MISO, CAISO, ERCOT, SPP, NYISO, ISO-NE).',
    `secondary_element_name` STRING COMMENT 'Name or identifier of the secondary element removed in N-2 or N-1-1 contingency scenarios. Null for single-element contingencies.',
    `secondary_element_type` STRING COMMENT 'Type classification of the secondary element removed in N-2 or N-1-1 contingency scenarios. Set to none for single-element (N-1) contingencies. [ENUM-REF-CANDIDATE: transmission_line|transformer|generator|bus|shunt_device|hvdc_link|none — 7 candidates stripped; promote to reference product]',
    `severity_rating` STRING COMMENT 'Assessment of the potential impact severity if this contingency were to occur, considering load at risk, voltage collapse potential, cascading outage risk, and system stability margin degradation.. Valid values are `critical|high|medium|low|minimal`',
    `stability_margin_percent` DECIMAL(18,2) COMMENT 'Percentage margin between the current operating point and the stability limit (voltage collapse point or transient stability limit) under this contingency scenario. Higher values indicate greater system security.',
    `state_code` STRING COMMENT 'Two-letter state or province code where the primary contingency element is located, used for regulatory reporting and jurisdictional coordination.',
    `study_mode_enabled` BOOLEAN COMMENT 'Boolean flag indicating whether this contingency is included in offline study-mode security assessments used for day-ahead planning, seasonal studies, and long-term transmission planning.',
    `thermal_limit_mva` DECIMAL(18,2) COMMENT 'Maximum thermal capacity in MVA for the most critical monitored element under this contingency scenario, representing the binding constraint for system operations.',
    `voltage_limit_lower_pu` DECIMAL(18,2) COMMENT 'Minimum acceptable voltage in per-unit (pu) for monitored buses under this contingency scenario, typically 0.90 to 0.95 pu for transmission systems per NERC standards.',
    `voltage_limit_upper_pu` DECIMAL(18,2) COMMENT 'Maximum acceptable voltage in per-unit (pu) for monitored buses under this contingency scenario, typically 1.05 to 1.10 pu for transmission systems per NERC standards.',
    CONSTRAINT pk_grid_contingency PRIMARY KEY(`grid_contingency_id`)
) COMMENT 'Defines credible contingency scenarios (N-1, N-2, N-1-1) and stores all real-time and study-mode security assessment results performed by the EMS. Master contingency records specify contingency name, element(s) removed, contingency type, probability, monitoring elements, thermal and voltage limits, and active/inactive status in real-time security assessment. Assessment result records capture study timestamp, study type (real-time, day-ahead, planning), base case power flow results, number of violations found, worst-case contingency ranking, thermal overload details, voltage violation details, stability margin, and recommended corrective actions (redispatch, switching, load shed). Supports NERC TPL-001 through TPL-004, FAC-001/FAC-002 reliability standards, operator situational awareness, and real-time reliability compliance.';

CREATE OR REPLACE TABLE `power_and_utilities_v2`.`gridops`.`security_assessment` (
    `security_assessment_id` BIGINT COMMENT 'Unique identifier for the security assessment record. Primary key.',
    `balancing_area_id` BIGINT COMMENT 'Reference to the balancing area under which this security assessment was conducted.',
    `control_zone_id` BIGINT COMMENT 'Reference to the control zone where this security assessment was performed.',
    `grid_contingency_id` BIGINT COMMENT 'Identifier of the contingency that resulted in the most severe violations or highest risk during this assessment.',
    `assessment_duration_seconds` STRING COMMENT 'Total execution time of the security assessment in seconds, from initiation to completion.',
    `assessment_status` STRING COMMENT 'Current lifecycle status of the security assessment execution: completed (successfully finished), in-progress (currently running), failed (error during execution), aborted (manually stopped), or pending-review (awaiting operator validation).. Valid values are `completed|in-progress|failed|aborted|pending-review`',
    `assessment_timestamp` TIMESTAMP COMMENT 'The date and time when the security assessment was executed by the Energy Management System (EMS). This is the principal business event timestamp for the assessment.',
    `assessment_type` STRING COMMENT 'The type of security assessment performed: real-time (operational), study-mode (what-if analysis), post-contingency (after event), pre-contingency (preventive), seasonal (long-term planning), or planning (future scenario).. Valid values are `real-time|study-mode|post-contingency|pre-contingency|seasonal|planning`',
    `contingency_count` STRING COMMENT 'Total number of contingencies (N-1, N-2, etc.) analyzed during this security assessment.',
    `convergence_iterations` STRING COMMENT 'Number of iterations required for the power flow calculation to converge during the assessment.',
    `corrective_action_required` BOOLEAN COMMENT 'Boolean flag indicating whether corrective actions are required to resolve violations identified in this assessment (True = corrective actions needed, False = no actions needed).',
    `corrective_action_summary` STRING COMMENT 'Summary of recommended corrective actions to address violations, such as generation redispatch, load shedding, switching operations, or voltage control adjustments.',
    `created_timestamp` TIMESTAMP COMMENT 'The date and time when this security assessment record was first created in the system.',
    `ems_system_code` STRING COMMENT 'Identifier of the Energy Management System (EMS) that performed this security assessment.',
    `max_thermal_loading_pct` DECIMAL(18,2) COMMENT 'The highest thermal loading percentage observed on any transmission element during the assessment, expressed as a percentage of the elements rated capacity.',
    `max_voltage_pu` DECIMAL(18,2) COMMENT 'The highest voltage level observed at any bus during the assessment, expressed in per-unit (pu) of nominal voltage.',
    `min_voltage_pu` DECIMAL(18,2) COMMENT 'The lowest voltage level observed at any bus during the assessment, expressed in per-unit (pu) of nominal voltage.',
    `modified_timestamp` TIMESTAMP COMMENT 'The date and time when this security assessment record was last modified or updated.',
    `nerc_compliance_flag` BOOLEAN COMMENT 'Boolean flag indicating whether the assessment results meet NERC reliability compliance requirements (True = compliant, False = non-compliant).',
    `notification_timestamp` TIMESTAMP COMMENT 'The date and time when the Reliability Coordinator or other stakeholders were notified of critical assessment results.',
    `operator_notes` STRING COMMENT 'Free-text notes entered by the system operator regarding the assessment results, actions taken, or special conditions observed.',
    `peak_demand_flag` BOOLEAN COMMENT 'Boolean flag indicating whether the assessment was performed during a peak demand period (True = peak demand, False = off-peak).',
    `power_flow_convergence_flag` BOOLEAN COMMENT 'Boolean flag indicating whether the power flow calculation converged successfully during the assessment (True = converged, False = did not converge).',
    `reliability_coordinator_notified` BOOLEAN COMMENT 'Boolean flag indicating whether the Reliability Coordinator was notified of critical violations found in this assessment (True = notified, False = not notified).',
    `reserve_margin_mw` DECIMAL(18,2) COMMENT 'Available operating reserve margin in megawatts at the time of the assessment, representing the difference between available generation and current load.',
    `scada_snapshot_reference` STRING COMMENT 'Identifier of the SCADA data snapshot used as the base case for this security assessment.',
    `season` STRING COMMENT 'The season during which the security assessment was performed: winter, spring, summer, or fall. Seasonal conditions impact load patterns and generation availability.. Valid values are `winter|spring|summer|fall`',
    `stability_violation_count` STRING COMMENT 'Number of stability violations (transient, voltage, or oscillatory stability) detected during dynamic security assessment.',
    `study_case_name` STRING COMMENT 'The name or identifier of the study case or scenario used for this assessment, typically defined in the EMS study environment.',
    `thermal_overload_count` STRING COMMENT 'Number of thermal overload violations detected on transmission lines, transformers, or other equipment during the assessment.',
    `total_generation_mw` DECIMAL(18,2) COMMENT 'Total system generation in megawatts at the time of the security assessment.',
    `total_load_mw` DECIMAL(18,2) COMMENT 'Total system load in megawatts at the time of the security assessment.',
    `violation_count` STRING COMMENT 'Total number of reliability violations (thermal, voltage, stability) detected across all contingencies in this assessment.',
    `voltage_violation_count` STRING COMMENT 'Number of voltage limit violations (high or low voltage) detected at buses or substations during the assessment.',
    `weather_condition` STRING COMMENT 'Weather condition at the time of the assessment that may impact system reliability: normal, extreme-heat, extreme-cold, high-wind, storm, ice, or fog. [ENUM-REF-CANDIDATE: normal|extreme-heat|extreme-cold|high-wind|storm|ice|fog — 7 candidates stripped; promote to reference product]',
    `worst_contingency_description` STRING COMMENT 'Detailed description of the worst-case contingency scenario, including affected equipment and outage conditions.',
    `worst_violation_severity` STRING COMMENT 'Severity classification of the most critical violation found during the assessment: critical (immediate action required), high (urgent attention), medium (monitor closely), low (minor concern), or none (no violations).. Valid values are `critical|high|medium|low|none`',
    CONSTRAINT pk_security_assessment PRIMARY KEY(`security_assessment_id`)
) COMMENT 'Records results of real-time and study-mode security assessments (contingency analysis, power flow, voltage stability) performed by the EMS. Captures assessment timestamp, study type, number of violations found, worst-case contingency, thermal overload count, voltage violation count, and recommended corrective actions. Supports operator situational awareness and NERC reliability compliance.';

CREATE OR REPLACE TABLE `power_and_utilities_v2`.`gridops`.`operator_log` (
    `operator_log_id` BIGINT COMMENT 'Unique surrogate identifier for each operator log entry in the grid operations control room. Primary key for the operator_log data product.',
    `alarm_event_id` BIGINT COMMENT 'The alarm identifier from the SCADA or EMS system that triggered or is associated with this log entry. Populated for alarm_acknowledgment entry types. Enables traceability from the operator log back to the originating SCADA alarm in OSIsoft PI Historian or GE PowerOn.',
    `asset_registry_id` BIGINT COMMENT 'Reference to the primary grid asset (substation, transformer, feeder, generator, transmission line, etc.) associated with this log entry. Links to the asset management master record in Maximo EAM. Null if the entry is not asset-specific.',
    `control_zone_id` BIGINT COMMENT 'Reference to the grid control zone or balancing area associated with this log entry. Links to the gridops.control_zone master record for geographic and operational context.',
    `employee_id` BIGINT COMMENT 'Reference to the licensed control room operator who authored this log entry. Links to the workforce/employee master record. Required for NERC CIP personnel accountability and shift responsibility tracking.',
    `person_id` BIGINT COMMENT 'Reference to the licensed control room operator who authored this log entry. Links to the workforce/employee master record. Required for NERC CIP personnel accountability and shift responsibility tracking.',
    `registry_id` BIGINT COMMENT 'Reference to the primary grid asset (substation, transformer, feeder, generator, transmission line, etc.) associated with this log entry. Links to the asset management master record in Maximo EAM. Null if the entry is not asset-specific.',
    `reliability_event_id` BIGINT COMMENT 'Reference to a NERC reliability event or OMS outage event that this log entry is associated with. Null if the entry is not tied to a specific reliability event. Enables correlation of operator actions to event timelines.',
    `safety_audit_id` BIGINT COMMENT 'Foreign key linking to safety.safety_audit. Business justification: Safety audits review operator logs to verify compliance with operating procedures and identify violations.',
    `scada_alarm_alarm_event_id` BIGINT COMMENT 'The alarm identifier from the SCADA or EMS system that triggered or is associated with this log entry. Populated for alarm_acknowledgment entry types. Enables traceability from the operator log back to the originating SCADA alarm in OSIsoft PI Historian or GE PowerOn.',
    `scada_point_id` BIGINT COMMENT 'The SCADA data point or tag identifier from OSIsoft PI Historian associated with the measurement or control action referenced in this log entry. Enables direct linkage to real-time operational data for post-event analysis.',
    `shift_id` BIGINT COMMENT 'Reference to the operational shift during which this log entry was created. Enables shift-level aggregation of events, handover documentation, and accountability reporting.',
    `shift_supervisor_employee_id` BIGINT COMMENT 'Reference to the shift supervisor who reviewed or approved this log entry. Required for entries of critical or high priority. Supports supervisory accountability and NERC CIP-004 personnel management compliance.',
    `ace_mw` DECIMAL(18,2) COMMENT 'The Area Control Error (ACE) value in Megawatts (MW) recorded at the time of the log entry. ACE is the real-time difference between actual and scheduled interchange, adjusted for frequency deviation. Critical metric for balancing area control and NERC BAL-001 compliance.',
    `ambient_temperature_c` DECIMAL(18,2) COMMENT 'Ambient air temperature in degrees Celsius recorded at the time of the log entry. Relevant for thermal loading analysis, equipment derating, and weather-related event context.',
    `approved_timestamp` TIMESTAMP COMMENT 'The date and time when this log entry was formally approved as part of the official operational record. Null if not yet approved. Required for regulatory audit trail integrity.',
    `asset_identifier` STRING COMMENT 'Human-readable asset identifier or tag number (e.g., substation name, feeder ID, equipment tag) as recorded by the operator at time of entry. Preserved as entered to maintain the original operational record even if the asset master record changes.',
    `asset_type` STRING COMMENT 'Type classification of the grid asset referenced in this log entry. Supports asset-type-specific filtering and analytics. [ENUM-REF-CANDIDATE: substation|transformer|feeder|generator|transmission_line|bus|breaker|capacitor_bank|relay|meter — promote to reference product]',
    `attachment_reference` STRING COMMENT 'File path, document management system reference, or URL pointing to supporting documentation attached to this log entry (e.g., switching order PDF, alarm printout, event report). Null if no attachment.',
    `cip_classification` STRING COMMENT 'NERC Critical Infrastructure Protection (CIP) impact classification of the asset or action referenced in this log entry. Determines the level of cybersecurity and physical security controls applicable. Required for NERC CIP-002 asset categorization compliance.. Valid values are `high|medium|low|not_applicable`',
    `communication_method` STRING COMMENT 'The method or channel used for the communication recorded in this log entry. Relevant for NERC COM-001 compliance which mandates reliable communication facilities for grid operators.. Valid values are `voice|radio|hotline|email|ems_message|written`',
    `communication_party` STRING COMMENT 'The name or identifier of the external or internal party involved in a communication log entry (e.g., RTO/ISO operator name, neighboring utility, field crew ID, supervisor name). Populated for communication entry types.',
    `corrective_action_required` BOOLEAN COMMENT 'Indicates whether this log entry requires a follow-up corrective action, work order, or remediation activity. True = a corrective action has been identified and must be tracked. Supports NERC CIP corrective action plan (CAP) tracking.',
    `created_timestamp` TIMESTAMP COMMENT 'The date and time when this log record was first persisted in the data platform (Silver layer). Distinct from entry_timestamp (when the operator created the entry) and event_occurred_timestamp (when the event happened). Used for data lineage and audit trail.',
    `dr_dispatch_mw` DECIMAL(18,2) COMMENT 'The quantity of Demand Response (DR) capacity dispatched or curtailed in Megawatts (MW) as recorded in this log entry. Populated for demand_response entry category entries.',
    `entry_category` STRING COMMENT 'Operational category classifying the functional area of the grid operation described in this log entry. Supports domain-specific filtering for post-event analysis and regulatory reporting. [ENUM-REF-CANDIDATE: generation|transmission|distribution|demand_response|frequency_regulation|voltage_control|outage|switching|environmental|safety|administrative — promote to reference product]',
    `entry_status` STRING COMMENT 'Current lifecycle status of the log entry within the control room logging workflow. draft = in progress; submitted = finalized by operator; reviewed = reviewed by shift supervisor; approved = approved for official record; voided = invalidated with reason.. Valid values are `draft|submitted|reviewed|approved|voided`',
    `entry_timestamp` TIMESTAMP COMMENT 'The precise date and time (UTC) when the operator created or submitted the log entry in the Energy Management System (EMS) or control room logging system. This is the principal real-world event time for the log record. Conforms to yyyy-MM-ddTHH:mm:ss.SSSXXX format.',
    `entry_type` STRING COMMENT 'Categorical discriminator classifying the nature of the log entry. action = operator-initiated grid action; alarm_acknowledgment = SCADA/EMS alarm acknowledged; communication = inter-operator or inter-entity communication; observation = operational observation or reading; switching_order = switching order execution step; note = general operational note.. Valid values are `action|alarm_acknowledgment|communication|observation|switching_order|note`',
    `event_occurred_timestamp` TIMESTAMP COMMENT 'The precise date and time (UTC) when the actual grid event, alarm, or operational action physically occurred, as distinct from when the operator recorded it. Critical for post-event timeline reconstruction and NERC reliability event analysis. May differ from entry_timestamp due to logging latency.',
    `frequency_hz` DECIMAL(18,2) COMMENT 'The measured system frequency in Hertz (Hz) at the time of the log entry, as recorded by the operator or captured from SCADA. Relevant for frequency regulation events and under-frequency load shedding actions. Nominal value is 60.0000 Hz for North American grids.',
    `generation_mw` DECIMAL(18,2) COMMENT 'The measured or dispatched generation output in Megawatts (MW) referenced in this log entry. Relevant for generation dispatch, curtailment, and unit commitment actions.',
    `load_mw` DECIMAL(18,2) COMMENT 'The measured or observed load in Megawatts (MW) at the time of the log entry. Relevant for load shedding, demand response dispatch, and load balancing actions. Null if not applicable to the entry type.',
    `log_entry_number` STRING COMMENT 'Externally-known, human-readable sequential identifier for the log entry (e.g., OL-2024-00123456). Used for cross-referencing in regulatory audits, NERC compliance filings, and post-event analysis reports.',
    `narrative` STRING COMMENT 'Free-text narrative entered by the operator describing the action taken, observation made, alarm acknowledged, or communication recorded. This is the primary payload of the log entry and serves as the official operational record for post-event analysis, regulatory audits, and NERC CIP compliance reviews.',
    `nerc_reportable` BOOLEAN COMMENT 'Indicates whether this log entry is associated with a NERC-reportable reliability event per NERC EOP-004 disturbance reporting thresholds. True = event meets NERC reporting criteria and must be submitted to NERC/DOE via OE-417 or similar form.',
    `nerc_standard_reference` STRING COMMENT 'The specific NERC Reliability Standard(s) applicable to the action or event described in this log entry (e.g., BAL-001, EOP-004, CIP-007). Supports compliance mapping and regulatory audit traceability.',
    `outage_ticket_number` STRING COMMENT 'The outage ticket or trouble order number from the OMS associated with this log entry. Populated when the log entry relates to an active outage event. Enables correlation between operator actions and outage management workflows.',
    `priority_level` STRING COMMENT 'Operational priority or severity level assigned to the log entry, indicating urgency and potential grid impact. critical entries typically correspond to NERC reportable events or imminent reliability threats.. Valid values are `critical|high|medium|low|informational`',
    `puc_reportable` BOOLEAN COMMENT 'Indicates whether this log entry is associated with an event that must be reported to the state Public Utility Commission (PUC) or Public Service Commission (PSC) per state regulatory requirements. True = state regulatory reporting obligation exists.',
    `reviewed_timestamp` TIMESTAMP COMMENT 'The date and time when the shift supervisor reviewed this log entry. Null if not yet reviewed. Part of the log entry lifecycle audit trail required for NERC compliance.',
    `source_log_reference` STRING COMMENT 'The native log or record identifier from the originating source system (EMS, DMS, OMS, SCADA). Enables traceability back to the system of record for data lineage and reconciliation purposes in the Silver layer.',
    `source_system` STRING COMMENT 'The originating operational system from which this log entry was generated or ingested. ems = Energy Management System; dms = Distribution Management System; oms = Outage Management System; scada = SCADA system; pi_historian = OSIsoft PI Historian; manual = manually entered by operator.. Valid values are `ems|dms|oms|scada|pi_historian|manual`',
    `switching_order_number` STRING COMMENT 'The switching order number from the DMS/OMS system associated with this log entry. Populated for switching_order entry types. Links the operator log to the formal switching order workflow in GE PowerOn Advanced DMS/OMS.',
    `updated_timestamp` TIMESTAMP COMMENT 'The date and time when this log record was last modified in the data platform. Tracks amendments, supervisor reviews, and status transitions. Required for Silver layer change data capture and audit trail completeness.',
    `void_reason` STRING COMMENT 'Free-text explanation for why this log entry was voided or invalidated. Populated only when entry_status = voided. Maintains audit trail integrity by preserving the reason for invalidation rather than deleting the record.',
    `voltage_kv` DECIMAL(18,2) COMMENT 'The measured or observed voltage in kilovolts (kV) at the referenced asset or bus at the time of the log entry. Relevant for voltage control actions, voltage deviation events, and reactive power dispatch entries.',
    `weather_condition` STRING COMMENT 'Prevailing weather condition at the time of the log entry as observed or reported by the operator. Relevant for weather-related outage events, load forecasting context, and post-event causal analysis. [ENUM-REF-CANDIDATE: clear|cloudy|rain|thunderstorm|snow|ice|high_wind|fog|extreme_heat — promote to reference product]',
    `work_order_number` STRING COMMENT 'The Maximo EAM work order number associated with corrective or maintenance actions triggered by this log entry. Populated when corrective_action_required = True. Enables traceability from operational events to maintenance work execution.',
    CONSTRAINT pk_operator_log PRIMARY KEY(`operator_log_id`)
) COMMENT 'Chronological log of operator actions, observations, and communications recorded in the grid operations control room. Each entry captures timestamp, operator ID, shift, log entry type (action, alarm acknowledgment, communication, note), associated asset or event, and free-text narrative. Serves as the official operational record for post-event analysis, regulatory audits, and NERC CIP compliance.';

CREATE OR REPLACE TABLE `power_and_utilities_v2`.`gridops`.`alarm_event` (
    `alarm_event_id` BIGINT COMMENT 'Unique identifier for the alarm event record. Primary key.',
    `asset_registry_id` BIGINT COMMENT 'Identifier of the physical grid asset (transformer, breaker, line, generator, etc.) associated with this alarm. Links to the enterprise asset management system.',
    `balancing_area_id` BIGINT COMMENT 'Identifier of the NERC-registered balancing area where the alarm occurred. Links to the gridops.balancing_area product.',
    `control_zone_id` BIGINT COMMENT 'Identifier of the control zone or dispatch area responsible for this alarm. Links to the gridops.control_zone product.',
    `distribution_switching_order_id` BIGINT COMMENT 'Identifier of the switching order associated with this alarm if the alarm was triggered during planned switching operations. Links to gridops.switching_order.',
    `employee_id` BIGINT COMMENT 'User ID or employee number of the operator who acknowledged the alarm. Used for performance tracking and audit trails.',
    `gridops_outage_event_id` BIGINT COMMENT 'Identifier of the associated outage event if this alarm is related to a customer outage or system disturbance. Links to the OMS (Outage Management System).',
    `registry_id` BIGINT COMMENT 'Identifier of the physical grid asset (transformer, breaker, line, generator, etc.) associated with this alarm. Links to the enterprise asset management system.',
    `scada_point_id` BIGINT COMMENT 'Unique identifier of the SCADA point or tag that generated this alarm. Links to the monitored asset or measurement point in the SCADA system.',
    `shelved_by_operator_employee_id` BIGINT COMMENT 'User ID of the operator who shelved the alarm. Required for audit and compliance.',
    `transmission_substation_id` BIGINT COMMENT 'Identifier of the substation where the alarmed asset is located. Null for transmission line or distributed asset alarms.',
    `work_order_id` BIGINT COMMENT 'Identifier of the maintenance or repair work order created in response to this alarm. Links to the EAM (Enterprise Asset Management) system.',
    `acknowledged_by_operator_name` STRING COMMENT 'Full name of the operator who acknowledged the alarm. Denormalized for reporting convenience.',
    `acknowledged_flag` BOOLEAN COMMENT 'Indicates whether the alarm has been acknowledged by an operator. True if acknowledged, False if still unacknowledged.',
    `acknowledged_timestamp` TIMESTAMP COMMENT 'Date and time when the alarm was acknowledged by an operator. Null if not yet acknowledged.',
    `alarm_category` STRING COMMENT 'Business classification of the alarm condition: thermal_overload (conductor or transformer heating), voltage_violation (over/under voltage), frequency_deviation (grid frequency out of range), equipment_failure (device malfunction), communication_loss (telemetry failure), or protection_system (relay or breaker operation).. Valid values are `thermal_overload|voltage_violation|frequency_deviation|equipment_failure|communication_loss|protection_system`',
    `alarm_count` STRING COMMENT 'Number of times this alarm condition has occurred for this asset within the current analysis window. Used for alarm flood detection and nuisance alarm identification.',
    `alarm_description` STRING COMMENT 'Detailed description of the alarm condition, including context, potential causes, and recommended operator actions. Used for training and alarm rationalization.',
    `alarm_message` STRING COMMENT 'Full alarm message text as presented to the operator in the SCADA/EMS system. Includes asset name, condition description, and measured value.',
    `alarm_state` STRING COMMENT 'Current lifecycle state of the alarm: active (unacknowledged and condition persists), acknowledged (operator has seen it), cleared (condition returned to normal), shelved (temporarily disabled), suppressed (filtered by alarm management logic), or stale (communication lost).. Valid values are `active|acknowledged|cleared|shelved|suppressed|stale`',
    `alarm_timestamp` TIMESTAMP COMMENT 'Precise date and time when the alarm condition was detected and the alarm was triggered in the SCADA/EMS system. This is the operational event time, distinct from record creation time.',
    `alarm_type` STRING COMMENT 'Classification of the alarm based on the nature of the monitored condition: analog (threshold violation on continuous measurement), digital (discrete state change), calculated (derived condition), communication (loss of signal), equipment_status (device health), or protection_operation (relay trip).. Valid values are `analog|digital|calculated|communication|equipment_status|protection_operation`',
    `cip_classification` STRING COMMENT 'NERC CIP impact classification of the asset or system that generated this alarm: high (critical cyber assets), medium (medium impact BES cyber systems), low (low impact BES cyber systems), or not_applicable.. Valid values are `high|medium|low|not_applicable`',
    `cleared_timestamp` TIMESTAMP COMMENT 'Date and time when the alarm condition returned to normal and the alarm was cleared. Null if alarm is still active.',
    `ems_alarm_code` STRING COMMENT 'Native alarm identifier from the EMS system. Used for cross-system reconciliation and audit trails.',
    `gis_feature_reference` STRING COMMENT 'Identifier of the GIS feature (point, line, polygon) representing the alarmed asset in the enterprise GIS system. Enables spatial analysis and map visualization.',
    `latitude` DECIMAL(18,2) COMMENT 'Geographic latitude coordinate (decimal degrees) of the alarmed asset location. Used for spatial analysis and mobile workforce dispatch.',
    `longitude` DECIMAL(18,2) COMMENT 'Geographic longitude coordinate (decimal degrees) of the alarmed asset location. Used for spatial analysis and mobile workforce dispatch.',
    `nerc_reportable_flag` BOOLEAN COMMENT 'Indicates whether this alarm represents a condition that must be reported to NERC under reliability standards (e.g., Bulk Electric System disturbance, CIP cyber security event). True if reportable, False otherwise.',
    `priority_level` STRING COMMENT 'Operator response priority assigned to the alarm per ISA-18.2 alarm rationalization methodology. Critical alarms require immediate action; informational alarms are for awareness only.. Valid values are `critical|high|medium|low|informational`',
    `record_created_timestamp` TIMESTAMP COMMENT 'Date and time when this alarm event record was first inserted into the data platform. Distinct from alarm_timestamp (operational event time). Used for data lineage and audit.',
    `record_updated_timestamp` TIMESTAMP COMMENT 'Date and time when this alarm event record was last modified in the data platform. Updated when alarm state changes (acknowledged, cleared, shelved).',
    `shelved_flag` BOOLEAN COMMENT 'Indicates whether the alarm has been temporarily shelved (suppressed) by an operator. True if shelved, False otherwise. Shelving is used during maintenance or known abnormal conditions.',
    `shelved_reason` STRING COMMENT 'Operator-entered justification for shelving the alarm (e.g., Planned maintenance on Transformer T-101, Known communication issue during storm).',
    `shelved_timestamp` TIMESTAMP COMMENT 'Date and time when the alarm was shelved. Null if not shelved.',
    `suppressed_flag` BOOLEAN COMMENT 'Indicates whether the alarm was automatically suppressed by alarm management logic (e.g., flood suppression, consequential alarm filtering). True if suppressed, False otherwise.',
    `suppression_rule` STRING COMMENT 'Name or identifier of the alarm management rule that suppressed this alarm (e.g., Substation Lockout Flood Suppression, Communication Loss Consequential Filter).',
    `threshold_value` DECIMAL(18,2) COMMENT 'The configured threshold or setpoint that was exceeded to trigger the alarm (e.g., high limit, low limit, deadband). Null for digital/status alarms.',
    `time_to_acknowledge_seconds` STRING COMMENT 'Elapsed time in seconds between alarm_timestamp and acknowledged_timestamp. Key performance indicator for operator response time per ISA-18.2.',
    `time_to_clear_seconds` STRING COMMENT 'Elapsed time in seconds between alarm_timestamp and cleared_timestamp. Measures total alarm duration and system restoration time.',
    `trigger_value` DECIMAL(18,2) COMMENT 'The measured value that triggered the alarm condition (e.g., actual current in amps, voltage in kV, temperature in Celsius, frequency in Hz). Null for digital/status alarms.',
    `unit_of_measure` STRING COMMENT 'Engineering unit for the trigger_value and threshold_value fields (e.g., A for amps, kV for kilovolts, MW for megawatts, Hz for hertz, C for Celsius, psi for pressure).',
    `voltage_level_kv` DECIMAL(18,2) COMMENT 'Nominal voltage level in kilovolts (kV) of the circuit or equipment where the alarm occurred (e.g., 345, 138, 69, 13.8, 4.16).',
    CONSTRAINT pk_alarm_event PRIMARY KEY(`alarm_event_id`)
) COMMENT 'Records each SCADA/EMS alarm generated from monitored grid assets including thermal overloads, voltage violations, equipment failures, communication loss, and protection system operations. Captures alarm point, alarm type, priority level (per ISA-18.2 alarm management standard), trigger value, threshold, acknowledgment status, acknowledging operator, shelving status, and time to acknowledge/clear. Supports alarm rationalization, operator performance review, and NERC CIP-007 compliance.';

CREATE OR REPLACE TABLE `power_and_utilities_v2`.`gridops`.`energy_balance` (
    `energy_balance_id` BIGINT COMMENT 'Unique surrogate identifier for each energy balance record in the balancing area. Primary key for the energy_balance data product.',
    `aggregation_group_id` BIGINT COMMENT 'Foreign key linking to der.aggregation_group. Business justification: Energy balance reports are broken out by aggregation groups for market settlement and DER performance analysis.',
    `balancing_area_id` BIGINT COMMENT 'Reference to the NERC-registered Balancing Authority Area (BAA) for which this energy balance record applies. Links to the balancing_area master record.',
    `employee_id` BIGINT COMMENT 'Identifier of the system operator or EMS user responsible for reviewing or manually adjusting this energy balance record. Populated for manual entries or operator-confirmed revisions. Links to workforce/operator master data.',
    `gl_account_id` BIGINT COMMENT 'Foreign key linking to finance.gl_account. Business justification: Energy Balance records are posted to the General Ledger for financial statements and regulatory filings.',
    `person_id` BIGINT COMMENT 'Identifier of the system operator or EMS user responsible for reviewing or manually adjusting this energy balance record. Populated for manual entries or operator-confirmed revisions. Links to workforce/operator master data.',
    `rate_schedule_id` BIGINT COMMENT 'Foreign key linking to product.rate_schedule. Business justification: Settlement report requires applying the correct rate schedule to each balancing area energy balance for billing compliance.',
    `rate_case_id` BIGINT COMMENT 'Foreign key linking to regulatory.rate_case. Business justification: Energy balance statements are submitted as part of rate‑case settlements; linking provides traceability to the specific rate case.',
    `ace_average_mw` DECIMAL(18,2) COMMENT 'Average Area Control Error (ACE) over the interval period in Megawatts (MW). Used for NERC Control Performance Standard (CPS1/CPS2) compliance calculations and regulatory reporting to NERC and state PUCs.',
    `ace_mw` DECIMAL(18,2) COMMENT 'Area Control Error (ACE) for the balancing area during the interval, expressed in Megawatts (MW). ACE = (Actual Net Interchange – Scheduled Net Interchange) – 10B(Actual Frequency – Scheduled Frequency). Key NERC BAL-001 compliance metric measuring real-time generation-load balance.',
    `actual_interchange_mwh` DECIMAL(18,2) COMMENT 'Actual metered energy interchange across balancing area tie-lines during the interval, expressed in MWh. Compared against scheduled_interchange_mwh to compute interchange deviation for NERC BAL compliance.',
    `cps1_score` DECIMAL(18,2) COMMENT 'NERC Control Performance Standard 1 (CPS1) compliance score for the interval, expressed as a percentage. CPS1 measures the one-minute average ACE relative to frequency deviation. NERC requires a minimum 100% CPS1 score on a rolling 12-month basis.',
    `cps2_violation_flag` BOOLEAN COMMENT 'Indicates whether the balancing area exceeded the NERC Control Performance Standard 2 (CPS2) ACE limit (L10) during this interval. True = CPS2 violation occurred; False = within limits. Triggers mandatory NERC reporting when True.',
    `created_timestamp` TIMESTAMP COMMENT 'Timestamp when this energy balance record was first created in the Silver Layer lakehouse, typically upon ingestion from SCADA/PI Historian or EMS. Audit trail field for data lineage.',
    `data_quality_code` STRING COMMENT 'Quality indicator for the energy balance record derived from SCADA/PI Historian telemetry quality flags. good = validated telemetry; suspect = questionable reading requiring review; estimated = gap-filled or interpolated; bad = failed quality check; missing = no telemetry received.. Valid values are `good|suspect|estimated|bad|missing`',
    `data_source` STRING COMMENT 'Identifies the primary source system from which this energy balance record was derived. scada = GE PowerOn SCADA telemetry; pi_historian = OSIsoft PI Historian; ems = Energy Management System calculated; manual = operator-entered; estimated = gap-filled estimate.. Valid values are `scada|pi_historian|ems|manual|estimated`',
    `der_net_injection_mwh` DECIMAL(18,2) COMMENT 'Net energy injected into the grid from Distributed Energy Resources (DER) including rooftop solar, battery storage, and small-scale generation during the interval, expressed in MWh. Tracked via DERMS integration.',
    `dr_response_mwh` DECIMAL(18,2) COMMENT 'Energy reduction achieved through Demand Response (DR) dispatch during the interval, expressed in MWh. Represents load curtailment from DR programs activated by the EMS/DERMS. Used for DR settlement and NERC BAL compliance.',
    `eia_930_reported_flag` BOOLEAN COMMENT 'Indicates whether this energy balance record has been included in an EIA Form 930 (Hourly Electric Grid Monitor) submission. True = reported to EIA; False = pending submission. Supports regulatory reporting completeness tracking.',
    `eia_ba_code` STRING COMMENT 'EIA-assigned balancing authority code for the reporting entity. Required for EIA Form 930 (Hourly Electric Grid Monitor) submission. Uniquely identifies the balancing authority in EIAs national energy data system.',
    `finalized_timestamp` TIMESTAMP COMMENT 'Timestamp when this energy balance record was promoted from preliminary to final status following validation. Marks the completion of the operational accounting close for the interval.',
    `fossil_generation_mwh` DECIMAL(18,2) COMMENT 'Total energy generated from fossil fuel sources (natural gas, coal, oil) within the balancing area during the interval, expressed in MWh. Subset of total_generation_mwh. Used for emissions reporting to EPA and EIA.',
    `frequency_bias_mw_per_hz` DECIMAL(18,2) COMMENT 'The frequency bias setting (B) applied in the ACE calculation formula for this interval, expressed in MW/Hz. Represents the balancing areas contribution to primary frequency response. Filed annually with NERC.',
    `frequency_hz` DECIMAL(18,2) COMMENT 'Average system frequency measured in Hertz (Hz) during the interval. Nominal value is 60.000 Hz for the North American interconnection. Deviations from nominal drive ACE calculations and frequency regulation dispatch.',
    `inadvertent_interchange_mwh` DECIMAL(18,2) COMMENT 'Accumulated inadvertent energy interchange for the interval, expressed in MWh. Represents the difference between actual and scheduled interchange that must be repaid to neighboring balancing areas per NERC BAL-005 payback requirements.',
    `interconnection` STRING COMMENT 'North American electrical interconnection to which this balancing area belongs. Determines synchronous frequency reference and reliability coordinator jurisdiction.. Valid values are `Eastern|Western|ERCOT|Quebec|Alaska|Hawaii`',
    `interval_duration_minutes` STRING COMMENT 'Duration of the energy balance interval in minutes (e.g., 5, 15, 30, 60). Distinguishes sub-hourly from hourly records and supports aggregation logic.',
    `interval_end_timestamp` TIMESTAMP COMMENT 'The ending timestamp of the energy accounting interval. Together with interval_start_timestamp defines the precise measurement window for this balance record.',
    `interval_start_timestamp` TIMESTAMP COMMENT 'The beginning timestamp of the energy accounting interval (hourly or sub-hourly) for which this balance record is computed. Derived from SCADA/PI Historian telemetry. Conforms to ISO 8601 format yyyy-MM-ddTHH:mm:ss.SSSXXX.',
    `load_forecast_error_mwh` DECIMAL(18,2) COMMENT 'Difference between actual total load and forecasted load for the interval, expressed in MWh (actual minus forecast). Positive value indicates load exceeded forecast; negative indicates load was below forecast. Used to evaluate forecasting accuracy and improve EMS models.',
    `load_forecast_mwh` DECIMAL(18,2) COMMENT 'Forecasted energy load for the balancing area during the interval, expressed in MWh. Generated by the EMS load forecasting module prior to the operating interval. Used to compute forecast error and support dispatch planning.',
    `nerc_compliance_flag` BOOLEAN COMMENT 'Indicates whether this energy balance interval is fully compliant with applicable NERC BAL reliability standards (BAL-001, BAL-002, BAL-003, BAL-005). True = compliant; False = one or more NERC BAL standard violations detected. Triggers compliance workflow when False.',
    `nerc_tag_number` STRING COMMENT 'NERC e-Tag identifier associated with the scheduled interchange transactions contributing to this energy balance interval. Used for cross-referencing with NERC e-Tag system for interchange scheduling and curtailment tracking.',
    `net_interchange_mwh` DECIMAL(18,2) COMMENT 'Net energy exchanged across the balancing area boundary during the interval, expressed in Megawatt-Hours (MWh). Positive value indicates net export; negative value indicates net import. Computed as sum of all scheduled and actual tie-line flows.',
    `nuclear_generation_mwh` DECIMAL(18,2) COMMENT 'Total energy generated from nuclear sources within the balancing area during the interval, expressed in MWh. Subset of total_generation_mwh. Reported separately per NRC and EIA requirements.',
    `operating_date` DATE COMMENT 'The calendar date (in local prevailing time) to which this energy balance interval belongs. Used for daily aggregation, settlement, and regulatory reporting aligned to the operating day.',
    `operating_hour` STRING COMMENT 'The hour of the operating day (0–23) in which this interval falls, expressed in local prevailing time. Used for hourly aggregation, TOU analysis, and RTO/ISO settlement hour alignment.',
    `operating_reserve_mw` DECIMAL(18,2) COMMENT 'Total operating reserve available in the balancing area at the start of the interval, expressed in Megawatts (MW). Includes spinning and non-spinning reserves. NERC BAL-002 compliance metric.',
    `record_status` STRING COMMENT 'Lifecycle status of the energy balance record indicating its processing and settlement state. preliminary = near-real-time estimate; final = validated operational accounting; revised = corrected after initial finalization; settled = accepted by RTO/ISO for financial settlement; void = invalidated record.. Valid values are `preliminary|final|revised|settled|void`',
    `renewable_generation_mwh` DECIMAL(18,2) COMMENT 'Total energy generated from renewable sources (wind, solar, hydro, geothermal, biomass) within the balancing area during the interval, expressed in MWh. Subset of total_generation_mwh. Supports Renewable Energy Certificate (REC) tracking and IRP reporting.',
    `revision_number` STRING COMMENT 'Sequential revision counter for this energy balance record. Starts at 0 for the initial preliminary record and increments with each correction or resettlement. Supports audit trail and version management for regulatory submissions.',
    `revision_reason` STRING COMMENT 'Free-text description of the reason for the most recent revision to this energy balance record (e.g., meter data correction, SCADA telemetry gap fill, RTO settlement adjustment). Populated only when revision_number > 0.',
    `rto_iso_code` STRING COMMENT 'Code identifying the Regional Transmission Organization (RTO) or Independent System Operator (ISO) with which this balancing area is affiliated for market settlement and reliability coordination (e.g., PJM, MISO, CAISO, SPP, ERCOT, NYISO, ISO-NE).',
    `scheduled_interchange_mwh` DECIMAL(18,2) COMMENT 'Total energy interchange scheduled across balancing area tie-lines for the interval, expressed in MWh. Represents the Day-Ahead Market (DAM) or intra-day scheduled position prior to real-time deviations.',
    `settled_timestamp` TIMESTAMP COMMENT 'Timestamp when this energy balance record was accepted and confirmed by the RTO/ISO for financial settlement. Marks the completion of the market settlement lifecycle for the interval.',
    `settlement_period_type` STRING COMMENT 'Identifies the market settlement period type for this energy balance record. real_time = RTM interval data; day_ahead = DAM scheduled position; final_settlement = post-operating-day settlement; resettlement = corrected settlement after dispute resolution.. Valid values are `real_time|day_ahead|final_settlement|resettlement`',
    `spinning_reserve_mw` DECIMAL(18,2) COMMENT 'Spinning (synchronized) reserve available in the balancing area during the interval, expressed in MW. Subset of operating_reserve_mw representing generation online and capable of immediate response. NERC BAL-002 compliance metric.',
    `total_generation_mwh` DECIMAL(18,2) COMMENT 'Total electrical energy generated within the balancing area during the interval, expressed in Megawatt-Hours (MWh). Aggregates all generation resources including fossil fuel, nuclear, and renewable sources. Sourced from SCADA/PI Historian telemetry.',
    `total_load_mwh` DECIMAL(18,2) COMMENT 'Total electrical energy consumed by load within the balancing area during the interval, expressed in Megawatt-Hours (MWh). Represents native load plus losses. Sourced from SCADA/PI Historian telemetry.',
    `transmission_losses_mwh` DECIMAL(18,2) COMMENT 'Estimated electrical energy lost in transmission and distribution within the balancing area during the interval, expressed in MWh. Used in energy accounting identity: Generation = Load + Net Interchange + Losses.',
    `updated_timestamp` TIMESTAMP COMMENT 'Timestamp of the most recent update to this energy balance record in the Silver Layer lakehouse. Updated on each revision, status change, or data quality correction.',
    CONSTRAINT pk_energy_balance PRIMARY KEY(`energy_balance_id`)
) COMMENT 'Hourly and sub-hourly energy balance records for the balancing area capturing total generation (MWh), total load (MWh), net interchange (MWh), losses, and ACE (Area Control Error). Derived from SCADA telemetry and used for NERC BAL compliance reporting, settlement with RTOs/ISOs, and operational accounting. Represents the authoritative near-real-time energy accounting record for the balancing area.';

CREATE OR REPLACE TABLE `power_and_utilities_v2`.`gridops`.`transmission_limit` (
    `transmission_limit_id` BIGINT COMMENT 'Unique identifier for the transmission limit record. Primary key for this entity.',
    `balancing_area_id` BIGINT COMMENT 'Foreign key linking to gridops.balancing_area. Business justification: Transmission limits are defined per balancing area; FK adds relational context.',
    `employee_id` BIGINT COMMENT 'Name or identifier of the transmission engineer or reliability coordinator who approved this limit for operational use.',
    `facility_id` BIGINT COMMENT 'Identifier of the transmission facility (line, transformer, flowgate, interface) to which this limit applies.',
    `ambient_temperature_c` DECIMAL(18,2) COMMENT 'Ambient temperature in degrees Celsius at which the limit rating was calculated. Used for dynamic rating adjustments.',
    `approval_date` DATE COMMENT 'Date on which this transmission limit was formally approved for enforcement in real-time operations.',
    `contingency_name` STRING COMMENT 'Name of the contingency scenario (e.g., N-1, N-2 outage) under which this limit applies. Identifies the specific outage condition that triggers this constraint.',
    `contingency_type` STRING COMMENT 'Classification of the contingency: N-1 (single element outage), N-2 (double contingency), base case (no outage), or extreme event.. Valid values are `n_minus_1|n_minus_2|base_case|extreme_event`',
    `created_timestamp` TIMESTAMP COMMENT 'Timestamp when this transmission limit record was first created in the system.',
    `dynamic_rating_enabled` BOOLEAN COMMENT 'Indicates whether dynamic line rating (real-time adjustment based on weather and conductor temperature) is enabled for this facility. True if enabled, False otherwise.',
    `effective_date` DATE COMMENT 'Date from which this transmission limit becomes active and enforceable in real-time operations and EMS security analysis.',
    `emergency_rating_15min_mva` DECIMAL(18,2) COMMENT 'Short-term emergency rating in MVA that the facility can sustain for up to 15 minutes without damage, used during contingency conditions.',
    `emergency_rating_4hr_mva` DECIMAL(18,2) COMMENT 'Long-term emergency rating in MVA that the facility can sustain for up to 4 hours, typically used for post-contingency load relief operations.',
    `ems_limit_code` STRING COMMENT 'Identifier of this limit record in the Energy Management System (EMS) used for real-time security analysis and dispatch.',
    `expiration_date` DATE COMMENT 'Date on which this transmission limit expires or is superseded by a new limit. Null if the limit is open-ended.',
    `ferc_jurisdiction` BOOLEAN COMMENT 'Indicates whether this transmission facility and its limits fall under FERC jurisdiction (interstate transmission). True if FERC-jurisdictional, False otherwise.',
    `gis_feature_reference` STRING COMMENT 'Identifier of the corresponding transmission facility feature in the GIS system, used for geospatial analysis and mapping.',
    `limit_notes` STRING COMMENT 'Free-text notes providing additional context, operational instructions, or special conditions related to this transmission limit.',
    `limit_source` STRING COMMENT 'Origin of the limit value: thermal analysis, voltage analysis, stability study, manufacturer equipment rating, field test measurement, or engineering judgment.. Valid values are `thermal_analysis|voltage_analysis|stability_study|manufacturer_rating|field_test|engineering_judgment`',
    `limit_status` STRING COMMENT 'Current lifecycle status of the limit record: active (enforced in EMS), inactive, suspended (temporarily not enforced), pending approval, or retired.. Valid values are `active|inactive|suspended|pending_approval|retired`',
    `limit_type` STRING COMMENT 'Physical constraint type: thermal (conductor heating), voltage (bus voltage deviation), stability (transient/voltage/oscillatory stability limits).. Valid values are `thermal|voltage|stability|transient_stability|voltage_stability|oscillatory_stability`',
    `load_dump_rating_mva` DECIMAL(18,2) COMMENT 'Maximum load that can be shed or transferred through this facility during emergency load dump or load shedding operations.',
    `modified_timestamp` TIMESTAMP COMMENT 'Timestamp when this transmission limit record was last modified or updated.',
    `nerc_cip_classification` STRING COMMENT 'NERC CIP impact classification of the facility: high, medium, low, or not applicable. Determines cybersecurity and physical security requirements.. Valid values are `high|medium|low|not_applicable`',
    `normal_rating_mva` DECIMAL(18,2) COMMENT 'Continuous normal operating limit in megavolt-amperes (MVA) under normal ambient and system conditions. This is the baseline thermal or transfer capability limit.',
    `normal_rating_mw` DECIMAL(18,2) COMMENT 'Continuous normal operating limit in megawatts (MW) for real power transfer. Used for flowgates and interfaces where MW is the primary constraint metric.',
    `rto_iso_code` STRING COMMENT 'Code of the RTO or ISO that has operational authority over this transmission facility and enforces these limits in market operations.',
    `scada_monitored` BOOLEAN COMMENT 'Indicates whether this transmission limit is actively monitored in real-time via SCADA telemetry. True if monitored, False otherwise.',
    `season_code` STRING COMMENT 'Season during which this limit applies: summer, winter, spring, fall, or year-round. Seasonal limits reflect ambient temperature and load pattern variations.. Valid values are `summer|winter|spring|fall|year_round`',
    `seasonal_adjustment_factor` DECIMAL(18,2) COMMENT 'Multiplier applied to base ratings to account for seasonal ambient temperature variations (e.g., summer de-rating, winter up-rating). Typically ranges from 0.8 to 1.2.',
    `study_reference` STRING COMMENT 'Reference identifier or document name of the engineering study (thermal, voltage, or stability study) that established this limit.',
    `voltage_level_kv` DECIMAL(18,2) COMMENT 'Nominal voltage level in kilovolts (kV) of the transmission facility (e.g., 138 kV, 230 kV, 345 kV, 500 kV).',
    `voltage_limit_high_kv` DECIMAL(18,2) COMMENT 'Upper voltage limit in kilovolts (kV) for voltage-constrained facilities. Exceeding this limit may cause equipment damage or system instability.',
    `voltage_limit_low_kv` DECIMAL(18,2) COMMENT 'Lower voltage limit in kilovolts (kV) for voltage-constrained facilities. Falling below this limit may cause voltage collapse or equipment malfunction.',
    CONSTRAINT pk_transmission_limit PRIMARY KEY(`transmission_limit_id`)
) COMMENT 'Master records for thermal, voltage, and stability limits on transmission facilities (lines, transformers, flowgates, interfaces) enforced in real-time operations. Captures normal rating (MVA/MW), emergency rating (15-min/4-hr), load dump rating, seasonal and ambient-adjusted ratings, applicable contingency, limit source (thermal/voltage/stability), and effective date. These limits are the hard constraints enforced by EMS security analysis and operator dispatch decisions per NERC FAC-008.';

CREATE OR REPLACE TABLE `power_and_utilities_v2`.`gridops`.`weather_forecast` (
    `weather_forecast_id` BIGINT COMMENT 'Unique identifier for each weather forecast record.',
    `superseded_weather_forecast_id` BIGINT COMMENT 'Self-referencing FK on weather_forecast (superseded_weather_forecast_id)',
    `cloud_cover_pct` DECIMAL(18,2) COMMENT 'Forecasted fraction of sky covered by clouds, expressed as a percentage.',
    `data_quality_flag` STRING COMMENT 'Overall data quality assessment for the forecast record.. Valid values are `good|fair|poor`',
    `dew_point_c` DECIMAL(18,2) COMMENT 'Forecasted dew point temperature in degrees Celsius.',
    `forecast_confidence_score` DECIMAL(18,2) COMMENT 'Numerical confidence rating (0‑100) assigned by the model to the forecast.',
    `forecast_horizon_hours` STRING COMMENT 'Number of hours ahead that the forecast covers.',
    `forecast_horizon_type` STRING COMMENT 'Granularity of the forecast period (e.g., hourly, daily).. Valid values are `hourly|daily|weekly|monthly`',
    `forecast_timestamp` TIMESTAMP COMMENT 'Date and time for which the forecast values are applicable.',
    `humidity_adjustment_factor` DECIMAL(18,2) COMMENT 'Numeric factor used to modify forecast values for humidity influences.',
    `humidity_pct` DECIMAL(18,2) COMMENT 'Forecasted relative humidity as a percentage.',
    `is_adjusted_for_humidity` BOOLEAN COMMENT 'Indicates whether humidity‑based corrections were applied (true/false).',
    `is_adjusted_for_terrain` BOOLEAN COMMENT 'Indicates whether terrain effects were applied to the forecast (true/false).',
    `is_adjusted_for_time_of_day` BOOLEAN COMMENT 'Indicates whether diurnal effects were applied to the forecast (true/false).',
    `issue_timestamp` TIMESTAMP COMMENT 'Date and time when the forecast was generated by the forecasting system.',
    `latitude` DOUBLE COMMENT 'Geographic latitude of the forecast location in decimal degrees.',
    `longitude` DOUBLE COMMENT 'Geographic longitude of the forecast location in decimal degrees.',
    `model_version` STRING COMMENT 'Identifier of the forecasting model version used to generate the forecast.',
    `notes` STRING COMMENT 'Free‑form comments or annotations from forecasters.',
    `precipitation_inches` DECIMAL(18,2) COMMENT 'Forecasted total precipitation depth in inches.',
    `pressure_hpa` DECIMAL(18,2) COMMENT 'Forecasted sea‑level atmospheric pressure in hectopascals.',
    `probability_of_precipitation_pct` DECIMAL(18,2) COMMENT 'Forecasted likelihood of precipitation expressed as a percentage.',
    `record_created_date` DATE COMMENT 'Calendar date when the forecast record was first stored in the lakehouse.',
    `record_updated_timestamp` TIMESTAMP COMMENT 'Date and time of the most recent update to the forecast record.',
    `severe_weather_flag` BOOLEAN COMMENT 'Indicates whether the forecast includes any severe weather conditions (true/false).',
    `solar_radiation_w_m2` DECIMAL(18,2) COMMENT 'Forecasted solar irradiance in watts per square meter.',
    `source_system` STRING COMMENT 'External system or agency providing the forecast data.. Valid values are `NOAA|ECMWF|GFS`',
    `temperature_c` DECIMAL(18,2) COMMENT 'Forecasted ambient air temperature in degrees Celsius.',
    `terrain_adjustment_factor` DECIMAL(18,2) COMMENT 'Numeric factor used to modify forecast values for terrain influences.',
    `time_of_day_adjustment_factor` DECIMAL(18,2) COMMENT 'Numeric factor used to modify forecast values for time‑of‑day influences.',
    `uv_index` STRING COMMENT 'Forecasted ultraviolet index indicating sunburn risk.',
    `visibility_mi` DECIMAL(18,2) COMMENT 'Forecasted horizontal visibility distance in miles.',
    `weather_zone_code` STRING COMMENT 'Standard code identifying the geographic weather zone for the forecast.',
    `wind_direction_deg` STRING COMMENT 'Forecasted wind direction expressed as degrees from true north.',
    `wind_speed_mph` DECIMAL(18,2) COMMENT 'Forecasted wind speed in miles per hour.',
    CONSTRAINT pk_weather_forecast PRIMARY KEY(`weather_forecast_id`)
) COMMENT 'Weather forecast data integrated into grid operations for load forecasting, storm preparation, and renewable generation prediction including temperature, wind speed, cloud cover, and precipitation';

CREATE OR REPLACE TABLE `power_and_utilities_v2`.`gridops`.`dispatch_participation` (
    `dispatch_participation_id` BIGINT COMMENT 'Primary key for the dispatch_participation association',
    `dr_dispatch_event_id` BIGINT COMMENT 'Foreign key linking to dr_dispatch_event',
    `meter_id` BIGINT COMMENT 'Foreign key linking to meter',
    `actual_reduction_mw` DECIMAL(18,2) COMMENT 'Actual MW reduction achieved by the meter during the dispatch event',
    `participation_status` STRING COMMENT 'Status of the meters participation in the dispatch event (e.g., responded, no‑response)',
    `response_timestamp` TIMESTAMP COMMENT 'Timestamp when the meter reported its response to the dispatch event',
    CONSTRAINT pk_dispatch_participation PRIMARY KEY(`dispatch_participation_id`)
) COMMENT 'This association product represents the participation of meters in demand‑response dispatch events. Each record links one dr_dispatch_event to one meter and captures attributes that exist only in the context of this relationship.. Existence Justification: A demand‑response dispatch event can involve many meters, and a given meter can be dispatched in many events over time. The utility records each participation with status, actual reduction, and response timestamp, which are attributes of the participation itself. This relationship is actively managed by grid operations and is a distinct business entity.';

CREATE OR REPLACE TABLE `power_and_utilities_v2`.`gridops`.`switching_order_material_allocation` (
    `switching_order_material_allocation_id` BIGINT COMMENT 'Primary key for the switching_order_material_allocation association',
    `gridops_switching_order_id` BIGINT COMMENT 'Foreign key linking to the switching order',
    `material_master_id` BIGINT COMMENT 'Foreign key linking to the material master',
    `line_status` STRING COMMENT 'Current status of the material line (e.g., planned, allocated, released)',
    `quantity` DECIMAL(18,2) COMMENT 'Amount of the material allocated to the switching order',
    `unit_of_measure` STRING COMMENT 'Unit of measure for the allocated quantity (e.g., EA, KG)',
    CONSTRAINT pk_switching_order_material_allocation PRIMARY KEY(`switching_order_material_allocation_id`)
) COMMENT 'Association table that records which material items are allocated to each grid operations switching order, including the quantity, unit of measure, and line status for each material requirement.. Existence Justification: A switching order often requires several spare parts or equipment items, and each material can be used in many different switching orders. The utility tracks the quantity, unit of measure, and status of each material assigned to a specific order, creating a distinct record for every order‑material pair.';

CREATE OR REPLACE TABLE `power_and_utilities_v2`.`gridops`.`control_center` (
    `control_center_id` BIGINT COMMENT 'Primary key for control_center',
    `backup_control_center_id` BIGINT COMMENT 'Self-referencing FK on control_center (backup_control_center_id)',
    `address` STRING COMMENT 'Street address of the control center facility.',
    `capacity_mw` DECIMAL(18,2) COMMENT 'Maximum generation or load handling capacity in megawatts.',
    `city` STRING COMMENT 'City where the control center is located.',
    `control_center_code` STRING COMMENT 'External code used to reference the control center in operational systems.',
    `contact_email` STRING COMMENT 'Primary email address for the control center contact point.',
    `contact_phone` STRING COMMENT 'Primary telephone number for the control center contact point.',
    `control_center_manager` STRING COMMENT 'Name of the individual responsible for overall control center management.',
    `country_code` STRING COMMENT 'Three‑letter ISO country code of the control center location.',
    `created_timestamp` TIMESTAMP COMMENT 'Timestamp when the control center record was first created in the data lake.',
    `data_source_system` STRING COMMENT 'Name of the source operational system (e.g., SCADA, EMS) that provides data for this record.',
    `decommission_date` DATE COMMENT 'Date the control center was retired or decommissioned (null if still active).',
    `control_center_description` STRING COMMENT 'Free‑form description of the control centers purpose and capabilities.',
    `established_date` DATE COMMENT 'Date the control center became operational.',
    `grid_area` STRING COMMENT 'Electrical grid area or balancing authority the control center serves.',
    `is_critical` BOOLEAN COMMENT 'Indicates whether the control center is designated as critical for grid reliability.',
    `last_maintenance_timestamp` TIMESTAMP COMMENT 'Timestamp of the most recent maintenance activity.',
    `latitude` DECIMAL(18,2) COMMENT 'Geographic latitude of the control center (decimal degrees).',
    `longitude` DECIMAL(18,2) COMMENT 'Geographic longitude of the control center (decimal degrees).',
    `maintenance_cycle_days` STRING COMMENT 'Planned interval in days between routine maintenance events.',
    `control_center_name` STRING COMMENT 'Human‑readable name of the control center.',
    `operational_mode` STRING COMMENT 'Mode in which the control center operates.',
    `primary_operator` STRING COMMENT 'Organization or business unit responsible for operating the control center.',
    `region_code` STRING COMMENT 'Internal code representing the geographic or operational region.',
    `state` STRING COMMENT 'State or province of the control center location.',
    `control_center_status` STRING COMMENT 'Current operational status of the control center.',
    `timezone` STRING COMMENT 'IANA timezone identifier for the control center location.',
    `control_center_type` STRING COMMENT 'Category of control center (e.g., primary, regional, backup).',
    `updated_timestamp` TIMESTAMP COMMENT 'Timestamp of the most recent update to the control center record.',
    `voltage_level_kv` DECIMAL(18,2) COMMENT 'Nominal voltage level served by the control center.',
    `zip_code` STRING COMMENT 'Postal/ZIP code for the control center address.',
    CONSTRAINT pk_control_center PRIMARY KEY(`control_center_id`)
) COMMENT 'Master reference table for control_center. Referenced by control_center_id.';

